:root {
  --st3-white: #ffffff;
  --st3-gray-50: #fbfbfd;
  --st3-gray-100: #f5f5f7;
  --st3-gray-200: #e8e8ed;
  --st3-gray-300: #d2d2d7;
  --st3-gray-500: #86868b;
  --st3-gray-600: #6e6e73;
  --st3-black: #1d1d1f;
  --st3-black-pure: #000000;
  --st3-accent: #fdb73e;
  --st3-accent-hover: #f4a91c;

  --st3-header-height: 48px;
  --st3-content-width: 1200px;

  --st3-radius-sm: 12px;
  --st3-radius-md: 18px;
  --st3-radius-lg: 28px;
  --st3-radius-pill: 999px;

  --st3-font:
    -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text",
    "Helvetica Neue", Helvetica, Arial, sans-serif;
}

html {
  background: var(--st3-white);
}

body {
  margin: 0;
  background: var(--st3-white);
  color: var(--st3-black);
  font-family: var(--st3-font);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
input,
select,
textarea {
  font: inherit;
}

.st3-header,
.st3-header * {
  box-sizing: border-box;
}

.st3-header {
  position: sticky;
  z-index: 1000;
  top: 0;
  width: 100%;
  color: var(--st3-black);
}

.st3-header__bar {
  position: relative;
  z-index: 20;
  height: var(--st3-header-height);
  background: rgba(250, 250, 252, 0.88);
  border-bottom: 1px solid rgba(0, 0, 0, 0.045);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
}

.st3-header__inner {
  width: min(calc(100% - 36px), var(--st3-content-width));
  height: 100%;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 26px;
}

.st3-header__logo {
  flex: 0 0 auto;
  color: var(--st3-black);
  text-decoration: none;
  font-size: 15px;
  line-height: 1;
  font-weight: 650;
  letter-spacing: -0.035em;
}

.st3-header__nav {
  min-width: 0;
  flex: 1;
  display: flex;
  align-items: stretch;
  justify-content: center;
  height: 100%;
}

.st3-header__nav-item {
  appearance: none;
  height: 100%;
  padding: 0 15px;
  border: 0;
  background: transparent;
  color: var(--st3-black);
  cursor: pointer;
  font-size: 12px;
  font-weight: 400;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.st3-header__nav-item:hover {
  color: #000;
}

.st3-header__actions {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 4px;
}

.st3-header__icon {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--st3-black);
  text-decoration: none;
  cursor: pointer;
  transition:
    background 160ms ease,
    transform 160ms ease;
}

.st3-header__icon:hover {
  background: rgba(0, 0, 0, 0.055);
}

.st3-header__icon:active {
  transform: scale(0.94);
}

.st3-header__icon svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.65;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.st3-header__menu-button {
  display: none;
}

.st3-mega {
  position: absolute;
  z-index: 10;
  top: var(--st3-header-height);
  right: 0;
  left: 0;
  overflow: hidden;
  background: rgba(250, 250, 252, 0.985);
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
  box-shadow: 0 28px 60px rgba(0, 0, 0, 0.08);
  transform-origin: top center;
  animation: st3MegaReveal 220ms cubic-bezier(0.22, 1, 0.36, 1);
}

.st3-mega__inner {
  width: min(calc(100% - 48px), 1024px);
  min-height: 310px;
  margin: 0 auto;
  padding: 42px 0 52px;
  display: grid;
  grid-template-columns: minmax(300px, 1.25fr) minmax(180px, 0.75fr);
  gap: 80px;
}

.st3-mega__eyebrow {
  margin: 0 0 17px;
  color: var(--st3-gray-500);
  font-size: 12px;
  font-weight: 500;
}

.st3-mega__links {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 7px;
}

.st3-mega__primary-link {
  color: var(--st3-black);
  text-decoration: none;
  font-size: clamp(22px, 2.15vw, 28px);
  line-height: 1.12;
  font-weight: 600;
  letter-spacing: -0.035em;
  transition:
    color 140ms ease,
    transform 140ms ease;
}

.st3-mega__primary-link:hover {
  color: #000;
  transform: translateX(3px);
}

.st3-mega__secondary {
  padding-top: 2px;
}

.st3-mega__secondary-links {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.st3-mega__secondary-link {
  width: fit-content;
  color: var(--st3-black);
  text-decoration: none;
  font-size: 13px;
  font-weight: 550;
}

.st3-mega__secondary-link:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

.st3-mega__accent {
  color: #8a5b00;
}

.st3-header__scrim {
  position: fixed;
  z-index: 5;
  top: var(--st3-header-height);
  right: 0;
  bottom: 0;
  left: 0;
  background: rgba(0, 0, 0, 0.18);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  animation: st3Scrim 180ms ease both;
}

.st3-mobile {
  display: none;
}

.st3-button {
  min-height: 44px;
  padding: 0 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: var(--st3-radius-pill);
  background: var(--st3-accent);
  color: var(--st3-black-pure);
  text-decoration: none;
  font-weight: 600;
  cursor: pointer;
  transition:
    transform 160ms ease,
    background 160ms ease,
    box-shadow 160ms ease;
}

.st3-button:hover {
  background: var(--st3-accent-hover);
  box-shadow: 0 7px 20px rgba(253, 183, 62, 0.24);
  transform: translateY(-1px);
}

.st3-button--dark {
  background: var(--st3-black);
  color: white;
}

.st3-button--dark:hover {
  background: #000;
  box-shadow: none;
}

@keyframes st3MegaReveal {
  from {
    opacity: 0;
    transform: translateY(-10px) scaleY(0.975);
  }

  to {
    opacity: 1;
    transform: translateY(0) scaleY(1);
  }
}

@keyframes st3Scrim {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .st3-mega,
  .st3-header__scrim {
    animation: none;
  }

  .st3-button,
  .st3-header__icon,
  .st3-mega__primary-link {
    transition: none;
  }
}

@media (max-width: 900px) {
  .st3-header__inner {
    width: min(calc(100% - 24px), var(--st3-content-width));
  }

  .st3-header__nav {
    display: none;
  }

  .st3-header__actions {
    margin-left: auto;
  }

  .st3-header__desktop-only {
    display: none;
  }

  .st3-header__menu-button {
    display: inline-flex;
  }

  .st3-mega,
  .st3-header__scrim {
    display: none;
  }

  .st3-mobile {
    position: fixed;
    z-index: 999;
    top: var(--st3-header-height);
    right: 0;
    bottom: 0;
    left: 0;
    display: block;
    overflow-y: auto;
    background: var(--st3-gray-50);
    animation: st3MegaReveal 220ms cubic-bezier(0.22, 1, 0.36, 1);
  }

  .st3-mobile__inner {
    padding: 28px 28px 60px;
  }

  .st3-mobile__label {
    margin: 0 0 14px;
    color: var(--st3-gray-500);
    font-size: 12px;
  }

  .st3-mobile__links {
    display: flex;
    flex-direction: column;
  }

  .st3-mobile__link {
    padding: 11px 0;
    color: var(--st3-black);
    text-decoration: none;
    font-size: 26px;
    line-height: 1.05;
    font-weight: 600;
    letter-spacing: -0.035em;
  }

  .st3-mobile__utility {
    margin-top: 28px;
    padding-top: 24px;
    border-top: 1px solid var(--st3-gray-200);
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  .st3-mobile__utility a {
    color: var(--st3-black);
    text-decoration: none;
    font-size: 14px;
    font-weight: 550;
  }
}

/* ==========================================================
   STEREOPHONIE V3 — HOMEPAGE FOUNDATION
   ========================================================== */

.st3-home {
  overflow: hidden;
  background: #fff;
  color: var(--st3-black);
}

.st3-home__hero {
  min-height: min(760px, calc(100svh - var(--st3-header-height)));
  padding: 90px 24px 110px;
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(circle at 50% 80%, rgba(0, 0, 0, 0.035), transparent 42%),
    #f5f5f7;
  text-align: center;
}

.st3-home__hero-content {
  width: min(100%, 920px);
  margin: 0 auto;
  animation: st3HomeIntro 700ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.st3-home__eyebrow {
  margin: 0 0 16px;
  color: var(--st3-gray-600);
  font-size: 17px;
  line-height: 1.3;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.st3-home__title {
  margin: 0;
  color: #1d1d1f;
  font-size: clamp(54px, 7.3vw, 96px);
  line-height: 0.95;
  font-weight: 650;
  letter-spacing: -0.065em;
}

.st3-home__subtitle {
  width: min(100%, 620px);
  margin: 28px auto 0;
  color: var(--st3-gray-600);
  font-size: clamp(18px, 2vw, 23px);
  line-height: 1.4;
  font-weight: 400;
  letter-spacing: -0.025em;
}

.st3-home__actions {
  margin-top: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
}

.st3-home__text-link,
.st3-home__preview a {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #8a5b00;
  text-decoration: none;
  font-size: 16px;
  font-weight: 500;
}

.st3-home__text-link span,
.st3-home__preview a span {
  font-size: 22px;
  line-height: 0;
  transition: transform 150ms ease;
}

.st3-home__text-link:hover span,
.st3-home__preview a:hover span {
  transform: translateX(3px);
}

.st3-home__statement {
  padding: 125px 24px;
  background: #fff;
}

.st3-home__statement-inner {
  width: min(100%, 1080px);
  margin: 0 auto;
}

.st3-home__section-label {
  margin: 0 0 19px;
  color: var(--st3-gray-500);
  font-size: 14px;
  font-weight: 600;
}

.st3-home__statement h2 {
  width: min(100%, 900px);
  margin: 0;
  color: var(--st3-black);
  font-size: clamp(38px, 5vw, 68px);
  line-height: 1.04;
  font-weight: 600;
  letter-spacing: -0.055em;
}

.st3-home__statement h2 span {
  color: var(--st3-gray-500);
}

.st3-home__preview-grid {
  padding: 0 12px 12px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  background: #fff;
}

.st3-home__preview {
  min-height: 590px;
  padding: 65px 40px;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  border-radius: 4px;
  text-align: center;
}

.st3-home__preview > div {
  width: min(100%, 520px);
}

.st3-home__preview--light {
  background: #f5f5f7;
  color: var(--st3-black);
}

.st3-home__preview--dark {
  background: #000;
  color: #f5f5f7;
}

.st3-home__preview-eyebrow {
  margin: 0 0 9px;
  color: var(--st3-gray-500);
  font-size: 14px;
  font-weight: 600;
}

.st3-home__preview--dark .st3-home__preview-eyebrow {
  color: #a1a1a6;
}

.st3-home__preview h2 {
  margin: 0;
  font-size: clamp(34px, 4vw, 52px);
  line-height: 1;
  font-weight: 600;
  letter-spacing: -0.05em;
}

.st3-home__preview p:not(.st3-home__preview-eyebrow) {
  margin: 16px auto 21px;
  color: var(--st3-gray-600);
  font-size: 18px;
  line-height: 1.4;
}

.st3-home__preview--dark p:not(.st3-home__preview-eyebrow) {
  color: #a1a1a6;
}

.st3-home__preview--dark a {
  color: var(--st3-accent);
}

.st3-home__coming {
  padding: 110px 24px 125px;
  background: #fff;
  text-align: center;
}

.st3-home__coming > * {
  width: min(100%, 720px);
  margin-right: auto;
  margin-left: auto;
}

.st3-home__coming p {
  margin-bottom: 14px;
  color: var(--st3-gray-500);
  font-size: 14px;
  font-weight: 600;
}

.st3-home__coming h2 {
  margin-top: 0;
  margin-bottom: 20px;
  font-size: clamp(32px, 4vw, 50px);
  line-height: 1.06;
  font-weight: 600;
  letter-spacing: -0.045em;
}

.st3-home__coming span {
  display: block;
  color: var(--st3-gray-600);
  font-size: 17px;
  line-height: 1.5;
}

@keyframes st3HomeIntro {
  from {
    opacity: 0;
    transform: translateY(18px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 760px) {
  .st3-home__hero {
    min-height: 620px;
    padding: 75px 22px 90px;
  }

  .st3-home__title {
    font-size: clamp(48px, 15vw, 68px);
  }

  .st3-home__subtitle {
    font-size: 18px;
  }

  .st3-home__actions {
    gap: 18px;
  }

  .st3-home__statement {
    padding: 85px 24px;
  }

  .st3-home__preview-grid {
    grid-template-columns: 1fr;
  }

  .st3-home__preview {
    min-height: 500px;
    padding: 55px 24px;
  }

  .st3-home__coming {
    padding: 85px 24px 95px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .st3-home__hero-content {
    animation: none;
  }
}

/* ==========================================================
   STEREOPHONIE V3 — LIVE STOREFRONT HOMEPAGE
   ========================================================== */

.st3-home-live {
  background: #fff;
  color: #1d1d1f;
}

.st3-live-hero {
  position: relative;
  min-height: 690px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 96px 24px 120px;
  background: #f5f5f7;
  isolation: isolate;
}

.st3-live-hero__content {
  position: relative;
  z-index: 2;
  width: min(100%, 900px);
  text-align: center;
  animation: st3LiveHeroIn 800ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.st3-live-hero__eyebrow {
  margin: 0 0 16px;
  font-size: 17px;
  line-height: 1.3;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.st3-live-hero h1 {
  margin: 0;
  font-size: clamp(58px, 8vw, 108px);
  line-height: 0.92;
  font-weight: 650;
  letter-spacing: -0.07em;
}

.st3-live-hero__copy {
  width: min(100%, 610px);
  margin: 30px auto 0;
  color: #6e6e73;
  font-size: clamp(18px, 2vw, 22px);
  line-height: 1.45;
  letter-spacing: -0.025em;
}

.st3-live-hero__actions {
  margin-top: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
}

.st3-link-arrow,
.st3-section-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #8a5b00;
  text-decoration: none;
  font-weight: 500;
}

.st3-link-arrow span,
.st3-section-link span {
  font-size: 23px;
  line-height: 1;
  transition: transform 160ms ease;
}

.st3-link-arrow:hover span,
.st3-section-link:hover span {
  transform: translateX(3px);
}

.st3-live-hero__orb {
  position: absolute;
  z-index: 1;
  left: 50%;
  bottom: -360px;
  width: 780px;
  height: 780px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: radial-gradient(
    circle at 50% 35%,
    rgba(253, 183, 62, 0.22),
    rgba(253, 183, 62, 0.06) 38%,
    transparent 69%
  );
  filter: blur(4px);
  pointer-events: none;
}

.st3-category-section,
.st3-products-section {
  width: min(100%, 1440px);
  margin: 0 auto;
  padding: 110px 42px 20px;
}

.st3-section-heading {
  margin-bottom: 38px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
}

.st3-section-eyebrow {
  margin: 0 0 10px;
  color: #86868b;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
}

.st3-section-heading h2 {
  margin: 0;
  font-size: clamp(38px, 4.4vw, 62px);
  line-height: 1;
  font-weight: 600;
  letter-spacing: -0.055em;
}

.st3-section-description {
  margin: 14px 0 0;
  color: #6e6e73;
  font-size: 18px;
  line-height: 1.45;
}

.st3-section-link {
  flex: 0 0 auto;
  margin-bottom: 4px;
}

.st3-category-rail {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(310px, min(31vw, 420px));
  gap: 16px;
  overflow-x: auto;
  padding: 4px 2px 18px;
  scroll-snap-type: x proximity;
  scrollbar-width: none;
}

.st3-category-rail::-webkit-scrollbar {
  display: none;
}

.st3-category-card {
  position: relative;
  min-height: 470px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  border-radius: 28px;
  background: #f5f5f7;
  color: #1d1d1f;
  text-decoration: none;
  scroll-snap-align: start;
  transform: translateZ(0);
  transition:
    transform 300ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 300ms ease;
}

.st3-category-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.08);
}

.st3-category-card__copy {
  position: relative;
  z-index: 2;
  padding: 30px 30px 10px;
}

.st3-category-card__copy h3 {
  margin: 0;
  font-size: 28px;
  line-height: 1.05;
  font-weight: 600;
  letter-spacing: -0.04em;
}

.st3-category-card__copy p {
  margin: 10px 0 0;
  color: #6e6e73;
  font-size: 15px;
  line-height: 1.4;
}

.st3-category-card__visual {
  min-height: 300px;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px 20px 26px;
}

.st3-category-card__visual img {
  width: 100%;
  height: 100%;
  max-height: 310px;
  object-fit: contain;
  transition: transform 450ms cubic-bezier(0.22, 1, 0.36, 1);
}

.st3-category-card:hover .st3-category-card__visual img {
  transform: scale(1.035);
}

.st3-category-card__fallback {
  width: 190px;
  height: 190px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #fff;
}

.st3-category-card__fallback span {
  font-size: 70px;
  font-weight: 600;
  letter-spacing: -0.06em;
}

.st3-category-card__arrow {
  position: absolute;
  right: 22px;
  bottom: 22px;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #1d1d1f;
  color: #fff;
  font-size: 24px;
  line-height: 1;
  transition:
    background 180ms ease,
    transform 180ms ease;
}

.st3-category-card:hover .st3-category-card__arrow {
  background: #fdb73e;
  color: #1d1d1f;
  transform: translateX(2px);
}

.st3-product-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
}

.st3-product-card {
  min-width: 0;
}

.st3-product-card__media {
  position: relative;
  aspect-ratio: 1 / 1.04;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 26px;
  border-radius: 24px;
  background: #f5f5f7;
  text-decoration: none;
}

.st3-product-card__image {
  width: 100%;
  height: 100%;
  object-fit: contain;
  transform: scale(0.96);
  transition: transform 950ms cubic-bezier(0.22, 1, 0.36, 1);
}

.st3-product-card:hover .st3-product-card__image {
  transform: scale(1);
}

