/* ==========================================================
   V3 — FINAL MEGA MENU MOTION
   One authoritative motion layer.
   ========================================================== */

.st3-mega {
  display: block;

  visibility: hidden;
  opacity: 0;

  clip-path: inset(0 0 100% 0 round 0 0 18px 18px);

  transform: translate3d(0, -10px, 0);

  transform-origin: top center;

  pointer-events: none;

  /*
   * Disable all older keyframe animation declarations.
   * The open/closed state now owns the animation.
   */
  animation: none !important;

  transition:
    clip-path 380ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 380ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 210ms ease,
    visibility 0s linear 380ms;

  will-change: clip-path, transform, opacity;
}

.st3-mega--open {
  visibility: visible;
  opacity: 1;

  clip-path: inset(0 0 0 0 round 0);

  transform: translate3d(0, 0, 0);

  pointer-events: auto;

  transition:
    clip-path 380ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 380ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 200ms ease,
    visibility 0s;
}

.st3-mega--closed {
  visibility: hidden;
  opacity: 0;

  clip-path: inset(0 0 100% 0 round 0 0 18px 18px);

  transform: translate3d(0, -10px, 0);

  pointer-events: none;
}

/*
 * MENU CONTENT
 *
 * The panel starts moving first.
 * Text follows slightly afterward.
 */

.st3-mega__inner {
  opacity: 0;

  transform: translate3d(0, -10px, 0);

  transition:
    opacity 180ms ease,
    transform 300ms cubic-bezier(0.22, 1, 0.36, 1);

  transition-delay: 0ms;
