.st3-cat-split {
  min-height: 690px;

  margin-bottom: 14px;

  overflow: hidden;

  display: grid;

  grid-template-columns:
    minmax(0, 0.78fr)
    minmax(0, 1.22fr);

  align-items: stretch;

  border-radius: 42px;

  background: #000;

  color: #f5f5f7;
}

.st3-cat-split__copy {
  display: flex;

  flex-direction: column;

  align-items: flex-start;

  justify-content: center;

  padding: clamp(50px, 7vw, 105px);
}

.st3-cat-kicker {
  margin: 0 0 11px;

  color: #86868b;

  font-size: 13px;

  font-weight: 600;

  letter-spacing: -0.01em;
}

.st3-cat-split h2 {
  margin: 0;

  max-width: 600px;

  font-size: clamp(54px, 6vw, 90px);

  line-height: 0.94;

  font-weight: 650;

  letter-spacing: -0.065em;
}

.st3-cat-split__description {
  max-width: 470px;

  margin: 20px 0 0;

  color: rgba(255, 255, 255, 0.66);

  font-size: 19px;

  line-height: 1.45;
}

.st3-cat-split .st3-cat-actions {
  justify-content: flex-start;
}

.st3-cat-media--split {
  min-height: 690px;

  margin: 22px 22px 22px 0;

  background: #101010;

  border-radius: 32px;
}

.st3-cat-media--split img {
  max-height: 650px;
}

.st3-cat-split:hover .st3-cat-media--split img {
  transform: scale(1.03);
}

/* ==========================================================
   MULTI-CATEGORY CAMPAIGN GRID
   ========================================================== */

.st3-cat-grid {
  display: grid;

  grid-template-columns: repeat(2, minmax(0, 1fr));

  gap: 14px;
}

.st3-cat-grid .st3-reveal {
  min-width: 0;
}

.st3-cat-tile {
  position: relative;

  min-height: 690px;

  overflow: hidden;

  display: grid;

  grid-template-rows: auto 1fr;

  border-radius: 38px;

  background: #f5f5f7;

  color: #1d1d1f;

  transition:
    transform 950ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 420ms ease;
}

.st3-cat-tile--dark {
  background: #000;

  color: #f5f5f7;
}

.st3-cat-tile--wide {
  grid-column: 1 / -1;

  min-height: 750px;
}

.st3-cat-tile:hover {
  transform: translateY(-3px);

  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.08);
}

.st3-cat-tile__copy {
  position: relative;

  z-index: 2;

  width: min(calc(100% - 48px), 650px);

  margin: 0 auto;

  padding: 48px 0 22px;

  text-align: center;
}

.st3-cat-tile__copy h3 {
  margin: 0;

  font-size: clamp(44px, 4.6vw, 70px);

  line-height: 0.96;

  font-weight: 650;

  letter-spacing: -0.062em;
}

.st3-cat-tile__copy > p:not(.st3-cat-kicker) {
  max-width: 520px;

  margin: 14px auto 0;

  color: #6e6e73;

  font-size: 17px;

  line-height: 1.43;
}

.st3-cat-tile--dark .st3-cat-tile__copy > p:not(.st3-cat-kicker) {
  color: rgba(255, 255, 255, 0.62);
}

.st3-cat-tile .st3-cat-text-link {
  margin-top: 17px;
}

.st3-cat-media--tile {
  width: calc(100% - 34px);

  height: 430px;

  margin: 0 auto 17px;

  border-radius: 30px;

  background: #ffffff;
}

.st3-cat-tile--dark .st3-cat-media--tile {
  background: #101010;
}

.st3-cat-tile--wide .st3-cat-media--tile {
  height: 475px;

  width: calc(100% - 44px);
}

.st3-cat-tile:hover .st3-cat-media--tile img {
  transform: scale(1.035);
}

/* ==========================================================
   IMPORTANT:
   REMOVE OLD CATEGORY PLACEHOLDER VISUAL LANGUAGE
   ========================================================== */

.st3-category-feature-grid,
.st3-apple-category-stack,
.st3-apple-categories {
  display: none !important;
}

/* ==========================================================
   ROUNDING CONSISTENCY
   ========================================================== */

.st3-home-live .st3-button,
.st3-home-live button {
  border-radius: 999px !important;
}

.st3-home-live img {
  border-radius: 24px;
}

.st3-product-card,
.st3-product-card__media {
  border-radius: 28px;
}

.st3-home-banner {
  border-radius: 38px;
}

/* ==========================================================
   TABLET
   ========================================================== */

@media (max-width: 1000px) {
  .st3-cat-split {
    grid-template-columns: 1fr;
  }

  .st3-cat-split__copy {
    align-items: center;

    text-align: center;

    padding: 65px 35px 30px;
  }

  .st3-cat-split .st3-cat-actions {
    justify-content: center;
  }

  .st3-cat-media--split {
    min-height: 500px;

    margin: 0 22px 22px;
  }

  .st3-cat-grid {
    grid-template-columns: 1fr;
  }

  .st3-cat-tile--wide {
    grid-column: auto;
  }
}

/* ==========================================================
   MOBILE
   ========================================================== */

@media (max-width: 700px) {
  .st3-cat-world {
    width: calc(100% - 16px);

    padding: 75px 0;
  }

  .st3-cat-intro {
    margin-bottom: 38px;
  }

  .st3-cat-intro h2 {
    font-size: clamp(48px, 15vw, 68px);
  }

  .st3-cat-hero {
    min-height: 650px;

    border-radius: 28px;
  }

  .st3-cat-hero__copy {
    padding: 45px 18px 18px;
  }

  .st3-cat-hero__copy h2 {
    font-size: clamp(52px, 15vw, 72px);
  }

  .st3-cat-media--hero {
    width: calc(100% - 20px);

    height: 390px;

    margin-bottom: 10px;

    border-radius: 22px;
  }

  .st3-cat-split {
    min-height: 650px;

    border-radius: 28px;
  }

  .st3-cat-split__copy {
    padding: 50px 24px 28px;
  }

  .st3-cat-split h2 {
    font-size: clamp(50px, 14vw, 70px);
  }

  .st3-cat-media--split {
    min-height: 390px;

    margin: 0 10px 10px;

    border-radius: 22px;
  }

  .st3-cat-grid {
    gap: 8px;
  }

  .st3-cat-tile,
  .st3-cat-tile--wide {
    min-height: 590px;

    border-radius: 28px;
  }

  .st3-cat-tile__copy {
    padding: 40px 0 18px;
  }

  .st3-cat-tile__copy h3 {
    font-size: clamp(42px, 12vw, 58px);
  }

  .st3-cat-media--tile,
  .st3-cat-tile--wide .st3-cat-media--tile {
    width: calc(100% - 20px);

    height: 355px;

    margin-bottom: 10px;

    border-radius: 22px;
  }
}

/* ==========================================================
   REDUCED MOTION
   ========================================================== */

@media (prefers-reduced-motion: reduce) {
  .st3-cat-media img,
  .st3-cat-tile {
    transition: none !important;
  }
}

/* ==========================================================
   V3 CATEGORY CAMPAIGNS
   TEXT + ARTWORK = ONE SURFACE
   ========================================================== */

/*
 * Major principle:
 *
 * There is no longer a card inside a card.
 * Copy and category artwork belong to one unified campaign.
 */

.st3-cat-world {
  --st3-campaign-gap: 12px;
}

/* ----------------------------------------------------------
   FULL WIDTH LIGHT CAMPAIGN
   ---------------------------------------------------------- */

.st3-cat-hero {
  display: flex;

  flex-direction: column;

  overflow: hidden;

  min-height: 820px;

  margin-bottom: var(--st3-campaign-gap);

  border-radius: 40px;

  background: #f5f5f7;
}

.st3-cat-hero__copy {
  flex: 0 0 auto;

  padding: 58px 24px 8px;
}

/*
 * The media is no longer a secondary white card.
 */

.st3-cat-hero .st3-cat-media--hero {
  flex: 1 1 auto;

  width: 100%;

  height: auto;

  min-height: 520px;

  margin: 0;

  border-radius: 0;

  background: transparent;
}

.st3-cat-hero .st3-cat-media--hero img {
  width: 100%;

  height: 100%;

  max-height: 570px;

  padding: 18px 60px 0;

  object-fit: contain;

  border-radius: 0;
}

/* ----------------------------------------------------------
   DARK / FEATURED FULL WIDTH CAMPAIGN
   ---------------------------------------------------------- */

.st3-cat-split {
  overflow: hidden;

  margin-bottom: var(--st3-campaign-gap);

  border-radius: 40px;

  background: #000;
}

/*
 * Remove the inner framed media card.
 */

.st3-cat-split .st3-cat-media--split {
  min-height: 650px;

  margin: 0;

  border-radius: 0;

  background: transparent;
}

.st3-cat-split .st3-cat-media--split img {
  width: 100%;

  height: 100%;

  max-height: 650px;

  padding: 50px;

  object-fit: contain;

  border-radius: 0;
}

/* ----------------------------------------------------------
   TWO-UP CATEGORY CAMPAIGNS
   ---------------------------------------------------------- */

.st3-cat-grid {
  gap: var(--st3-campaign-gap);
}

.st3-cat-tile {
  position: relative;

  overflow: hidden;

  min-height: 690px;

  display: flex;

  flex-direction: column;

  border-radius: 36px;
}

/*
 * Text forms the top part of the SAME panel.
 */

.st3-cat-tile__copy {
  flex: 0 0 auto;

  padding: 45px 24px 8px;
}

/*
 * Image occupies remaining space directly on panel background.
 */

.st3-cat-tile .st3-cat-media--tile,
.st3-cat-tile--wide .st3-cat-media--tile {
  flex: 1 1 auto;

  width: 100%;

  height: auto;

  min-height: 410px;

  margin: 0;

  border-radius: 0;

  background: transparent;
}

/*
 * Absolutely no white photo-frame canvas.
 */

.st3-cat-tile .st3-cat-media--tile img,
.st3-cat-tile--wide .st3-cat-media--tile img {
  width: 100%;

  height: 100%;

  max-height: 470px;

  padding: 24px 42px 14px;

  object-fit: contain;

  border-radius: 0;
}

/*
 * Dark campaign artwork lives directly on black.
 */

.st3-cat-tile--dark .st3-cat-media--tile {
  background: transparent;
}

/*
 * No nested-placeholder card for categories without art.
 */

.st3-cat-media__empty {
  min-height: inherit;

  border-radius: 0;

  background: transparent;
}

/* ----------------------------------------------------------
   CAMPAIGN VISUAL HOVER
   ---------------------------------------------------------- */

.st3-cat-hero,
.st3-cat-split,
.st3-cat-tile {
  isolation: isolate;
}

.st3-cat-hero img,
.st3-cat-split img,
.st3-cat-tile img {
  transform: translateZ(0);

  transition: transform 720ms cubic-bezier(0.22, 1, 0.36, 1);
}

@media (hover: hover) {
  .st3-cat-hero:hover img,
  .st3-cat-split:hover img,
  .st3-cat-tile:hover img {
    transform: scale(1.025);
  }
}

/* ----------------------------------------------------------
   PRODUCT CARDS
   TRANSPARENT ARTWORK SHOULD LIVE ON CARD SURFACE
   ---------------------------------------------------------- */

.st3-product-card__media {
  overflow: hidden;

  background: #f5f5f7;

  border-radius: 28px;
}

.st3-product-card__image {
  width: 100%;

  height: 100%;

  object-fit: contain;

  background: transparent !important;
}

/* ----------------------------------------------------------
   PRODUCT PAGE
   TRANSPARENT IMAGE SURFACE
   ---------------------------------------------------------- */

.st3-product-gallery,
.st3-product-gallery__media,
.st3-product-gallery__stage {
  background: #f5f5f7;
}

.st3-product-gallery img,
.st3-product-page img {
  background: transparent !important;
}

/* ----------------------------------------------------------
   MOBILE
   ---------------------------------------------------------- */

@media (max-width: 700px) {
  .st3-cat-world {
    --st3-campaign-gap: 8px;
  }

  .st3-cat-hero {
    min-height: 650px;

    border-radius: 28px;
  }

  .st3-cat-hero__copy {
    padding: 42px 18px 8px;
  }

  .st3-cat-hero .st3-cat-media--hero {
    min-height: 380px;
  }

  .st3-cat-hero .st3-cat-media--hero img {
    padding: 15px 20px 0;
  }

  .st3-cat-split {
    border-radius: 28px;
  }

  .st3-cat-split .st3-cat-media--split {
    min-height: 390px;
  }

  .st3-cat-split .st3-cat-media--split img {
    padding: 24px;
  }

  .st3-cat-tile {
    min-height: 570px;

    border-radius: 28px;
  }

  .st3-cat-tile__copy {
    padding: 38px 16px 4px;
  }

  .st3-cat-tile .st3-cat-media--tile,
  .st3-cat-tile--wide .st3-cat-media--tile {
    min-height: 340px;
  }

  .st3-cat-tile .st3-cat-media--tile img,
  .st3-cat-tile--wide .st3-cat-media--tile img {
    padding: 15px 22px 8px;
  }
}

/* ==========================================================
   STEREOPHONIE V3 — OFFICIAL BRAND LOCKUP
   ========================================================== */

.st3-header__logo {
  width: 132px;
  min-width: 132px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  overflow: visible;
}

.st3-brand-logo {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  line-height: 0;
}

.st3-brand-logo__image {
  width: auto;
  height: 30px;
  max-width: 100%;
  display: block;
  object-fit: contain;
  object-position: left center;
}

.st3-footer .st3-brand-logo__image {
  height: 42px;
  max-width: min(250px, 100%);
}

@media (max-width: 900px) {
  .st3-header__logo {
    width: 116px;
    min-width: 116px;
  }

  .st3-brand-logo__image {
    height: 27px;
  }
}

/* ==========================================================
   STEREOPHONIE V3 — HERO ARTWORK REFINEMENT
   Removes previous yellow sphere.
   Replaces it with restrained Apple-inspired dimensional art.
   ========================================================== */

.st3-live-hero__orb {
  position: absolute;
  right: clamp(28px, 7vw, 120px);
  top: 50%;
  width: clamp(330px, 36vw, 540px);
  aspect-ratio: 1.08;
  border-radius: 48px;
  transform: translateY(-50%) rotate(-5deg);
  overflow: hidden;
  pointer-events: none;
  opacity: 1;

  background: linear-gradient(
    145deg,
    rgba(255, 255, 255, 0.96) 0%,
    rgba(242, 242, 244, 0.92) 40%,
    rgba(224, 224, 228, 0.72) 100%
  );

  box-shadow:
    0 38px 90px rgba(0, 0, 0, 0.09),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);

  filter: none;
}

.st3-live-hero__orb::before {
  content: "";
  position: absolute;
  width: 72%;
  height: 72%;
  left: -11%;
  top: -5%;
  border-radius: 42px;
  transform: rotate(18deg);

  background: linear-gradient(145deg, #202023 0%, #3c3c3f 48%, #111113 100%);

  box-shadow: 0 35px 70px rgba(0, 0, 0, 0.22);
}

.st3-live-hero__orb::after {
  content: "";
  position: absolute;
  width: 63%;
  height: 54%;
  right: -5%;
  bottom: 6%;
  border-radius: 38px;
  transform: rotate(-12deg);

  background:
    radial-gradient(
      circle at 38% 35%,
      rgba(253, 183, 62, 0.52),
      rgba(253, 183, 62, 0.14) 35%,
      transparent 68%
    ),
    linear-gradient(150deg, rgba(52, 52, 55, 0.98), rgba(20, 20, 22, 0.98));

  box-shadow: 0 30px 75px rgba(0, 0, 0, 0.22);
}

/*
 * Add a subtle glass highlight instead of a giant mustard sphere.
 */
.st3-live-hero {
  isolation: isolate;
}

.st3-live-hero__content {
  position: relative;
  z-index: 3;
}

@media (max-width: 900px) {
  .st3-live-hero__orb {
    width: min(68vw, 390px);
    right: -110px;
    top: 61%;
    opacity: 0.48;
    border-radius: 36px;
  }
}

@media (max-width: 640px) {
  .st3-live-hero__orb {
    width: 330px;
    right: -180px;
    opacity: 0.3;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .st3-live-hero__orb {
    animation: st3HeroArtworkFloat 9s ease-in-out infinite;
  }
}

@keyframes st3HeroArtworkFloat {
  0%,
  100% {
    transform: translateY(-50%) rotate(-5deg) translate3d(0, 0, 0);
  }

  50% {
    transform: translateY(calc(-50% - 8px)) rotate(-3deg) translate3d(0, 0, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .st3-live-hero__orb {
    animation: none;
  }
}

/* ==========================================================
   STEREOPHONIE V3 — EDITORIAL ART REFINEMENT
   Removes the previous large mustard/yellow sphere treatment.
   ========================================================== */

.st3-live-hero__orb {
  opacity: 0 !important;
  visibility: hidden !important;
  animation: none !important;
}

/*
 * Any editorial / promotional dark card that previously
 * depended on the oversized yellow glow keeps the premium
 * dark surface but receives a much quieter depth treatment.
 */

.st3-home-live
  :is(
    .st3-editorial,
    .st3-promo,
    .st3-promo-card,
    .st3-editorial-card,
    .st3-store-promo,
    .st3-feature-banner
  ) {
  position: relative;
  isolation: isolate;
  overflow: hidden;
}

.st3-home-live
  :is(
    .st3-editorial,
    .st3-promo,
    .st3-promo-card,
    .st3-editorial-card,
    .st3-store-promo,
    .st3-feature-banner
  )::after {
  content: "";
  position: absolute;
  z-index: -1;
  right: -8%;
  top: 15%;
  width: min(36vw, 430px);
  aspect-ratio: 1;
  border-radius: 36%;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.055),
    rgba(255, 255, 255, 0.008)
  );
  border: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: 0 50px 100px rgba(0, 0, 0, 0.22);
  transform: rotate(-14deg);
  pointer-events: none;
}

/* ==========================================================
   STEREOPHONIE V3 — SHOPPING ASSISTANT
   ========================================================== */

.st3-ai-launcher,
.st3-ai-panel,
.st3-ai-panel * {
  box-sizing: border-box;
}

.st3-ai-launcher {
  position: fixed;
  z-index: 6000;
  right: 24px;
  bottom: 24px;

  height: 48px;
  padding: 0 18px 0 10px;

  display: inline-flex;
  align-items: center;
  gap: 10px;

  border: 1px solid rgba(0, 0, 0, 0.09);
  border-radius: 999px;

  background: rgba(255, 255, 255, 0.9);

  color: #1d1d1f;

  box-shadow:
    0 12px 34px rgba(0, 0, 0, 0.11),
    0 2px 7px rgba(0, 0, 0, 0.05);

  -webkit-backdrop-filter: saturate(180%) blur(24px);
  backdrop-filter: saturate(180%) blur(24px);

  cursor: pointer;

  transition:
    transform 200ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 200ms ease,
    background 200ms ease;
}

.st3-ai-launcher:hover {
  transform: translateY(-2px);

  box-shadow:
    0 17px 40px rgba(0, 0, 0, 0.14),
    0 3px 8px rgba(0, 0, 0, 0.05);
}

.st3-ai-launcher:active {
  transform: scale(0.97);
}

.st3-ai-launcher__icon {
  width: 30px;
  height: 30px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #1d1d1f;
  color: #fff;
}

.st3-ai-launcher__icon svg {
  width: 16px;
  height: 16px;

  fill: none;
  stroke: currentColor;
  stroke-width: 1.65;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.st3-ai-launcher__label {
  font-size: 13px;
  line-height: 1;
  font-weight: 600;
  letter-spacing: -0.015em;
}

.st3-ai-panel {
  position: fixed;
  z-index: 5999;

  right: 24px;
  bottom: 84px;

  width: min(calc(100vw - 32px), 420px);

  max-height: min(720px, calc(100dvh - 120px));

  display: flex;
  flex-direction: column;

  overflow: hidden;

  border: 1px solid rgba(0, 0, 0, 0.08);

  border-radius: 30px;

  background: rgba(250, 250, 252, 0.97);

  color: #1d1d1f;

  box-shadow:
    0 30px 90px rgba(0, 0, 0, 0.18),
    0 8px 26px rgba(0, 0, 0, 0.08);

  -webkit-backdrop-filter: saturate(180%) blur(30px);

  backdrop-filter: saturate(180%) blur(30px);

  opacity: 0;
  visibility: hidden;

  transform: translateY(14px) scale(0.975);

  transform-origin: bottom right;

  pointer-events: none;

  transition:
    opacity 180ms ease,
    transform 300ms cubic-bezier(0.22, 1, 0.36, 1),
    visibility 0s linear 300ms;
}

.st3-ai-panel--open {
  opacity: 1;
  visibility: visible;

  transform: translateY(0) scale(1);

  pointer-events: auto;

  transition:
    opacity 190ms ease,
    transform 330ms cubic-bezier(0.22, 1, 0.36, 1),
    visibility 0s;
}

.st3-ai-panel__top {
  padding: 24px 24px 20px;

  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;

  border-bottom: 1px solid rgba(0, 0, 0, 0.065);
}

.st3-ai-panel__eyebrow {
  margin: 0 0 6px;

  color: #86868b;

  font-size: 11px;
  line-height: 1.2;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.st3-ai-panel__top h2 {
  margin: 0;

  font-size: 28px;
  line-height: 1;
  font-weight: 650;
  letter-spacing: -0.045em;
}

.st3-ai-panel__close {
  width: 34px;
  height: 34px;

  flex: 0 0 auto;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  border: 0;
  border-radius: 50%;

  background: rgba(0, 0, 0, 0.055);

  color: #1d1d1f;

  cursor: pointer;
}

.st3-ai-panel__close svg {
  width: 15px;
  height: 15px;

  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
