/* ==========================================================
   STEREOPHONIE V3 — DARK EDITORIAL CARD FINAL REDESIGN
   Removes the oversized mustard/orange artwork permanently.
   Keeps a restrained, premium Apple-inspired dark treatment.
   ========================================================== */

/*
 * The homepage contains a dark editorial/promo section such as
 * "Technology for every day."
 *
 * Previous experiments added oversized mustard radial artwork.
 * This final override intentionally removes ALL large decorative
 * mustard shapes from that family of cards.
 */
.st3-home-live
  :is(
    .st3-editorial,
    .st3-promo,
    .st3-promo-card,
    .st3-editorial-card,
    .st3-store-promo,
    .st3-feature-banner
  ) {
  position: relative !important;
  isolation: isolate !important;
  overflow: hidden !important;

  /*
   * IMPORTANT:
   * Remove inherited radial / mustard background artwork.
   */
  background-image: none !important;

  background: linear-gradient(
    135deg,
    #1d1d1f 0%,
    #1b1b1d 52%,
    #202023 100%
  ) !important;

  border: 1px solid rgba(255, 255, 255, 0.045);

  box-shadow:
    0 20px 55px rgba(0, 0, 0, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

/*
 * REMOVE OLD ARTWORK.
 *
 * This deliberately kills both pseudo-elements because
 * earlier homepage iterations used either ::before or ::after
 * for the large mustard orb / panel.
 */
.st3-home-live
  :is(
    .st3-editorial,
    .st3-promo,
    .st3-promo-card,
    .st3-editorial-card,
    .st3-store-promo,
    .st3-feature-banner
  )::before,
.st3-home-live
  :is(
    .st3-editorial,
    .st3-promo,
    .st3-promo-card,
    .st3-editorial-card,
    .st3-store-promo,
    .st3-feature-banner
  )::after {
  content: none !important;
  display: none !important;
  background: none !important;
  box-shadow: none !important;
  border: 0 !important;
}

/*
 * Extra protection against the older global decorative orb.
 */
.st3-home-live .st3-live-hero__orb {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  animation: none !important;
}

/* ==========================================================
   NEW MINIMAL EDITORIAL DEPTH
   ========================================================== */

/*
 * Instead of another large object, the card now gets only a
 * restrained edge highlight. This is intentionally subtle.
 */
.st3-home-live
  :is(
    .st3-editorial,
    .st3-promo,
    .st3-promo-card,
    .st3-editorial-card,
    .st3-store-promo,
    .st3-feature-banner
  )
  > * {
  position: relative;
  z-index: 2;
}

/*
 * Give the typography a little more breathing room now that
 * there is no giant artwork competing with it.
 */
.st3-home-live
  :is(
    .st3-editorial,
    .st3-promo,
    .st3-promo-card,
    .st3-editorial-card,
    .st3-store-promo,
    .st3-feature-banner
  )
  h2 {
  max-width: 760px;
  text-wrap: balance;
}

/*
 * Slightly quieter secondary copy.
 */
.st3-home-live
  :is(
    .st3-editorial,
    .st3-promo,
    .st3-promo-card,
    .st3-editorial-card,
    .st3-store-promo,
    .st3-feature-banner
  )
  p {
  text-wrap: pretty;
}

/*
 * Keep mustard only where it belongs:
 * small interaction accents / CTA.
 */
.st3-home-live
  :is(
    .st3-editorial,
    .st3-promo,
    .st3-promo-card,
    .st3-editorial-card,
    .st3-store-promo,
    .st3-feature-banner
  )
  .st3-button {
  background: #fdb73e;
  color: #000;

