  background: #f4a91c;

  transform: translateY(-1px);

  box-shadow: 0 8px 22px rgba(253, 183, 62, 0.12);
}

/* ==========================================================
   FALLBACK CLEANUP
   Covers older promo implementations that may use a dedicated
   decorative element rather than pseudo-elements.
   ========================================================== */

.st3-home-live
  :is([class*="promo"])
  :is(
    [class*="orb"],
    [class*="halo"],
    [class*="glow"],
    [class*="sphere"],
    [class*="artwork"]
  ) {
