  }
}

/* ==========================================================
   STEREOPHONIE V3 — CLEAN TECHNOLOGY EDITORIAL BANNER
   Final override.
   No giant mustard sphere / halo / orb.
   ========================================================== */

.st3-home-banner {
  position: relative;
  isolation: isolate;

  width: min(calc(100% - 48px), 1220px);
  min-height: 430px;

  margin: 96px auto;

  padding: clamp(56px, 7vw, 90px) clamp(36px, 7vw, 88px);

  display: flex;
  align-items: center;

  overflow: hidden;

  border-radius: 32px;

  background: linear-gradient(145deg, #1d1d1f 0%, #202023 58%, #18181a 100%);

  color: #f5f5f7;

  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.08);

  transform: translateZ(0);
}

/*
 * Very restrained surface depth.
 * This is intentionally monochrome — no mustard artwork.
 */

.st3-home-banner::before {
  content: "";

  position: absolute;
  z-index: 0;

  top: -34%;
  right: -8%;

  width: min(52vw, 660px);
  aspect-ratio: 1;

  border-radius: 50%;

  background: radial-gradient(
    circle at center,
    rgba(255, 255, 255, 0.045) 0%,
    rgba(255, 255, 255, 0.018) 36%,
    transparent 69%
  );

  pointer-events: none;
}

/*
 * Subtle architectural line instead of a giant colored object.
 */

.st3-home-banner::after {
  content: "";

  position: absolute;
  z-index: 0;

  right: clamp(34px, 7vw, 92px);
  top: 50%;

  width: clamp(120px, 18vw, 240px);
  height: 1px;

  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.13),
    transparent
  );

  transform: translateY(-50%);

  pointer-events: none;
}

.st3-home-banner__copy {
  position: relative;
  z-index: 2;

  width: min(100%, 720px);

  margin: 0;
}

.st3-home-banner .st3-section-eyebrow {
  margin: 0 0 18px;

  color: #a1a1a6;

  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;

  letter-spacing: -0.015em;
}

.st3-home-banner h2 {
  width: min(100%, 700px);

  margin: 0;

  color: #f5f5f7;

  font-size: clamp(50px, 6vw, 82px);

  line-height: 0.94;

  font-weight: 620;

  letter-spacing: -0.065em;

  text-wrap: balance;
}

.st3-home-banner__copy > p:not(.st3-section-eyebrow) {
  width: min(100%, 520px);

  margin: 28px 0 0;

  color: #a1a1a6;

  font-size: clamp(17px, 1.6vw, 20px);

  line-height: 1.45;

  letter-spacing: -0.02em;

  text-wrap: pretty;
}

.st3-home-banner .st3-button {
  margin-top: 32px;

  min-height: 48px;

  padding: 0 24px;

  border: 0;
  border-radius: 999px;

  background: #fdb73e;

  color: #111;

  box-shadow: none;

  font-size: 15px;
  font-weight: 600;

  transition:
    transform 180ms cubic-bezier(0.22, 1, 0.36, 1),
    background 180ms ease,
    box-shadow 180ms ease;
}

.st3-home-banner .st3-button:hover {
  background: #f4ad2b;

  transform: translateY(-1px);

  box-shadow: 0 8px 24px rgba(253, 183, 62, 0.12);
}

.st3-home-banner .st3-button:active {
  transform: translateY(0) scale(0.98);
}

/*
 * Absolute safeguard:
 * should an old cached build or future JSX revision restore this
 * decorative object, it still cannot appear.
 */

.st3-home-banner__shape {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;

  width: 0 !important;
  height: 0 !important;

  background: none !important;
  box-shadow: none !important;
}

/* Tablet */

@media (max-width: 900px) {
  .st3-home-banner {
    width: min(calc(100% - 32px), 1220px);

    min-height: 390px;

    margin: 72px auto;

    padding: 58px 42px;

    border-radius: 28px;
  }

  .st3-home-banner::after {
    display: none;
  }

  .st3-home-banner::before {
    right: -30%;
    opacity: 0.7;
  }
}

/* Mobile */

@media (max-width: 640px) {
  .st3-home-banner {
    width: calc(100% - 24px);

    min-height: auto;

    margin: 54px auto;

    padding: 46px 26px 50px;

    border-radius: 26px;
  }

  .st3-home-banner h2 {
    font-size: clamp(44px, 13vw, 62px);

    line-height: 0.96;
  }

  .st3-home-banner__copy > p:not(.st3-section-eyebrow) {
    margin-top: 22px;

    font-size: 17px;
  }

  .st3-home-banner .st3-button {
    margin-top: 27px;
  }

  .st3-home-banner::before {
    top: auto;
    right: -55%;
    bottom: -40%;

    width: 430px;

    opacity: 0.45;
  }
}

@media (prefers-reduced-motion: reduce) {
  .st3-home-banner,
  .st3-home-banner *,
  .st3-home-banner::before,
  .st3-home-banner::after {
    animation: none !important;
    transition: none !important;
  }
}

/* ==========================================================
   STEREOPHONIE V3 — STOREFRONT POLISH 2026
   Product presentation + homepage rhythm + premium footer
   ========================================================== */

/* ----------------------------------------------------------
   HOMEPAGE PRODUCT SECTIONS
   ---------------------------------------------------------- */

.st3-products-section {
  width: min(calc(100% - 48px), 1360px);

  margin: 0 auto;

  padding: 116px 0 28px;
}

.st3-products-section--soft {
  width: 100%;

  max-width: none;

  margin: 78px 0 0;

  padding: 108px max(24px, calc((100vw - 1360px) / 2)) 116px;

  background: #f5f5f7;
}

.st3-products-section .st3-section-heading {
  margin-bottom: 42px;
}

.st3-products-section .st3-section-heading h2 {
  font-size: clamp(44px, 4.6vw, 68px);

  line-height: 0.98;

  letter-spacing: -0.055em;
}

.st3-products-section .st3-section-description {
  max-width: 520px;

  margin-top: 13px;

  color: #6e6e73;

  font-size: 17px;

  line-height: 1.45;
}

/* ----------------------------------------------------------
   PRODUCT GRID
   ---------------------------------------------------------- */

.st3-product-grid {
  display: grid;

  grid-template-columns: repeat(4, minmax(0, 1fr));

  gap: 18px;
}

/* ----------------------------------------------------------
   PRODUCT CARD
   ---------------------------------------------------------- */

.st3-product-card {
  position: relative;

  min-width: 0;

  overflow: hidden;

  border: 0 !important;

  border-radius: 30px !important;

  background: #f5f5f7 !important;

  box-shadow: none !important;

  transform: translateZ(0);

  transition:
    transform 950ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 420ms cubic-bezier(0.22, 1, 0.36, 1),
    background 250ms ease;
}

@media (hover: hover) {
  .st3-product-card:hover {
    transform: translateY(-5px);

    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.075) !important;
  }
}

/* ----------------------------------------------------------
   PRODUCT ARTWORK
   ---------------------------------------------------------- */

.st3-product-card__media {
  position: relative;

  width: calc(100% - 16px);

  aspect-ratio: 1 / 1;

  margin: 8px 8px 0;

  overflow: hidden;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 24px !important;

  background: #fff !important;

  isolation: isolate;
}

.st3-product-card__media::before {
  content: "";

  position: absolute;

  z-index: -1;

  left: 50%;

  bottom: 10%;

  width: 62%;

  height: 22%;

  transform: translateX(-50%);

  border-radius: 50%;

  background: radial-gradient(
    ellipse at center,
    rgba(0, 0, 0, 0.055),
    rgba(0, 0, 0, 0.018) 42%,
    transparent 72%
  );

  filter: blur(16px);

  opacity: 0.46;
}

.st3-product-card__image {
  width: 100% !important;

  height: 100% !important;

  object-fit: contain !important;

  object-position: center center;

  padding: clamp(22px, 8%, 42px);

  background: transparent !important;

  transform: scale(1);

  transition: transform 600ms cubic-bezier(0.22, 1, 0.36, 1);
}

@media (hover: hover) {
  .st3-product-card:hover .st3-product-card__image {
    transform: scale(1.035);
  }
}

/* ----------------------------------------------------------
   PRODUCT CARD COPY
   ---------------------------------------------------------- */

.st3-product-card__content,
.st3-product-card__body,
.st3-product-card__info {
  padding: 20px 20px 23px;
}

.st3-product-card h3,
.st3-product-card__title {
  margin: 0;

  color: #1d1d1f;

  font-size: 17px;

  line-height: 1.2;

  font-weight: 600;

  letter-spacing: -0.022em;
}

.st3-product-card a {
  text-decoration: none;
}

.st3-product-card__category,
.st3-product-card__brand {
  color: #86868b;

  font-size: 11px;

  font-weight: 600;

  letter-spacing: 0.015em;
}

.st3-product-card__price,
.st3-product-card__pricing {
  color: #1d1d1f;

  font-size: 14px;

  font-weight: 600;

  letter-spacing: -0.01em;
}

.st3-product-card__old-price,
.st3-product-card__compare-price {
