/*
 * Animate only elements displaying the New treatment.
 * This is intentionally restrained:
 * slight float + soft shadow breathing.
 */
.st3-product-card :is(.st3-product-card__badge, .st3-product-card__new) {
  transform-origin: center;

  animation: st3NewBadgeFloat 3.2s cubic-bezier(0.22, 1, 0.36, 1) infinite;
}

@keyframes st3NewBadgeFloat {
  0%,
