/* ==========================================================
   STEREOPHONIE V3 — AUTHORITATIVE STICKY HEADER
   Keeps storefront navigation visible while scrolling.
   ========================================================== */

.st3-header {
  position: sticky !important;
  position: -webkit-sticky !important;

  top: 0 !important;

  z-index: 5000 !important;

  width: 100%;

  background: rgba(250, 250, 252, 0.9) !important;

  border-bottom: 1px solid rgba(0, 0, 0, 0.045);

  -webkit-backdrop-filter: saturate(180%) blur(22px);

  backdrop-filter: saturate(180%) blur(22px);

  transform: translateZ(0);

  isolation: isolate;
}

/*
 * Slight premium surface depth.
 * Very subtle so it still feels clean.
 */
.st3-header::after {
  content: "";

  position: absolute;

  left: 0;
  right: 0;
  bottom: -1px;

  height: 1px;

  background: linear-gradient(
    90deg,
    transparent,
    rgba(0, 0, 0, 0.055),
    transparent
  );

  pointer-events: none;
}

/*
 * Make sure header inner content stays above its surface.
 */
.st3-header > * {
  position: relative;

  z-index: 2;
}

/*
 * Mega menu must remain directly attached to sticky header.
 */
.st3-mega {
  z-index: 5010 !important;
}

/*
 * Scrim remains underneath the menu/header.
 */
.st3-header__scrim--v3 {
  z-index: 4990 !important;
}

/*
 * Prevent any parent animation or transform from breaking
 * sticky positioning.
 */
body,
html {
  overflow-x: clip;
}

/*
 * Desktop/tablet/mobile all use the same sticky behavior.
 */
@media (max-width: 900px) {
  .st3-header {
    position: sticky !important;
    position: -webkit-sticky !important;

    top: 0 !important;

    z-index: 5000 !important;
  }
}

/*
 * Keep header transitions smooth without making the
 * navigation itself move while scrolling.
 */
@media (prefers-reduced-motion: no-preference) {
  .st3-header {
    transition:
      background-color 180ms ease,
      border-color 180ms ease,
      box-shadow 180ms ease;
  }
}

@media (prefers-reduced-motion: reduce) {
  .st3-header {
    transition: none !important;
  }
}

/* ==========================================================
   STEREOPHONIE V3 — FINAL LOCKED STOREFRONT HEADER
   AUTHORITATIVE OVERRIDE
   ========================================================== */

/*
 * IMPORTANT:
 * We intentionally use position: FIXED instead of sticky.
 *
 * Sticky can stop working when an ancestor uses:
 * overflow, transform, contain, filtering, etc.
 *
 * Fixed attaches the navigation directly to the viewport,
 * so it remains visible regardless of page scroll position.
 */

.st3-header {
  position: fixed !important;

  top: 0 !important;
  right: 0 !important;
  left: 0 !important;

  width: 100% !important;

  margin: 0 !important;

  z-index: 10000 !important;

  background: rgba(250, 250, 252, 0.92) !important;

  border-bottom: 1px solid rgba(0, 0, 0, 0.05) !important;

  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.65),
    0 8px 28px rgba(0, 0, 0, 0.035);

  -webkit-backdrop-filter: saturate(180%) blur(22px);

  backdrop-filter: saturate(180%) blur(22px);

  transform: translate3d(0, 0, 0) !important;

  isolation: isolate;

  visibility: visible !important;

  opacity: 1 !important;
}

/* ----------------------------------------------------------
   RESERVE SPACE FOR THE FIXED HEADER

   Otherwise the first section of each storefront page would
   slide underneath the fixed navigation.
   ---------------------------------------------------------- */

html {
  scroll-padding-top: var(--st3-header-height, 58px);
}

/*
 * Only pages that actually contain the Stereophonie header
 * receive this spacing.
 */
body:has(.st3-header) {
  padding-top: var(--st3-header-height, 58px) !important;
}

/* ----------------------------------------------------------
   HEADER CONTENT
   ---------------------------------------------------------- */

.st3-header__inner {
  position: relative;

  z-index: 3;
}

/* ----------------------------------------------------------
   MEGA MENUS

   Because the header is now fixed, the dropdown must remain
   visually connected to it and above the storefront.
   ---------------------------------------------------------- */

.st3-mega {
  position: fixed !important;

  top: var(--st3-header-height, 58px) !important;

  right: 0 !important;
  left: 0 !important;

  z-index: 9999 !important;
}

/* ----------------------------------------------------------
   BACKGROUND SCRIM FOR OPEN MENUS
   ---------------------------------------------------------- */

.st3-header__scrim--v3 {
  position: fixed !important;

  top: var(--st3-header-height, 58px) !important;

  right: 0 !important;
  bottom: 0 !important;
  left: 0 !important;

  width: 100% !important;

  height: calc(100dvh - var(--st3-header-height, 58px)) !important;

  z-index: 9990 !important;
}

/* ----------------------------------------------------------
   SAFARI / MOBILE SAFETY
   ---------------------------------------------------------- */

@supports (-webkit-backdrop-filter: blur(1px)) {
  .st3-header {
    -webkit-backdrop-filter: saturate(180%) blur(22px);
  }
}

@media (max-width: 900px) {
  .st3-header {
    position: fixed !important;

    top: 0 !important;

    right: 0 !important;

    left: 0 !important;

    z-index: 10000 !important;
  }

  body:has(.st3-header) {
    padding-top: var(--st3-header-height, 58px) !important;
  }
}

/* ----------------------------------------------------------
   PREVENT CONTENT FROM PAINTING ABOVE NAVIGATION
   ---------------------------------------------------------- */

.st3-home-live,
.st3-footer {
  position: relative;

  z-index: 1;
}

/* ----------------------------------------------------------
   SMOOTH PREMIUM APPEARANCE
   ---------------------------------------------------------- */

@media (prefers-reduced-motion: no-preference) {
  .st3-header {
    transition:
      background-color 180ms ease,
      box-shadow 180ms ease,
      border-color 180ms ease;
  }
}

@media (prefers-reduced-motion: reduce) {
  .st3-header {
    transition: none !important;
  }
}

