  border: 0 !important;
}

/*
 * Product image surface.
 */

.st3-shop-page :is(.st-v2-product__media, .st-card17__media) {
  overflow: hidden !important;

  min-height: 350px !important;

  margin: 10px !important;

  border: 0 !important;

  border-radius: 22px !important;

  background: #fff !important;

  background-image: none !important;
}

.st3-shop-page :is(.st-v2-product__image, .st-card17 img) {
  object-fit: contain !important;

  background: transparent !important;

  filter: none !important;
}

.st3-shop-page :is(.st-v2-product__body, .st-card17__body) {
  padding: 10px 20px 22px !important;

  background: transparent !important;
}

.st3-shop-page .st-v2-product__name {
  color: #1d1d1f !important;

  font-size: 18px !important;

  font-weight: 600 !important;

  letter-spacing: -0.025em !important;

  text-transform: none !important;
}

.st3-shop-page .st-v2-product__pricing strong {
  color: #1d1d1f !important;

  font-size: 16px !important;
}

/*
 * Remove gaming-red decorations.
 */

.st3-shop-page
  :is(.st-v2-product, .st-card17)
  :is([style*="red"], [class*="signal"]) {
  border-color: rgba(0, 0, 0, 0.07) !important;
}

/* ==========================================================
   PRODUCT DETAIL PAGE
   ========================================================== */

.st3-product-page.st-pdp17 {
  min-height: 100vh !important;

  padding-top: 0 !important;

  background: #fff !important;

  color: #1d1d1f !important;
}

/* ----------------------------------------------------------
   BREADCRUMB
   ---------------------------------------------------------- */

.st3-product-page .st-pdp17__breadcrumb {
  width: min(calc(100% - 48px), 1320px) !important;

  margin: 0 auto !important;

  padding: 38px 0 24px !important;

  border: 0 !important;

  color: #86868b !important;

  font-size: 12px !important;

  letter-spacing: 0.02em !important;
}

.st3-product-page .st-pdp17__breadcrumb a {
  color: #6e6e73 !important;
}

.st3-product-page .st-pdp17__breadcrumb strong {
  color: #1d1d1f !important;
}

/* ----------------------------------------------------------
   PRODUCT HERO
   ---------------------------------------------------------- */

.st3-product-page .st-pdp17__hero {
  width: min(calc(100% - 48px), 1320px) !important;

  margin: 0 auto 100px !important;

  display: grid !important;

  grid-template-columns:
    minmax(0, 1.12fr)
    minmax(390px, 0.88fr) !important;

  gap: 30px !important;

  align-items: start !important;
}

/* ----------------------------------------------------------
   GALLERY
   ---------------------------------------------------------- */

.st3-product-page .st-pdp17__gallery-column {
  overflow: hidden !important;

  border: 0 !important;

  border-radius: 32px !important;

  background: #f5f5f7 !important;

  background-image: none !important;

  box-shadow: none !important;
}

.st3-product-page .st-pdp17__gallery-column * {
  border-color: rgba(0, 0, 0, 0.07);
}

.st3-product-page .st-pdp17__gallery-column img {
  background: transparent !important;

  object-fit: contain !important;

  filter: none !important;
}

/*
 * Kill old graph paper/grid overlay.
 */

.st3-product-page .st-pdp17__gallery-column::before,
.st3-product-page .st-pdp17__gallery-column::after {
  content: none !important;

  display: none !important;
}

/* ----------------------------------------------------------
   PRODUCT INFORMATION PANEL
   ---------------------------------------------------------- */

.st3-product-page .st-pdp17__panel {
  position: sticky !important;

  top: calc(var(--st3-header-height, 64px) + 24px) !important;

  overflow: hidden !important;

  padding: clamp(32px, 4vw, 50px) !important;

  border: 1px solid rgba(0, 0, 0, 0.065) !important;

  border-radius: 32px !important;

  background: #f5f5f7 !important;

  background-image: none !important;

  box-shadow: none !important;
}

.st3-product-page .st-pdp17__signal {
  padding-bottom: 22px !important;

  border-bottom: 1px solid rgba(0, 0, 0, 0.07) !important;
}

.st3-product-page .st-pdp17__signal span {
  color: #6e6e73 !important;

  font-size: 12px !important;

  letter-spacing: 0.02em !important;
}

.st3-product-page .st-pdp17__identity {
  padding: 42px 0 30px !important;
}

.st3-product-page .st-pdp17__identity > p {
  margin: 0 0 12px !important;

  color: #86868b !important;

  font-size: 13px !important;

  font-weight: 600 !important;

  letter-spacing: -0.01em !important;

  text-transform: none !important;
}

.st3-product-page .st-pdp17__identity > p::before {
  display: none !important;
}

.st3-product-page .st-pdp17__identity h1 {
  margin: 0 !important;

  color: #1d1d1f !important;

  font-size: clamp(44px, 5vw, 72px) !important;

  line-height: 0.95 !important;

  font-weight: 650 !important;

  letter-spacing: -0.06em !important;

  text-transform: none !important;
}

.st3-product-page .st-pdp17__price {
  margin-top: 24px !important;
}

.st3-product-page .st-pdp17__price strong {
  color: #1d1d1f !important;

  font-size: 28px !important;

  letter-spacing: -0.035em !important;
}

.st3-product-page .st-pdp17__summary {
  padding: 28px 0 !important;

  color: #6e6e73 !important;

  font-size: 16px !important;

  line-height: 1.55 !important;

  border-top: 1px solid rgba(0, 0, 0, 0.07) !important;

  border-bottom: 1px solid rgba(0, 0, 0, 0.07) !important;
}

/* ----------------------------------------------------------
   PRODUCT FACTS
   ---------------------------------------------------------- */

.st3-product-page .st-pdp17__facts {
  margin: 28px 0 !important;

  display: grid !important;

  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;

  gap: 8px !important;

  border: 0 !important;
}

.st3-product-page .st-pdp17__facts > div {
  min-width: 0 !important;

  padding: 16px !important;

  border: 1px solid rgba(0, 0, 0, 0.06) !important;

  border-radius: 16px !important;

  background: #fff !important;
}

.st3-product-page .st-pdp17__facts > div::before {
  display: none !important;
}

.st3-product-page .st-pdp17__facts small {
  color: #86868b !important;

  font-size: 10px !important;

  letter-spacing: 0.04em !important;
}

.st3-product-page .st-pdp17__facts strong {
  color: #1d1d1f !important;

  font-size: 13px !important;

  text-transform: none !important;
}

/* ----------------------------------------------------------
   PRODUCT DETAILS
   ---------------------------------------------------------- */

.st3-product-page .st-pdp17-info {
  width: min(calc(100% - 48px), 1320px) !important;

  margin: 0 auto 110px !important;

  padding: clamp(44px, 6vw, 78px) !important;

  border: 0 !important;

  border-radius: 32px !important;

  background: #f5f5f7 !important;

  background-image: none !important;
}

.st3-product-page .st-pdp17-info__header span {
  color: #86868b !important;

  font-size: 13px !important;

  letter-spacing: 0 !important;

  text-transform: none !important;
}

.st3-product-page .st-pdp17-info__header h2 {
  margin-top: 12px !important;

  color: #1d1d1f !important;

  font-size: clamp(42px, 5vw, 70px) !important;

  line-height: 0.98 !important;

  letter-spacing: -0.055em !important;

  text-transform: none !important;
}

.st3-product-page .st-pdp17-info__grid {
  margin-top: 45px !important;

  display: grid !important;

  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;

  gap: 12px !important;
}

.st3-product-page .st-pdp17-info__grid article {
  min-height: 260px !important;

  padding: 28px !important;

  border: 0 !important;

  border-radius: 22px !important;

  background: #fff !important;
}

.st3-product-page .st-pdp17-info__number {
  color: #86868b !important;
}

.st3-product-page .st-pdp17-info__icon {
  border: 0 !important;

  background: #f5f5f7 !important;

  color: #1d1d1f !important;
}

/*
 * No red accents from PDP17.
 */

.st3-product-page
  :is(.st-pdp17__identity, .st-pdp17__facts, .st-pdp17-info)
  :is(::before, ::after) {
  border-color: rgba(0, 0, 0, 0.07) !important;
}

/* ----------------------------------------------------------
   CTA SYSTEM
   ---------------------------------------------------------- */

.st3-shop-page :is(.st-v2-button, button[type="submit"]),
.st3-product-page :is(.st-v2-button, button[type="submit"]) {
  border-radius: 999px !important;
}

.st3-shop-page .st-v2-button--signal,
.st3-product-page .st-v2-button--signal {
  border-color: var(--st3-store-accent) !important;

  background: var(--st3-store-accent) !important;

  color: #000 !important;
}

/* ==========================================================
   RESPONSIVE
   ========================================================== */

@media (max-width: 1100px) {
  .st3-shop-page .st-v2-product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .st3-product-page .st-pdp17__hero {
    grid-template-columns: 1fr !important;
  }

  .st3-product-page .st-pdp17__panel {
    position: relative !important;

    top: auto !important;
  }
}

@media (max-width: 760px) {
  .st3-shop-page .st-v2-shop-hero,
  .st3-shop-page .st-v2-shop-body {
    padding-left: 18px !important;

    padding-right: 18px !important;
  }

  .st3-shop-page .st-v2-shop-hero .st-v2-container,
  .st3-shop-page .st-v2-shop-body > .st-v2-container {
    width: 100% !important;
  }

  .st3-shop-page .st-v2-shop-hero h1 {
    font-size: clamp(52px, 16vw, 76px) !important;
  }

  .st3-shop-page .st-v2-shop-layout {
    display: block !important;
  }

  .st3-shop-page .st-v2-product-grid {
    grid-template-columns: 1fr !important;
  }

  .st3-product-page .st-pdp17__breadcrumb,
  .st3-product-page .st-pdp17__hero,
  .st3-product-page .st-pdp17-info {
    width: calc(100% - 28px) !important;
  }

  .st3-product-page .st-pdp17__hero {
    gap: 14px !important;

    margin-bottom: 65px !important;
  }

  .st3-product-page .st-pdp17__gallery-column,
  .st3-product-page .st-pdp17__panel,
  .st3-product-page .st-pdp17-info {
    border-radius: 26px !important;
  }

  .st3-product-page .st-pdp17__panel {
    padding: 28px 22px !important;
  }

  .st3-product-page .st-pdp17__identity h1 {
    font-size: clamp(42px, 13vw, 62px) !important;
  }

  .st3-product-page .st-pdp17__facts {
    grid-template-columns: 1fr !important;
  }

  .st3-product-page .st-pdp17-info {
    padding: 38px 20px !important;
  }

  .st3-product-page .st-pdp17-info__grid {
    grid-template-columns: 1fr !important;
  }
}

/* ----------------------------------------------------------
   MOTION ACCESSIBILITY
   ---------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
  .st3-shop-page *,
  .st3-product-page * {
    transition-duration: 0.001ms !important;

    animation-duration: 0.001ms !important;

    animation-iteration-count: 1 !important;
  }
}

/* ==========================================================
   STEREOPHONIE V3 — SHOP + PRODUCT PAGE
   AUTHORITATIVE VISUAL MIGRATION
   2026-08-19

   Purpose:
   - visually retire the old arcade / database presentation
   - preserve all existing shop/product functionality
   - align /shop and /shop/[slug] with V3 homepage
   ========================================================== */

/* ==========================================================
   SHARED PAGE FOUNDATION
   ========================================================== */

.st3-shop-page,
.st3-product-page {
  --st3-store-ink: #1d1d1f;
  --st3-store-muted: #6e6e73;
  --st3-store-soft: #f5f5f7;
  --st3-store-card: #f7f7f8;
  --st3-store-line: rgba(0, 0, 0, 0.07);
  --st3-store-accent: #fdb73e;
  --st3-store-accent-hover: #f4aa21;

  background: #fff !important;
  color: var(--st3-store-ink) !important;

  min-height: 100vh;

  font-family:
    -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text",
    "Helvetica Neue", Arial, sans-serif !important;
}

/*
 * Remove the visual vocabulary of the previous
 * red / black hardware-database iteration.
 */
.st3-shop-page *,
.st3-product-page * {
  text-shadow: none;
}

/* ==========================================================
   SHOP — HERO
   ========================================================== */

.st3-shop-page .st-v2-shop-hero {
  position: relative;

  padding: clamp(76px, 9vw, 128px) 24px clamp(62px, 7vw, 100px) !important;

  background: linear-gradient(180deg, #f5f5f7 0%, #fafafa 100%) !important;

  border: 0 !important;
  overflow: hidden;
}

.st3-shop-page .st-v2-shop-hero::before {
  content: "";

  position: absolute;
  right: clamp(-160px, -7vw, -50px);
  top: 50%;

  width: clamp(300px, 38vw, 570px);
  aspect-ratio: 1;

  transform: translateY(-50%);

  border-radius: 50%;

  background: radial-gradient(
    circle,
    rgba(253, 183, 62, 0.075) 0%,
    rgba(253, 183, 62, 0.025) 40%,
    transparent 70%
  );

  pointer-events: none;
}

.st3-shop-page .st-v2-shop-hero .st-v2-container {
  position: relative;
  z-index: 1;

  width: min(calc(100% - 48px), 1360px) !important;
  max-width: 1360px !important;

  margin: 0 auto !important;
}

/* Breadcrumb */

.st3-shop-page .st-v2-shop-hero__crumb {
  margin-bottom: 44px !important;

  color: #86868b !important;

  font-size: 12px !important;
  line-height: 1.4 !important;
  font-weight: 550 !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
}

.st3-shop-page .st-v2-shop-hero__crumb a {
  color: inherit !important;
  text-decoration: none;
}

/* Main shop intro */

.st3-shop-page .st-v2-shop-hero__main {
  display: grid !important;

  grid-template-columns:
    minmax(0, 1.4fr)
    minmax(300px, 0.6fr) !important;

  align-items: end !important;
  gap: clamp(48px, 8vw, 120px) !important;
}

.st3-shop-page .st-v2-shop-hero .st-v2-kicker {
  margin: 0 0 16px !important;

  color: #86868b !important;

  font-size: 14px !important;
  line-height: 1.3 !important;
  font-weight: 600 !important;
  letter-spacing: -0.015em !important;
  text-transform: none !important;
}

.st3-shop-page .st-v2-shop-hero .st-v2-kicker::before,
.st3-shop-page .st-v2-shop-hero .st-v2-kicker::after {
  display: none !important;
}

.st3-shop-page .st-v2-shop-hero h1 {
  max-width: 820px;

  margin: 0 !important;

  color: #1d1d1f !important;

  font-size: clamp(54px, 7vw, 100px) !important;

  line-height: 0.92 !important;
  font-weight: 650 !important;
  letter-spacing: -0.07em !important;

  text-transform: none !important;
}

.st3-shop-page .st-v2-shop-hero h1 span {
  color: inherit !important;
}

/* Old status database boxes become one soft information card */

.st3-shop-page .st-v2-shop-hero__status {
  overflow: hidden;

  display: grid !important;
  grid-template-columns: repeat(3, 1fr) !important;

  border: 1px solid var(--st3-store-line) !important;

  border-radius: 24px !important;

  background: rgba(255, 255, 255, 0.72) !important;

  box-shadow: 0 14px 42px rgba(0, 0, 0, 0.035) !important;

  -webkit-backdrop-filter: blur(18px) saturate(160%);
  backdrop-filter: blur(18px) saturate(160%);
}

.st3-shop-page .st-v2-shop-hero__status > div {
  min-width: 0;

  padding: 22px 20px !important;

  border: 0 !important;
}

.st3-shop-page .st-v2-shop-hero__status > div + div {
  border-left: 1px solid var(--st3-store-line) !important;
}

.st3-shop-page .st-v2-shop-hero__status span {
  display: block;

  margin-bottom: 7px;

  color: #86868b !important;

  font-size: 10px !important;
  font-weight: 600 !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
}

.st3-shop-page .st-v2-shop-hero__status strong {
  color: #1d1d1f !important;

  font-size: 16px !important;
  font-weight: 600 !important;
  letter-spacing: -0.025em !important;
  text-transform: none !important;
}

/* Kill old ticker / green terminal vocabulary */

.st3-shop-page .st-v2-shop-hero__ticker {
  display: none !important;
}

/* ==========================================================
   SHOP — BODY / SEARCH / FILTERS
   ========================================================== */

.st3-shop-page .st-v2-shop-body {
  padding: 72px 24px 120px !important;

  background: #fff !important;
}

.st3-shop-page .st-v2-shop-body > .st-v2-container {
  width: min(calc(100% - 48px), 1360px) !important;

  max-width: 1360px !important;

  margin: 0 auto !important;
}

/* Search bar */

.st3-shop-page .st-v2-catalog-tools {
  margin-bottom: 42px !important;

  padding: 0 !important;

  border: 0 !important;
  background: transparent !important;
}

.st3-shop-page .st-v2-catalog-search {
  min-height: 58px !important;

  overflow: hidden;

  border: 1px solid rgba(0, 0, 0, 0.09) !important;

  border-radius: 999px !important;

  background: #f5f5f7 !important;
}

.st3-shop-page .st-v2-catalog-search input {
  color: #1d1d1f !important;

  background: transparent !important;

  font-size: 15px !important;
}

.st3-shop-page .st-v2-catalog-search button {
  height: 46px !important;

  margin-right: 6px !important;
  padding: 0 24px !important;

  border: 0 !important;
  border-radius: 999px !important;

  background: var(--st3-store-accent) !important;

  color: #000 !important;

  font-weight: 600 !important;

  text-transform: none !important;
  letter-spacing: -0.01em !important;

  transition:
    transform 180ms cubic-bezier(0.22, 1, 0.36, 1),
    background 180ms ease !important;
}

.st3-shop-page .st-v2-catalog-search button:hover {
  background: var(--st3-store-accent-hover) !important;

  transform: translateY(-1px);
}

/* Main shop layout */

.st3-shop-page .st-v2-shop-layout {
  display: grid !important;

  grid-template-columns: 260px minmax(0, 1fr) !important;

  gap: 48px !important;
}

/* Sidebar */

.st3-shop-page .st-v2-catalog-sidebar {
  border: 0 !important;
  background: transparent !important;

  color: #1d1d1f !important;
}

.st3-shop-page .st-v2-catalog-sidebar__title {
  padding: 0 0 20px !important;

  border-bottom: 1px solid var(--st3-store-line) !important;

  color: #1d1d1f !important;

  text-transform: none !important;
  letter-spacing: 0 !important;
}

.st3-shop-page .st-v2-catalog-panel section {
  padding: 24px 0 !important;

  border-bottom: 1px solid var(--st3-store-line) !important;

  background: transparent !important;
}

.st3-shop-page .st-v2-control-label {
  color: #86868b !important;

  font-size: 12px !important;
  font-weight: 600 !important;

  text-transform: none !important;
  letter-spacing: 0 !important;
}

.st3-shop-page .st-v2-catalog-panel__categories button {
  min-height: 44px;

  border-radius: 13px !important;

  color: #1d1d1f !important;

  background: transparent !important;

  text-transform: none !important;
  letter-spacing: 0 !important;

  transition: background 160ms ease !important;
}

.st3-shop-page .st-v2-catalog-panel__categories button:hover {
  background: #f5f5f7 !important;
}

.st3-shop-page .st-v2-catalog-panel__categories button.is-active {
  background: #1d1d1f !important;

  color: #fff !important;
}

/* Results heading */

.st3-shop-page .st-v2-shop-results__head {
  min-height: 52px !important;

  margin-bottom: 22px !important;
  padding-bottom: 16px !important;

  border-bottom: 1px solid var(--st3-store-line) !important;

  color: #1d1d1f !important;

  text-transform: none !important;
  letter-spacing: 0 !important;
}

.st3-shop-page .st-v2-shop-results__head span,
.st3-shop-page .st-v2-shop-results__head strong {
  color: inherit !important;
  text-transform: none !important;
  letter-spacing: 0 !important;
}

/* No terminal indicator dots */

.st3-shop-page .st-v2-led {
  display: none !important;
}

/* ==========================================================
   SHOP — EXISTING V2 PRODUCT CARDS
   Restyled without touching behavior.
   ========================================================== */

.st3-shop-page .st-v2-product-grid {
  display: grid !important;

  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;

  gap: 18px !important;
}

.st3-shop-page .st-v2-product {
  position: relative;

  overflow: hidden;

  border: 0 !important;
  border-radius: 28px !important;

  background: #f5f5f7 !important;

  box-shadow: none !important;

  transform: translate3d(0, 0, 0);

  transition:
    transform 300ms cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 300ms ease !important;
}

@media (hover: hover) {
  .st3-shop-page .st-v2-product:hover {
    transform: translateY(-5px);

    box-shadow: 0 18px 42px rgba(0, 0, 0, 0.08) !important;
  }
}

/* Remove black terminal card header */

.st3-shop-page .st-v2-product__head {
  position: absolute !important;

  z-index: 4;
  top: 16px;
  right: 16px;
  left: 16px;

  min-height: 0 !important;

  padding: 0 !important;

  border: 0 !important;
  background: transparent !important;

  pointer-events: none;
}

.st3-shop-page .st-v2-product__head > *:not(.st-v2-product__status) {
  display: none !important;
}

.st3-shop-page .st-v2-product__status {
  margin-left: auto !important;

  padding: 7px 11px !important;

  border: 1px solid rgba(0, 0, 0, 0.055) !important;

  border-radius: 999px !important;

  background: rgba(255, 255, 255, 0.9) !important;

