/* ========================================================================
   STEREOPHONIE V3 — SHOP V4
   Real retail architecture.
   This layer intentionally replaces the old database / arcade composition.
   ======================================================================== */

.st3-shop-v4 {
  position: relative;

  min-height: 100vh;

  overflow: clip;

  background: #fff;

  color: #1d1d1f;
}

/* ------------------------------------------------------------------------
   HERO
   ------------------------------------------------------------------------ */

.st3-shop-v4__hero {
  position: relative;

  overflow: hidden;

  background: linear-gradient(145deg, #f5f5f7 0%, #f7f7f8 58%, #fbfbfc 100%);
}

.st3-shop-v4__hero::after {
  content: "";

  position: absolute;

  width: clamp(300px, 38vw, 620px);

  aspect-ratio: 1;

  right: clamp(-210px, -8vw, -80px);

  top: clamp(-230px, -12vw, -90px);

  border-radius: 50%;

  pointer-events: none;

  background: radial-gradient(
    circle,
    rgba(253, 183, 62, 0.14) 0%,
    rgba(253, 183, 62, 0.055) 38%,
    transparent 70%
  );

  filter: blur(4px);
}

.st3-shop-v4__hero-inner {
  position: relative;
  z-index: 2;

  width: min(calc(100% - 48px), 1220px);

  margin: 0 auto;

  padding: clamp(56px, 7vw, 94px) 0 clamp(72px, 9vw, 120px);
}

.st3-shop-v4__breadcrumb {
  display: flex;

  align-items: center;

  gap: 8px;

  margin-bottom: clamp(58px, 7vw, 90px);

  color: #86868b;

  font-size: 12px;

  font-weight: 500;

  line-height: 1;
}

.st3-shop-v4__breadcrumb a {
  color: inherit;

  text-decoration: none;
}

.st3-shop-v4__breadcrumb a:hover {
  color: #1d1d1f;
}

.st3-shop-v4__breadcrumb svg {
  width: 12px;

  height: 12px;
}

.st3-shop-v4__hero-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1.2fr)
    minmax(340px, 0.8fr);

  align-items: end;

  gap: clamp(50px, 8vw, 120px);
}

.st3-shop-v4__eyebrow {
  margin: 0 0 18px;

  color: #86868b;

  font-size: 14px;

  font-weight: 600;

  line-height: 1.2;

  letter-spacing: -0.01em;
}

.st3-shop-v4__hero-copy h1 {
  max-width: 820px;

  margin: 0;

  color: #1d1d1f;

  font-size: clamp(56px, 6.8vw, 96px);

  font-weight: 650;

  line-height: 0.94;

  letter-spacing: -0.067em;

  text-wrap: balance;
}

.st3-shop-v4__intro {
  max-width: 610px;

  margin: 30px 0 0;

  color: #6e6e73;

  font-size: clamp(17px, 1.6vw, 21px);

  line-height: 1.48;

  letter-spacing: -0.018em;
}

.st3-shop-v4__hero-summary {
  display: grid;

  grid-template-columns: repeat(3, minmax(0, 1fr));

  overflow: hidden;

  border: 1px solid rgba(0, 0, 0, 0.055);

  border-radius: 24px;

  background: rgba(255, 255, 255, 0.74);

  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.045);

  -webkit-backdrop-filter: blur(18px);

  backdrop-filter: blur(18px);
