/* ------------------------------------------------------------------------
   TABLET
   ------------------------------------------------------------------------ */

@media (max-width: 1000px) {
  .st3-shop-v4__hero-grid {
    grid-template-columns: 1fr;
  }

  .st3-shop-v4__hero-summary {
    max-width: 650px;
  }

  .st3-shop-v4__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* ------------------------------------------------------------------------
   MOBILE
   ------------------------------------------------------------------------ */

@media (max-width: 700px) {
  .st3-shop-v4__hero-inner,
  .st3-shop-v4__catalog-inner {
    width: calc(100% - 32px);
  }

  .st3-shop-v4__hero-inner {
    padding: 42px 0 66px;
  }

  .st3-shop-v4__breadcrumb {
    margin-bottom: 44px;
  }

  .st3-shop-v4__hero-copy h1 {
    font-size: clamp(48px, 14vw, 68px);
  }

  .st3-shop-v4__intro {
    font-size: 17px;
  }

  .st3-shop-v4__hero-summary {
    grid-template-columns: 1fr;
  }

  .st3-shop-v4__hero-summary > div {
    padding: 18px 20px;
  }

  .st3-shop-v4__hero-summary > div + div {
    border-left: 0;

    border-top: 1px solid rgba(0, 0, 0, 0.055);
  }

  .st3-shop-v4__catalog-inner {
    padding: 64px 0 90px;
  }

  .st3-shop-v4__catalog-heading {
    align-items: start;

    flex-direction: column;
  }

  .st3-shop-v4__catalog-heading h2 {
    font-size: 44px;
  }

  .st3-shop-v4__controls .st-v2-catalog-tools {
    flex-direction: column !important;

    align-items: stretch !important;
  }

  .st3-shop-v4__controls .st-v2-catalog-tools__right {
    width: 100% !important;
  }

  .st3-shop-v4__grid {
    grid-template-columns: 1fr;

    gap: 18px;
  }

  .st3-shop-v4__grid .st-v2-product__media {
    height: min(92vw, 430px) !important;
  }
}

/* ------------------------------------------------------------------------
   REDUCED MOTION
   ------------------------------------------------------------------------ */

@media (prefers-reduced-motion: reduce) {
  .st3-shop-v4 *,
  .st3-shop-v4 *::before,
  .st3-shop-v4 *::after {
    scroll-behavior: auto !important;

    animation-duration: 0.01ms !important;

    animation-iteration-count: 1 !important;

    transition-duration: 0.01ms !important;
  }
}

/* ==========================================================================
   STEREOPHONIE V3 — RETAIL REDESIGN PHASE 2
   Authoritative shop + PDP layer.
   Removes remaining arcade/database architecture from visible storefront.
   ========================================================================== */

/* ==========================================================================
   SHOP — STOP LEGACY FILTER PANEL FROM FLOATING OVER THE PAGE
   ========================================================================== */

.st3-shop-page {
  --st3-retail-max: 1220px;
  --st3-retail-surface: #f5f5f7;
  --st3-retail-text: #1d1d1f;
  --st3-retail-muted: #6e6e73;
  --st3-retail-soft: #86868b;
  --st3-retail-border: rgba(0, 0, 0, 0.07);
  --st3-retail-mustard: #fdb73e;

  background: #fff !important;
  color: var(--st3-retail-text);
}

/*
 * The old component still owns all filter/query logic,
 * but it is no longer allowed to behave like a fixed arcade console.
 */

.st3-shop-page .st-v2-catalog-sidebar,
.st3-shop-page .st-filter-v10-sidebar {
  position: static !important;
  inset: auto !important;

  width: 100% !important;
  height: auto !important;
  min-height: 0 !important;
  max-height: none !important;

  margin: 0 !important;
  padding: 0 !important;

  overflow: visible !important;

  border: 0 !important;
  border-radius: 0 !important;

  background: transparent !important;
  box-shadow: none !important;

  transform: none !important;
  z-index: auto !important;
}

/*
 * Kill the old sidebar/system heading.
 */

.st3-shop-page .st-v2-catalog-sidebar__title,
.st3-shop-page
  .st-filter-v10-sidebar
  > :is(header, .st-v2-catalog-sidebar__title) {
  display: none !important;
}

/*
 * Convert filter controls into a clean horizontal retail toolbar.
 */

.st3-shop-page .st-v2-catalog-panel {
  width: 100% !important;

  display: grid !important;

  grid-template-columns: repeat(5, minmax(0, 1fr)) !important;

  gap: 10px !important;

  padding: 0 !important;

  border: 0 !important;

  background: transparent !important;
}

/*
 * Remove arcade separators/section headers.
 */

.st3-shop-page .st-v2-catalog-panel section {
  min-width: 0 !important;

  margin: 0 !important;
  padding: 0 !important;

  border: 0 !important;

  background: transparent !important;
}

.st3-shop-page .st-v2-control-label {
  display: none !important;
}

/*
 * Category / Brand / Price / availability / sort
 * become compact Apple-like filter pills/cards.
 */

.st3-shop-page
  :is(
    .st-v2-catalog-panel__categories,
    .st-v2-select,
    .st-v2-price-range,
    .st-v2-toggle
  ) {
  width: 100% !important;
}

.st3-shop-page
  :is(
    .st-v2-catalog-panel__categories button,
    .st-v2-select select,
    .st-v2-toggle,
    .st-v2-price-range
  ) {
  min-height: 54px !important;

  border: 1px solid rgba(0, 0, 0, 0.065) !important;

  border-radius: 18px !important;

  background: #f5f5f7 !important;

  color: #1d1d1f !important;

  box-shadow: none !important;

  text-transform: none !important;

  letter-spacing: 0 !important;
}

/*
 * Remove all visible legacy copy if those nodes remain.
 */

.st3-shop-page
  :is(.st-filter-v10-sidebar, .st-v2-catalog-sidebar)
  :is([data-version], [data-system], [data-status]) {
  display: none !important;
}

