/* ------------------------------------------------------------------------
   QUICK VIEW
   ------------------------------------------------------------------------ */

.st-retail-qv {
  position: fixed;
  z-index: 3000;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 28px;
  isolation: isolate;
  overflow: hidden;
  overscroll-behavior: contain;
  animation: stRetailQuickViewShellIn 320ms ease both;
}

.st-retail-qv.is-closing {
  pointer-events: none;
  animation: stRetailQuickViewShellOut 280ms ease both;
}

.st-retail-qv__backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  background: rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(12px);
}

.st-retail-qv__window {
  position: relative;
  z-index: 1;
  width: min(960px, 100%);
  max-height: min(720px, calc(100vh - 56px));
  overflow: auto;
  display: grid;
  grid-template-columns: 1.04fr 0.96fr;
  border-radius: 30px;
  background: #fff;
  box-shadow: 0 36px 100px rgba(0, 0, 0, 0.2);
  transform-origin: center;
  will-change: opacity, transform;
  animation: stRetailQuickViewWindowIn 380ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.st-retail-qv.is-closing .st-retail-qv__window {
  animation: stRetailQuickViewWindowOut 260ms cubic-bezier(0.4, 0, 1, 1) both;
}

@keyframes stRetailQuickViewShellIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes stRetailQuickViewShellOut {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes stRetailQuickViewWindowIn {
  from {
    opacity: 0;
    transform: translate3d(0, 24px, 0) scale(0.97);
    filter: blur(3px);
  }

  to {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
    filter: blur(0);
  }
}

@keyframes stRetailQuickViewWindowOut {
  from {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
    filter: blur(0);
  }

  to {
    opacity: 0;
    transform: translate3d(0, 14px, 0) scale(0.985);
    filter: blur(2px);
  }
}

