  margin-top: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border-radius: 999px;
  text-decoration: none;
  cursor: pointer;
}

.st-retail-qv__primary {
  background: #fdb73e;
  color: #111;
  font-size: 13px;
  font-weight: 650;
}

.st-retail-qv__save {
  margin-top: 9px;
  border: 1px solid rgba(0, 0, 0, 0.1);
  background: #fff;
  color: #1d1d1f;
  font-size: 13px;
}

.st-retail-qv__save svg {
  width: 16px;
  height: 16px;
}

/* ------------------------------------------------------------------------
   FILTER MODALS
   ------------------------------------------------------------------------ */

.st-retail-filter-modal,
.st-retail-filter-sheet {
  position: fixed;
  z-index: 3100;
  inset: 0;
}

.st-retail-filter-modal__backdrop,
.st-retail-filter-sheet__backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  background: rgba(0, 0, 0, 0.23);
  backdrop-filter: blur(10px);
}

.st-retail-filter-modal {
  display: grid;
  place-items: center;
  padding: 24px;
}

.st-retail-filter-modal__dialog {
  position: relative;
  z-index: 1;
  width: min(620px, 100%);
  max-height: min(720px, calc(100vh - 48px));
  overflow: auto;
  border-radius: 28px;
  background: #fff;
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.18);
}

/* Re-skin preserved modal internals. */

.st-retail-filter-modal .st-filter-v10-modal__body {
  padding: 32px !important;
  border: 0 !important;
  background: #fff !important;
}

.st-retail-filter-modal .st-filter-v10-modal__heading {
  padding: 0 0 25px !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08) !important;
}

.st-retail-filter-modal .st-filter-v10-modal__heading small {
  color: #86868b !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
}

.st-retail-filter-modal .st-filter-v10-modal__heading h2 {
  margin-top: 7px !important;
  color: #1d1d1f !important;
  font-size: 30px !important;
  line-height: 1 !important;
  letter-spacing: -0.04em !important;
  text-transform: none !important;
}

.st-retail-filter-modal .st-filter-v10-modal__heading button {
  border: 0 !important;
  border-radius: 50% !important;
  background: #f5f5f7 !important;
}

.st-retail-filter-modal .st-filter-v10-choice-list {
  margin-top: 18px !important;
  display: grid !important;
  gap: 6px !important;
}

.st-retail-filter-modal .st-filter-v10-choice-list > button {
  min-height: 56px !important;
  padding: 0 16px !important;
  border: 0 !important;
  border-radius: 14px !important;
  background: transparent !important;
  color: #1d1d1f !important;
}

.st-retail-filter-modal .st-filter-v10-choice-list > button:hover,
.st-retail-filter-modal .st-filter-v10-choice-list > button.is-active {
  background: #f5f5f7 !important;
}

.st-retail-filter-modal .st-filter-v10-choice-list small {
  display: none !important;
}

.st-retail-filter-modal .st-filter-v10-choice-list strong {
  font-size: 14px !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
}

/* ------------------------------------------------------------------------
   MOBILE FILTER SHEET
   ------------------------------------------------------------------------ */

.st-retail-filter-sheet {
  display: none;
}

.st-retail-filter-sheet__panel {
  position: absolute;
  z-index: 2;
  left: 12px;
  right: 12px;
  bottom: 12px;
  max-height: calc(100vh - 24px);
  overflow: auto;
  border-radius: 28px;
  background: #fff;
}

.st-retail-filter-sheet__panel > header {
  padding: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.st-retail-filter-sheet__panel > header div {
  display: grid;
  gap: 4px;
}

.st-retail-filter-sheet__panel > header span {
  color: #86868b;
  font-size: 12px;
}

.st-retail-filter-sheet__panel > header strong {
  font-size: 22px;
  letter-spacing: -0.03em;
}

.st-retail-filter-sheet__panel > header button {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: #f5f5f7;
}

.st-retail-filter-sheet__content {
  padding: 0 16px 20px;
  display: grid;
  gap: 7px;
}

.st-retail-filter-sheet__content > button {
  min-height: 66px;
  padding: 0 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 0;
  border-radius: 16px;
  background: #f5f5f7;
  text-align: left;
}

.st-retail-filter-sheet__content > button span {
  display: grid;
  gap: 4px;
}

.st-retail-filter-sheet__content small {
  color: #86868b;
  font-size: 11px;
}

.st-retail-filter-sheet__content strong {
  color: #1d1d1f;
  font-size: 14px;
}

.st-retail-filter-sheet__panel > footer {
  padding: 14px 16px 18px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  border-top: 1px solid rgba(0, 0, 0, 0.07);
}

.st-retail-filter-sheet__panel > footer button {
  min-height: 52px;
  border: 0;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
}

.st-retail-filter-sheet__panel > footer button:first-child {
  background: #f5f5f7;
  color: #1d1d1f;
}

.st-retail-filter-sheet__panel > footer button:last-child {
  background: #1d1d1f;
  color: #fff;
}

/* ------------------------------------------------------------------------
   RESPONSIVE
   ------------------------------------------------------------------------ */

@media (max-width: 1100px) {
  .st-retail-shop .st-v2-product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .st-retail-filters__choices {
    flex-wrap: wrap;
  }
}

@media (max-width: 820px) {
  .st-retail-filters__choices,
  .st-retail-filters__clear,
  .st-retail-filters__sort {
    display: none;
  }

  .st-retail-filters__bar {
    min-height: 58px;
  }

  .st-retail-filters__right {
    width: 100%;
    justify-content: flex-end;
  }

  .st-retail-filters__mobile {
    min-height: 44px;
    padding: 0 16px;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: 0;
    border-radius: 999px;
    background: #f5f5f7;
    color: #1d1d1f;
    font-size: 13px;
    font-weight: 600;
  }

  .st-retail-filters__mobile svg {
    width: 16px;
    height: 16px;
  }

  .st-retail-filters__mobile span {
    min-width: 21px;
    height: 21px;
    display: grid;
    place-items: center;
    border-radius: 999px;
    background: #1d1d1f;
    color: #fff;
    font-size: 10px;
  }

  .st-retail-filter-sheet {
    display: block;
  }

  .st-retail-qv__window {
    grid-template-columns: 1fr;
  }

  .st-retail-qv__visual {
    min-height: 390px;
  }
}

@media (max-width: 640px) {
  .st-retail-filters__search {
    height: 58px;
    padding-left: 16px;
  }

  .st-retail-filters__search button {
    min-width: 86px;
    height: 46px;
  }

  .st-retail-shop .st-v2-product-grid {
    grid-template-columns: 1fr !important;
    gap: 18px !important;
  }

  .st-retail-card__visual {
    height: 390px;
  }

  .st-retail-qv {
    padding: 10px;
  }

  .st-retail-qv__window {
    max-height: calc(100vh - 20px);
    border-radius: 22px;
  }

  .st-retail-qv__visual {
    min-height: 330px;
    padding: 48px;
  }

  .st-retail-qv__info {
    padding: 38px 25px 28px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .st-retail-card,
  .st-retail-card__image,
  .st-retail-card__quick,
  .st-retail-qv,
  .st-retail-qv__backdrop,
  .st-retail-qv__window {
    animation-duration: 1ms !important;
    transition: none !important;
  }
}

/* ========================================================================
   PRODUCT PAGE V3 — STRUCTURAL RETAIL DESIGN
   ======================================================================== */

.st-product-v3 {
  min-height: 100vh;
  background: #fff;
  color: #1d1d1f;
}

.st-product-v3__shell {
  width: min(calc(100% - 48px), 1280px);
  margin: 0 auto;
}

.st-product-v3__breadcrumb {
  padding: 30px 0 22px;
  display: flex;
  align-items: center;
  gap: 8px;
  color: #86868b;
  font-size: 12px;
}

.st-product-v3__breadcrumb a,
.st-product-v3__breadcrumb span {
  color: inherit;
  text-decoration: none;
}

.st-product-v3__main {
  display: grid;
  grid-template-columns:
    minmax(0, 1.08fr)
    minmax(390px, 0.92fr);
  gap: 42px;
  align-items: start;
  padding-bottom: 110px;
}

.st-product-v3__gallery,
.st-product-v3__summary {
  min-width: 0;
}

.st-product-v3__summary {
  padding: 12px 0 0;
}

.st-product-v3__availability-row {
  min-height: 48px;
  padding-bottom: 23px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}

.st-product-v3__availability {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #86868b;
  font-size: 12px;
  font-weight: 550;
}

.st-product-v3__availability i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #aaa;
}

.st-product-v3__availability.is-available {
  color: #188038;
}

.st-product-v3__availability.is-available i {
  background: #f6b43a;
}

.st-product-v3__reference {
  color: #99999e;
  font-size: 11px;
}

.st-product-v3__heading {
  padding: 48px 0 28px;
}

.st-product-v3__heading > span {
  color: #86868b;
  font-size: 13px;
}

.st-product-v3__heading h1 {
  max-width: 650px;
  margin: 14px 0 0;
  color: #1d1d1f;
  font-size: clamp(48px, 5vw, 72px);
  line-height: 0.96;
  font-weight: 650;
  letter-spacing: -0.065em;
}

.st-product-v3__price {
  margin-top: 26px;
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.st-product-v3__price strong {
  color: #1d1d1f;
  font-size: 27px;
  font-weight: 600;
  letter-spacing: -0.03em;
}

.st-product-v3__price del {
  color: #86868b;
  font-size: 15px;
}

.st-product-v3__description {
  margin: 0;
  padding: 26px 0;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  color: #6e6e73;
  font-size: 15px;
  line-height: 1.65;
}

.st-product-v3__meta {
  padding: 18px 0 26px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.st-product-v3__meta > div {
  padding: 14px;
  border-radius: 15px;
  background: #f5f5f7;
}

.st-product-v3__meta small,
.st-product-v3__meta strong {
  display: block;
}

.st-product-v3__meta small {
  color: #86868b;
  font-size: 10px;
}

.st-product-v3__meta strong {
  margin-top: 6px;
  color: #1d1d1f;
  font-size: 12px;
}

/* gallery */

.st-product-gallery-v3 {
  position: sticky;
  top: 100px;
}

.st-product-gallery-v3__stage {
  position: relative;
  min-height: 650px;
  overflow: hidden;
  display: grid;
  place-items: center;
  border-radius: 32px;
  background: #f5f5f7;
}

.st-product-gallery-v3__image {
  width: 100%;
  height: 100%;
  max-height: 590px;
  padding: 70px;
  object-fit: contain;
  filter: drop-shadow(0 26px 34px rgba(0, 0, 0, 0.06));
}

.st-product-gallery-v3__counter {
  position: absolute;
  left: 22px;
  bottom: 22px;
  padding: 10px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.95);
  color: #1d1d1f;
  font-size: 11px;
  font-weight: 600;
}

.st-product-gallery-v3__fullscreen {
  position: absolute;
  left: 50%;
  bottom: 20px;
  transform: translateX(-50%);
  min-height: 44px;
  padding: 0 17px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 0;
  border-radius: 999px;
  background: #1d1d1f;
  color: #fff;
  font-size: 12px;
  cursor: pointer;
}

.st-product-gallery-v3__fullscreen svg {
  width: 15px;
  height: 15px;
}

.st-product-gallery-v3__nav {
  position: absolute;
  right: 20px;
  bottom: 20px;
  display: flex;
  gap: 7px;
}

.st-product-gallery-v3__nav button {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: #fff;
  color: #1d1d1f;
  cursor: pointer;
}

.st-product-gallery-v3__nav svg {
  width: 18px;
  height: 18px;
}

.st-product-gallery-v3__thumbs {
  margin-top: 12px;
  display: flex;
  gap: 9px;
}

.st-product-gallery-v3__thumbs button {
  position: relative;
  width: 84px;
  height: 84px;
  overflow: hidden;
  border: 1px solid transparent;
  border-radius: 16px;
  background: #f5f5f7;
  cursor: pointer;
}

.st-product-gallery-v3__thumbs button.is-active {
  border-color: #fdb73e;
}

.st-product-gallery-v3__thumbs img {
  width: 100%;
  height: 100%;
  padding: 9px;
  object-fit: contain;
}

.st-product-gallery-v3__thumbs span {
  display: none;
}

/* purchase */

.st-purchase-v3 {
  margin-top: 6px;
  padding: 0;
  border: 0;
  background: transparent;
}

.st-purchase-v3__header {
  padding: 18px 0;
  display: flex;
  justify-content: space-between;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  font-size: 13px;
}

.st-purchase-v3__header > div {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
}

.st-purchase-v3__header small {
  color: #86868b;
}

.st-purchase-v3__led {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #f6b43a;
}

.st-purchase-v3__body {
  padding: 24px 0 0;
}

.st-purchase-v3__section {
  margin-bottom: 24px;
}

.st-purchase-v3__section-title {
  margin-bottom: 12px;
}

.st-purchase-v3__section-title > span {
  display: none;
}

.st-purchase-v3__section-title strong {
  color: #1d1d1f;
  font-size: 13px;
}

.st-purchase-v3__section-title small {
  margin-top: 3px;
  display: block;
  color: #86868b;
  font-size: 11px;
}

.st-purchase-v3__variants {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.st-purchase-v3__variants button {
  min-height: 46px;
  padding: 0 15px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(0, 0, 0, 0.11);
  border-radius: 14px;
  background: #fff;
  color: #1d1d1f;
  font-size: 12px;
  cursor: pointer;
}

.st-purchase-v3__variants button.is-active {
  border-color: #1d1d1f;
  background: #1d1d1f;
  color: #fff;
}

.st-purchase-v3__variants button.is-unavailable {
