  background: #f5f5f7;
}

.st-purchase-v3__selection small,
.st-purchase-v3__selection span {
  color: #86868b;
  font-size: 10px;
}

.st-purchase-v3__selection strong {
  display: block;
  margin-top: 4px;
}

.st-purchase-v3__selected-price strong {
  margin-top: 0;
  font-size: 20px;
}

.st-purchase-v3__specs {
  margin: 0 0 16px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  overflow: hidden;
  border: 1px solid rgba(0, 0, 0, 0.08);
  border-radius: 16px;
  background: rgba(0, 0, 0, 0.08);
}

.st-purchase-v3__specs > div {
  padding: 14px;
  background: #fff;
}

.st-purchase-v3__specs small,
.st-purchase-v3__specs strong {
  display: block;
}

.st-purchase-v3__specs small {
  color: #86868b;
  font-size: 9px;
}

.st-purchase-v3__specs strong {
  margin-top: 5px;
  color: #1d1d1f;
  font-size: 11px;
}

.st-purchase-v3__status {
  margin: 14px 0;
  padding: 15px;
  display: flex;
  align-items: center;
  gap: 11px;
  border-radius: 14px;
  background: #f5f5f7;
}

.st-purchase-v3__status > i {
