  height: 7px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #aaa;
}

.st-purchase-v3__status.is-ready > i,
.st-purchase-v3__status.is-low > i {
  background: #f6b43a;
}

.st-purchase-v3__status strong,
.st-purchase-v3__status span {
  display: block;
}

.st-purchase-v3__status strong {
  font-size: 11px;
}

.st-purchase-v3__status span {
  margin-top: 2px;
  color: #86868b;
  font-size: 10px;
}

.st-purchase-v3__quantity {
  margin: 20px 0;
  display: flex;
  align-items: end;
  justify-content: space-between;
}

.st-purchase-v3__quantity small {
  color: #86868b;
