  margin-bottom: 46px;
}

.st-product-v3__details-head span {
  color: #86868b;
  font-size: 13px;
}

.st-product-v3__details-head h2 {
  margin: 10px 0 0;
  font-size: clamp(42px, 4.5vw, 64px);
  line-height: 0.98;
  letter-spacing: -0.06em;
}

.st-product-v3__details-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}

.st-product-v3__details-grid article {
  padding: 34px;
  border-radius: 26px;
  background: #f5f5f7;
}

.st-product-v3__details-grid small {
