  font-size: 11px;
}

.st-product-v3__details-grid h3 {
  margin: 7px 0 0;
  font-size: 26px;
  letter-spacing: -0.04em;
}

.st-product-v3__overview > p,
.st-product-v3__specifications > p {
  margin: 24px 0 0;
  color: #6e6e73;
  line-height: 1.65;
}

.st-product-v3__overview dl,
.st-product-v3__specifications dl {
  margin: 28px 0 0;
}

.st-product-v3__overview dl > div,
.st-product-v3__specifications dl > div {
  padding: 12px 0;
  display: flex;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid rgba(0, 0, 0, 0.07);
}

.st-product-v3__overview dt,
.st-product-v3__specifications dt {
  color: #86868b;
  font-size: 11px;
}

.st-product-v3__overview dd,
.st-product-v3__specifications dd {
  margin: 0;
  color: #1d1d1f;
  font-size: 12px;
  font-weight: 600;
  text-align: right;
}

.st-product-v3__service-grid {
  margin-top: 18px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}

.st-product-v3__service-grid > a,
.st-product-v3__service-grid > div {
  min-height: 180px;
  padding: 26px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 16px;
  align-items: start;
  border-radius: 24px;
  background: #f5f5f7;
  color: #1d1d1f;
  text-decoration: none;
}

.st-product-v3__service-grid > div {
  grid-template-columns: auto 1fr;
}

.st-product-v3__service-grid svg {
  width: 20px;
  height: 20px;
}

.st-product-v3__service-grid span {
  display: block;
}

.st-product-v3__service-grid small,
.st-product-v3__service-grid strong,
.st-product-v3__service-grid p {
  display: block;
}

.st-product-v3__service-grid small {
  color: #86868b;
  font-size: 10px;
}

.st-product-v3__service-grid strong {
  margin-top: 7px;
  font-size: 17px;
}

.st-product-v3__service-grid p {
  margin: 8px 0 0;
  color: #6e6e73;
  font-size: 12px;
  line-height: 1.5;
}

.st-product-v3__related {
  padding: 40px 0 110px;
}

.st-product-v3__related > header {
  margin-bottom: 28px;
  display: flex;
  justify-content: space-between;
  align-items: end;
}

.st-product-v3__related header span {
  color: #86868b;
  font-size: 12px;
}

.st-product-v3__related h2 {
  margin: 6px 0 0;
  font-size: 38px;
  letter-spacing: -0.045em;
}

.st-product-v3__related header > a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #1d1d1f;
  font-size: 12px;
  text-decoration: none;
}

.st-product-v3__related-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}

/* remove old PDP if anything stale survives */

.st-product-v3 .st-pdp17,
.st-product-v3 .st-pdp17-info,
.st-product-v3 .st-pdp17-related,
.st-product-v3 .st-buy17 {
  display: none !important;
}

@media (max-width: 1050px) {
  .st-product-v3__main {
    grid-template-columns: 1fr;
  }

  .st-product-gallery-v3 {
    position: relative;
    top: auto;
  }

  .st-product-v3__summary {
    max-width: 720px;
  }

  .st-product-v3__service-grid {
    grid-template-columns: 1fr;
  }

  .st-product-v3__related-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 720px) {
  .st-product-v3__shell {
    width: min(calc(100% - 28px), 1280px);
  }

  .st-product-v3__main {
    gap: 28px;
    padding-bottom: 70px;
  }

  .st-product-gallery-v3__stage {
    min-height: 440px;
    border-radius: 22px;
  }

  .st-product-gallery-v3__image {
    padding: 42px;
  }

  .st-product-v3__heading {
    padding-top: 34px;
  }

  .st-product-v3__heading h1 {
    font-size: clamp(42px, 14vw, 60px);
  }

  .st-product-v3__meta {
    grid-template-columns: 1fr;
  }

  .st-product-v3__details {
    padding: 72px 0;
  }

  .st-product-v3__details-grid {
    grid-template-columns: 1fr;
  }

  .st-product-v3__details-grid article {
    padding: 25px;
  }

  .st-product-v3__related-grid {
    grid-template-columns: 1fr;
  }

  .st-purchase-v3__actions {
    grid-template-columns: 1fr;
  }

  .st-purchase-v3__wishlist {
    grid-column: auto;
  }
}

/* ========================================================================
   SHOP HERO REMOVAL + COMPACT RETAIL START
   ======================================================================== */

.st-retail-shop {
  padding-top: 0 !important;
}

.st-retail-shop .st3-shop-hero,
.st-retail-shop .st-v2-shop-hero,
.st-retail-shop .st3-shop-intro {
  display: none !important;
}

.st-retail-shop .st-v2-shop-body {
  padding-top: 56px !important;
}

.st-retail-shop .st-v2-container {
  width: min(calc(100% - 48px), 1280px) !important;
  margin-inline: auto !important;
}

.st-retail-shop .st-v2-shop-results__head {
  margin-bottom: 24px !important;
}

@media (max-width: 720px) {
  .st-retail-shop .st-v2-shop-body {
    padding-top: 28px !important;
  }

  .st-retail-shop .st-v2-container {
    width: min(calc(100% - 28px), 1280px) !important;
  }
}

/* STEREOPHONIE V4 MINIMAL RETAIL
   ====================================================================== */

:root {
  --st-v4-black: #171719;
  --st-v4-text: #1d1d1f;
  --st-v4-muted: #76767b;
  --st-v4-line: rgba(0, 0, 0, 0.085);
  --st-v4-soft: #f5f5f7;
  --st-v4-soft-2: #fafafa;
  --st-v4-white: #ffffff;
  --st-v4-mustard: #f6b43a;
  --st-v4-green: #2ccf66;
}

/* ======================================================================
   SHOP
   ====================================================================== */

.st-retail-shop-v4 {
  background: #fff !important;
  color: var(--st-v4-text);
  min-height: 100vh;
}

/* The old introduction must never consume layout even if stale JSX
   somehow survives a merge. */
.st-retail-shop-v4 .st-v2-shop-hero,
.st-retail-shop-v4 .st3-shop-hero,
.st-retail-shop-v4 .st3-shop-intro {
  display: none !important;
}

.st-retail-shop-v4 .st-v2-shop-body {
  padding: clamp(42px, 5vw, 76px) 0 clamp(80px, 9vw, 132px) !important;
  background: #fff !important;
}

.st-retail-shop-v4 .st-v2-container {
  width: min(calc(100% - 48px), 1220px) !important;
  max-width: none !important;
  margin-inline: auto !important;
}

.st-retail-shop-v4 .st-v2-shop-layout {
  display: block !important;
}

.st-retail-shop-v4 .st-v2-shop-layout__sidebar-space {
  display: none !important;
}

.st-retail-shop-v4 .st-v2-shop-results {
  width: 100% !important;
}

.st-retail-shop-v4 .st-v2-shop-results__head {
  margin: 0 0 28px !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
}

.st-retail-shop-v4 .st-v2-product-grid {
  width: 100% !important;
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: clamp(18px, 2vw, 26px) !important;
  align-items: start !important;
}

/* ======================================================================
   FILTERS V4
   ====================================================================== */

.st-filter-v4 {
  position: relative;
  z-index: 10;
  margin-bottom: 38px;
}

.st-filter-v4__search {
  width: 100%;
  min-height: 62px;

  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 13px;

  padding: 7px 8px 7px 20px;

  border: 1px solid var(--st-v4-line);

  border-radius: 20px;

  background: var(--st-v4-soft);

  transition:
    border-color 160ms ease,
    background 160ms ease;
}

.st-filter-v4__search:focus-within {
  border-color: rgba(0, 0, 0, 0.16);

  background: #fff;
}

.st-filter-v4__search > svg {
  width: 18px;
  height: 18px;
  color: #8c8c91;
}

.st-filter-v4__search input {
  width: 100%;
  min-width: 0;

  border: 0;
  outline: 0;

  background: transparent;

  color: var(--st-v4-text);

  font: inherit;
  font-size: 14px;
}

.st-filter-v4__search input::placeholder {
  color: #909095;
}

.st-filter-v4__clear-search {
  width: 34px;
  height: 34px;

  display: grid;
  place-items: center;

  border: 0;
  border-radius: 50%;

  background: transparent;
  color: #777;

  cursor: pointer;
}

.st-filter-v4__clear-search svg {
  width: 15px;
  height: 15px;
}

.st-filter-v4__search-button {
  min-width: 118px;
  min-height: 48px;

  padding: 0 24px;

  border: 0;
  border-radius: 15px;

  background: var(--st-v4-mustard);
  color: #111;

  font-size: 13px;
  font-weight: 650;

  cursor: pointer;

  transition:
    transform 160ms ease,
    filter 160ms ease;
}

@media (hover: hover) {
  .st-filter-v4__search-button:hover {
    filter: brightness(0.97);
    transform: translateY(-1px);
  }
}

.st-filter-v4__bar {
  margin-top: 16px;
  padding-bottom: 18px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;

  border-bottom: 1px solid var(--st-v4-line);
}

.st-filter-v4__filters {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.st-filter-v4__select,
.st-filter-v4__sort {
  position: relative;

  height: 44px;

  display: flex;
  align-items: center;

  border: 1px solid var(--st-v4-line);

  border-radius: 999px;

  background: #fff;

  overflow: hidden;
}

.st-filter-v4__select > span {
  position: absolute;
  left: 16px;
  z-index: 1;

  color: var(--st-v4-text);

  font-size: 13px;
  font-weight: 560;

  pointer-events: none;
}

.st-filter-v4__select select {
  appearance: none;

  min-width: 126px;
  height: 100%;

  padding: 0 40px 0 16px;

  border: 0;
  outline: 0;

  background: transparent;
  color: transparent;

  cursor: pointer;
}

.st-filter-v4__select svg,
.st-filter-v4__sort svg {
  position: absolute;
  right: 14px;

  width: 14px;
  height: 14px;

  pointer-events: none;
}

.st-filter-v4__pill {
  height: 44px;

  display: inline-flex;
  align-items: center;
  gap: 8px;

  padding: 0 16px;

  border: 1px solid var(--st-v4-line);

  border-radius: 999px;

  background: #fff;
  color: var(--st-v4-text);

  font-size: 13px;
  font-weight: 560;

  cursor: pointer;
}

.st-filter-v4__pill > svg {
  width: 14px;
  height: 14px;
}

.st-filter-v4__pill.is-active {
  background: var(--st-v4-black);
  border-color: var(--st-v4-black);
  color: #fff;
}

.st-filter-v4__stock-dot {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: var(--st-v4-green);
}

.st-filter-v4__sort {
  min-width: 170px;
  background: var(--st-v4-soft);
  border-color: transparent;
}

.st-filter-v4__sort > span {
  padding-left: 16px;

  color: #8b8b90;

  font-size: 12px;

  pointer-events: none;
}

.st-filter-v4__sort select {
  appearance: none;

  flex: 1;
  height: 100%;

  padding: 0 38px 0 8px;

  border: 0;
  outline: 0;

  background: transparent;
  color: var(--st-v4-text);

  font-size: 13px;
  font-weight: 590;

  cursor: pointer;
}

.st-filter-v4__price-wrap {
  position: relative;
}

.st-filter-v4__price-backdrop {
  position: fixed;
  inset: 0;
  z-index: 20;

  border: 0;
  background: transparent;
}

.st-filter-v4__price-popover {
  position: absolute;
  z-index: 30;

  top: calc(100% + 12px);
  left: 0;

  width: min(360px, calc(100vw - 32px));

  padding: 22px;

  border: 1px solid var(--st-v4-line);

  border-radius: 22px;

  background: rgba(255, 255, 255, 0.98);

  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.13);
}

.st-filter-v4__price-title {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;

  padding-bottom: 18px;

  border-bottom: 1px solid var(--st-v4-line);
}

.st-filter-v4__price-title small,
.st-filter-v4__price-title strong {
  display: block;
}

.st-filter-v4__price-title small {
  margin-bottom: 5px;

  color: var(--st-v4-muted);

  font-size: 11px;
}

.st-filter-v4__price-title strong {
  font-size: 20px;
  letter-spacing: -0.025em;
}

.st-filter-v4__price-title > button {
  width: 34px;
  height: 34px;

  display: grid;
  place-items: center;

  border: 0;
  border-radius: 50%;

  background: var(--st-v4-soft);

  cursor: pointer;
}

.st-filter-v4__price-title svg {
  width: 15px;
  height: 15px;
}

.st-filter-v4__price-fields {
  padding: 18px 0;

  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.st-filter-v4__price-fields label > span {
  display: block;

  margin: 0 0 7px;

  color: var(--st-v4-muted);

  font-size: 11px;
}

.st-filter-v4__price-fields label > div {
  min-height: 48px;

  display: flex;
  align-items: center;
  gap: 6px;

  padding: 0 13px;

  border: 1px solid var(--st-v4-line);

  border-radius: 13px;

  background: var(--st-v4-soft-2);
}

.st-filter-v4__price-fields input {
  width: 100%;
  min-width: 0;

  border: 0;
  outline: 0;

  background: transparent;

  font: inherit;
  font-weight: 600;
}

.st-filter-v4__price-range {
  color: var(--st-v4-muted);

  font-size: 11px;
}

.st-filter-v4__price-actions {
  margin-top: 18px;

  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.st-filter-v4__price-actions button {
  min-height: 44px;

  border: 0;
  border-radius: 12px;

  background: var(--st-v4-soft);

  font: inherit;
  font-size: 13px;
  font-weight: 600;

  cursor: pointer;
}

.st-filter-v4__price-actions button:last-child {
  background: var(--st-v4-mustard);
  color: #111;
}

.st-filter-v4__mobile-label {
  display: none;
}

/* ======================================================================
   PRODUCT PAGE V4
   ====================================================================== */

.st-product-v4 {
  min-height: 100vh;

  background: #fff;
  color: var(--st-v4-text);
}

.st-product-v4__shell {
  width: min(calc(100% - 48px), 1240px);

  margin: 0 auto;

  padding: 34px 0 110px;
}

.st-product-v4__breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;

  margin-bottom: 54px;

  color: #8a8a90;

  font-size: 12px;
}

.st-product-v4__breadcrumb a,
.st-product-v4__breadcrumb strong {
  color: inherit;
  font-weight: 500;
  text-decoration: none;
}

.st-product-v4__masthead {
  display: grid;

  grid-template-columns:
    minmax(0, 1.5fr)
    minmax(240px, 0.5fr);

  align-items: end;

  gap: clamp(36px, 7vw, 110px);

  padding-bottom: clamp(42px, 5vw, 70px);

  border-bottom: 1px solid var(--st-v4-line);
}

.st-product-v4__eyebrow {
  display: block;

  margin-bottom: 18px;

  color: var(--st-v4-muted);

  font-size: 13px;
}

.st-product-v4__masthead h1 {
  max-width: 820px;

  margin: 0;

  font-size: clamp(54px, 7vw, 104px);

  line-height: 0.91;

  font-weight: 630;

  letter-spacing: -0.07em;
}

.st-product-v4__masthead-copy > p {
  max-width: 720px;

  margin: 30px 0 0;

  color: #6f6f74;

  font-size: clamp(15px, 1.5vw, 18px);

  line-height: 1.58;
}

.st-product-v4__masthead-commerce {
  padding-bottom: 5px;
}

.st-product-v4__availability {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  color: #6e6e73;

  font-size: 12px;
  font-weight: 560;
}

.st-product-v4__availability i {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #aaa;
}

.st-product-v4__availability.is-available i {
  background: var(--st-v4-green);
}

.st-product-v4__masthead-price {
  margin-top: 25px;

  display: flex;
  align-items: baseline;
  gap: 12px;
}

.st-product-v4__masthead-price strong {
  font-size: clamp(28px, 3vw, 42px);

  line-height: 1;

  font-weight: 600;

  letter-spacing: -0.04em;
}

.st-product-v4__masthead-price del {
  color: #909095;

  font-size: 15px;
}

.st-product-v4__masthead-commerce > small {
  display: block;

  margin-top: 18px;

  color: #9a9a9f;

  font-size: 10px;
}

.st-product-v4__visual {
  padding: clamp(46px, 6vw, 86px) 0 clamp(62px, 8vw, 108px);
}

/* Make whatever gallery implementation is currently active behave
   like one large premium visual stage instead of the old left column. */
.st-product-v4__visual > * {
  width: 100% !important;
  max-width: none !important;
}

.st-product-v4__visual :where(.st-gallery-v3, .st-pdp17-gallery) {
  width: 100% !important;

  border: 0 !important;
  border-radius: 34px !important;

  background: var(--st-v4-soft) !important;

  box-shadow: none !important;
}

.st-product-v4__visual :where(.st-gallery-v3__stage, .st-pdp17-gallery__stage) {
  min-height: clamp(560px, 67vw, 790px) !important;

  border: 0 !important;

  background: var(--st-v4-soft) !important;
}

.st-product-v4__commerce {
  padding: clamp(62px, 7vw, 96px) 0;

  border-top: 1px solid var(--st-v4-line);

  border-bottom: 1px solid var(--st-v4-line);
}

.st-product-v4__commerce-heading {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    minmax(240px, 380px);

  align-items: end;

  gap: 40px;

  margin-bottom: 46px;
}

.st-product-v4__commerce-heading span,
.st-product-v4__information-heading span,
.st-product-v4__identity > span,
.st-product-v4__overview > span,
.st-product-v4__specs > span {
  color: var(--st-v4-muted);

  font-size: 12px;
}

.st-product-v4__commerce-heading h2,
.st-product-v4__information-heading h2 {
  margin: 8px 0 0;

  max-width: 760px;

  font-size: clamp(40px, 5vw, 70px);

  line-height: 0.98;

  font-weight: 610;

  letter-spacing: -0.055em;
}

.st-product-v4__commerce-heading p {
  margin: 0;

  color: #747479;

  font-size: 14px;
  line-height: 1.55;
}

.st-product-v4__commerce-layout {
  display: grid;

  grid-template-columns:
    minmax(0, 1.5fr)
    minmax(280px, 0.5fr);

  align-items: start;

  gap: clamp(28px, 5vw, 68px);
}

.st-product-v4__purchase {
  min-width: 0;
}

/* Flatten the purchase component into this architecture regardless
   of the temporary class namespace it currently carries. */
.st-product-v4__purchase > section {
  width: 100% !important;

  margin: 0 !important;

  border: 0 !important;

  border-radius: 0 !important;

  background: transparent !important;

  box-shadow: none !important;
}

.st-product-v4__purchase > section > header {
  padding: 0 0 20px !important;

  border-bottom: 1px solid var(--st-v4-line) !important;

  background: transparent !important;
}

.st-product-v4__identity {
  position: sticky;
  top: 105px;

  padding: 28px;

  border-radius: 24px;

  background: var(--st-v4-soft);
}

.st-product-v4__identity dl {
  margin: 24px 0 0;
}

.st-product-v4__identity dl > div {
  min-height: 48px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  border-top: 1px solid var(--st-v4-line);
}

.st-product-v4__identity dt {
  color: var(--st-v4-muted);

  font-size: 12px;
}

.st-product-v4__identity dd {
  margin: 0;

  font-size: 13px;
  font-weight: 600;

  text-align: right;
}

.st-product-v4__information {
  padding: clamp(76px, 9vw, 126px) 0;
}

.st-product-v4__information-heading {
  margin-bottom: 56px;
}

.st-product-v4__information-layout {
  display: grid;

  grid-template-columns:
