.st-purchase-v6__quantity {
  min-width: 0;
}

.st-purchase-v6__stepper {
  width: 118px;

  height: 44px;

  margin-top: 7px;

  display: grid;

  grid-template-columns: 36px 1fr 36px;

  align-items: center;

  overflow: hidden;

  border: 1px solid #dedee3;

  border-radius: 999px;

  background: #fff;
