  margin-top: 5px;

  color: #9a9aa0;

  font-size: 9px;
}

/* Buttons */

.st-purchase-v6__primary-actions {
  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 9px;
}

.st-purchase-v6__cart,
.st-purchase-v6__buy,
.st-purchase-v6__notify,
.st-purchase-v6__disabled,
.st-purchase-v6__save {
  min-height: 48px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 9px;

  border: 0;

  border-radius: 999px;

  font-size: 12px;

  font-weight: 620;

  cursor: pointer;
}

.st-purchase-v6__cart {
  background: var(--st-mustard);

  color: #171719;
}

.st-purchase-v6__buy {
  background: #1d1d1f;

  color: #fff;
}

.st-purchase-v6__notify {
  width: 100%;

  background: var(--st-mustard);

  color: #171719;
}

.st-purchase-v6__disabled {
  width: 100%;

  background: #ededf0;

  color: #88888d;

  cursor: not-allowed;
}

.st-purchase-v6__save {
  width: 100%;

  min-height: 44px;

  border: 1px solid #dcdce1;

  background: #fff;

  color: #1d1d1f;
}

.st-purchase-v6__save.is-active {
  border-color: var(--st-mustard);

  background: #fffaf0;
}

.st-purchase-v6__cart svg,
.st-purchase-v6__buy svg,
.st-purchase-v6__notify svg,
.st-purchase-v6__disabled svg,
.st-purchase-v6__save svg {
  width: 16px;

  height: 16px;

  stroke-width: 1.8;
}

/* Messages */

.st-purchase-v6__message {
  display: flex;
  align-items: center;

  gap: 8px;

  min-height: 42px;

  padding: 9px 13px;

  border-radius: 12px;

  background: #f5f5f7;

  color: #505056;

  font-size: 11px;
}

.st-purchase-v6__message.is-success {
  border-left: 3px solid var(--st-mustard);
}

.st-purchase-v6__message svg {
  width: 15px;

  height: 15px;
}

/* ============================================================
   DETAILS
   ============================================================ */

.st-product-v5__details {
  gap: clamp(50px, 8vw, 95px) !important;

  padding: 72px 0 !important;
}

.st-product-v5__details h2 {
