   ========================================================= */

/*
 * These selectors deliberately target launcher-style
 * assistant controls only.
 *
 * They cover the V3 assistant namespace while avoiding
 * content inside an opened assistant conversation.
 */

:is(
  [class*="st3"][class*="assistant"][class*="launcher"],
  [class*="st3"][class*="assistant"][class*="trigger"],
  [class*="st3"][class*="assistant"][class*="button"],
  [class*="v3"][class*="assistant"][class*="launcher"],
  [class*="v3"][class*="assistant"][class*="trigger"],
  [class*="assistant"][class*="floating"]
) {
  position: fixed;

  isolation: isolate;

  animation: st-v3-assistant-float 3.8s ease-in-out infinite !important;
}

/*
 * Breathing outer halo.
 */

:is(
  [class*="st3"][class*="assistant"][class*="launcher"],
  [class*="st3"][class*="assistant"][class*="trigger"],
  [class*="st3"][class*="assistant"][class*="button"],
  [class*="v3"][class*="assistant"][class*="launcher"],
  [class*="v3"][class*="assistant"][class*="trigger"],
  [class*="assistant"][class*="floating"]
)::before {
  content: "";

  position: absolute;

  inset: -18px;

  border-radius: 999px;

  background: radial-gradient(
    circle,
    rgba(245, 179, 53, 0.24) 0%,
    rgba(245, 179, 53, 0.13) 36%,
    rgba(245, 179, 53, 0.05) 58%,
    rgba(245, 179, 53, 0) 76%
  );

  filter: blur(5px);

  opacity: 0.42;

  transform: scale(0.92);

  z-index: -1;

  pointer-events: none;

  animation: st-v3-assistant-breathe 2.9s ease-in-out infinite !important;
}

/*
 * A second softer ring gives the launcher the layered
 * glow visible in the design without becoming neon.
 */

:is(
  [class*="st3"][class*="assistant"][class*="launcher"],
  [class*="st3"][class*="assistant"][class*="trigger"],
  [class*="st3"][class*="assistant"][class*="button"],
  [class*="v3"][class*="assistant"][class*="launcher"],
  [class*="v3"][class*="assistant"][class*="trigger"],
  [class*="assistant"][class*="floating"]
)::after {
  content: "";

  position: absolute;

  inset: -8px;

  border: 1px solid rgba(245, 179, 53, 0.17);

  border-radius: 999px;

  opacity: 0.44;

  transform: scale(0.96);

  z-index: -1;

  pointer-events: none;

  animation: st-v3-assistant-ring 2.9s ease-in-out infinite !important;
}

@keyframes st-v3-assistant-breathe {
  0%,
  100% {
    opacity: 0.28;

    transform: scale(0.88);
  }

  50% {
    opacity: 0.8;

    transform: scale(1.14);
  }
}

@keyframes st-v3-assistant-ring {
  0%,
  100% {
    opacity: 0.26;

    transform: scale(0.94);
  }

  50% {
    opacity: 0.68;

    transform: scale(1.09);
  }
}

/*
 * Very restrained vertical movement.
 *
 * Only ~4px total travel so it attracts the eye
 * without looking like a gaming UI.
 */

@keyframes st-v3-assistant-float {
  0%,
  100% {
    translate: 0 0;
  }

  50% {
    translate: 0 -4px;
  }
}

