 */
@keyframes st3AiPermanentOuterBreath {
  0%,
  100% {
    opacity: 0.13;

    transform: scale(0.82);

    filter: blur(9px);
  }

  48% {
    opacity: 0.64;

    transform: scale(1.25);

    filter: blur(14px);
  }

