button[data-st-ai-launcher="true"]:focus-visible [data-st-ai-glow="inner"],
button[data-st-ai-launcher="true"]:active [data-st-ai-glow="inner"],
button[data-st-ai-launcher="true"].st3-ai-launcher--open
  [data-st-ai-glow="inner"] {
