    infinite !important;
}

button[data-st-ai-launcher="true"]:hover,
button[data-st-ai-launcher="true"]:focus-visible,
button[data-st-ai-launcher="true"]:active,
button[data-st-ai-launcher="true"].st3-ai-launcher--open {
  animation: stActiveAiFloat 3.65s ease-in-out infinite !important;
}

@keyframes stActiveAiOuterBreath {
  0%,
  100% {
    opacity: 0.2;
    transform: scale(0.72);
    filter: blur(7px);
  }

  42% {
    opacity: 0.94;
    transform: scale(1.1);
    filter: blur(8px);
  }

  58% {
    opacity: 0.72;
    transform: scale(1.19);
    filter: blur(10px);
  }
}

@keyframes stActiveAiInnerBreath {
  0%,
  100% {
    opacity: 0.18;
    transform: scale(0.86);
  }

  48% {
    opacity: 0.77;
    transform: scale(1.1);
  }

  64% {
    opacity: 0.46;
    transform: scale(1.17);
  }
}

