/* =========================================================
   4. HEADER — PREMIUM OPEN/CLOSE
   ========================================================= */

.st3-header__nav-item,
.st3-header__icon {
  transition:
    color 180ms var(--st-active-ease),
    background-color 180ms var(--st-active-ease),
    border-color 180ms var(--st-active-ease),
    opacity 180ms var(--st-active-ease) !important;
}

/*
 * Real active mega-menu architecture from v3-header.tsx:
 * st3-mega + --open / --closing / --closed
 */
.st3-mega {
  transform-origin: 50% 0 !important;

  transition:
    opacity 260ms var(--st-active-ease),
    transform 260ms var(--st-active-ease),
    visibility 260ms linear !important;

  will-change: opacity, transform !important;
}

.st3-mega--closed {
  opacity: 0 !important;

  transform: translate3d(0, -8px, 0) scaleY(0.985) !important;

  visibility: hidden !important;

  pointer-events: none !important;
}

.st3-mega--closing {
  opacity: 0 !important;

  transform: translate3d(0, -5px, 0) scaleY(0.99) !important;

  visibility: visible !important;

  pointer-events: none !important;
}

.st3-mega--open {
  opacity: 1 !important;

  transform: translate3d(0, 0, 0) scaleY(1) !important;

  visibility: visible !important;

  pointer-events: auto !important;
}

.st3-mega__inner--switch {
  transition:
    opacity 210ms var(--st-active-ease),
    transform 210ms var(--st-active-ease) !important;
}

.st3-mega :is(.st3-mega__primary-link, .st3-mega__secondary-link) {
  transition:
    color 170ms var(--st-active-ease),
    opacity 170ms var(--st-active-ease),
    transform 170ms var(--st-active-ease) !important;
}

.st3-mega :is(.st3-mega__primary-link, .st3-mega__secondary-link):hover {
  transform: translate3d(3px, 0, 0) !important;
}

.st3-header__scrim--v3 {
