  position: relative;

  width: 100%;
  min-height: clamp(520px, 62vw, 720px);

  display: grid;
  place-items: center;

  overflow: hidden;

  border-radius: 30px;

  background: linear-gradient(180deg, #f7f7f9 0%, var(--st-gallery-bg) 100%);

  isolation: isolate;
}

.st-pg-modern__stage {
  width: 100%;
  height: 100%;
  min-height: inherit;

  display: grid;
  place-items: center;

  padding: clamp(44px, 6vw, 84px) clamp(28px, 6vw, 80px)
    clamp(94px, 10vw, 124px);

  animation: stModernGalleryImageIn 420ms var(--st-gallery-ease) both;
}

.st-pg-modern__image {
  display: block;

  width: auto;
  height: auto;

  max-width: min(72%, 680px);
  max-height: clamp(390px, 50vw, 570px);

  object-fit: contain;

  user-select: none;
  -webkit-user-drag: none;

  transform: translateZ(0);

  filter: drop-shadow(0 24px 40px rgba(0, 0, 0, 0.045));
}

/* --------------------------------------------------------
   APPLE-INSPIRED CENTERED IMAGE SELECTOR
   -------------------------------------------------------- */

.st-pg-modern__pagination {
  position: absolute;

  left: 50%;
  bottom: 26px;

  transform: translateX(-50%);

  z-index: 4;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 8px;

  min-height: 44px;

  padding: 8px 13px;

  border: 1px solid rgba(0, 0, 0, 0.055);

  border-radius: 999px;

  background: rgba(255, 255, 255, 0.82);

  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.055);

  -webkit-backdrop-filter: blur(18px);

  backdrop-filter: blur(18px);
}

.st-pg-modern__dot {
  appearance: none;

  width: 16px;
  height: 28px;

  display: grid;
  place-items: center;

  flex: 0 0 auto;

  margin: 0;
  padding: 0;

  border: 0;

