.st-pg-modern__dot > span {
  display: block;

  width: 7px;
  height: 7px;

  border-radius: 999px;

  background: var(--st-gallery-muted);

  transition:
    width 320ms var(--st-gallery-ease),
    height 320ms var(--st-gallery-ease),
    background-color 260ms ease,
    box-shadow 260ms ease,
    transform 260ms var(--st-gallery-ease);
}

.st-pg-modern__dot.is-active {
  width: 48px;
}

.st-pg-modern__dot.is-active > span {
  width: 40px;
  height: 7px;

  background: var(--st-gallery-mustard);

  box-shadow:
    0 0 0 1px rgba(245, 179, 53, 0.08),
    0 4px 12px rgba(245, 179, 53, 0.18);
}

.st-pg-modern__dot:not(.is-active):hover > span {
  background: #8f8f95;

  transform: scale(1.12);
}

.st-pg-modern__dot:focus-visible {
  box-shadow: 0 0 0 3px rgba(245, 179, 53, 0.2);
}

/* --------------------------------------------------------
   IMAGE CHANGE
   -------------------------------------------------------- */

@keyframes stModernGalleryImageIn {
  0% {
    opacity: 0;
    transform: translate3d(12px, 0, 0) scale(0.992);
  }

  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}

/* --------------------------------------------------------
   EMPTY STATE
   -------------------------------------------------------- */

.st-pg-modern--empty {
  min-height: 520px;

  display: grid;
  place-items: center;

  border-radius: 30px;

  background: var(--st-gallery-bg);

  color: #8a8a8f;

  font-size: 14px;
}

/* --------------------------------------------------------
   MOBILE
   -------------------------------------------------------- */

@media (max-width: 900px) {
  .st-pg-modern__viewport {
    min-height: min(132vw, 610px);

    border-radius: 24px;
  }

  .st-pg-modern__stage {
    padding: 34px 20px 90px;
  }

  .st-pg-modern__image {
    max-width: 84%;
    max-height: 470px;
  }

  .st-pg-modern__pagination {
    bottom: 20px;

    min-height: 42px;

    padding: 7px 11px;
  }
}

@media (max-width: 560px) {
  .st-pg-modern__viewport {
    min-height: min(138vw, 540px);

    border-radius: 20px;
  }

  .st-pg-modern__image {
    max-width: 90%;
    max-height: 400px;
  }

  .st-pg-modern__dot.is-active {
    width: 42px;
  }

  .st-pg-modern__dot.is-active > span {
    width: 34px;
  }
}

/*
 * We intentionally keep this one micro-animation.
 * It is an in-gallery image change, not a route/page transition.
 */
@media (prefers-reduced-motion: reduce) {
  .st-pg-modern__stage {
    animation: none;
  }

  .st-pg-modern__dot,
  .st-pg-modern__dot > span {
    transition: none;
  }
}

/* === ST MODERN PRODUCT GALLERY END === */

/* === ST PREMIUM CAROUSEL MOTION START === */

/* ========================================================
   PREMIUM IMAGE TRANSITION
   ======================================================== */

.st-pg-modern__stage {
  position: relative !important;

  overflow: hidden !important;

  animation: none !important;
}

.st-pg-modern__stage .st-pg-modern__image {
  position: absolute !important;

  inset: 0 !important;

  margin: auto !important;

  will-change: transform, opacity, filter;

  backface-visibility: hidden;

  -webkit-backface-visibility: hidden;

  transform-origin: 50% 50%;
}

/*
 * Normal resting image.
 */
.st-pg-modern__image--incoming {
  opacity: 1;

  transform: translate3d(0, 0, 0) scale(1);
}

/*
 * NEW image arriving from the right.
 */
.st-pg-modern__image--incoming.is-transitioning.is-next {
  animation: stPgPremiumEnterNext 520ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/*
 * NEW image arriving from the left.
 */
.st-pg-modern__image--incoming.is-transitioning.is-previous {
  animation: stPgPremiumEnterPrevious 520ms cubic-bezier(0.22, 0.61, 0.36, 1)
    both !important;
}

/*
 * OLD image leaving toward the left.
 */
.st-pg-modern__image--outgoing.is-next {
  animation: stPgPremiumExitNext 520ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/*
 * OLD image leaving toward the right.
 */
.st-pg-modern__image--outgoing.is-previous {
  animation: stPgPremiumExitPrevious 520ms cubic-bezier(0.22, 0.61, 0.36, 1)
    both !important;
}

@keyframes stPgPremiumEnterNext {
  0% {
    opacity: 0;

    transform: translate3d(44px, 0, 0) scale(0.985);
  }

  55% {
    opacity: 1;
  }

  100% {
    opacity: 1;

    transform: translate3d(0, 0, 0) scale(1);
  }
}

@keyframes stPgPremiumExitNext {
  0% {
    opacity: 1;

    transform: translate3d(0, 0, 0) scale(1);
  }

  100% {
    opacity: 0;

    transform: translate3d(-34px, 0, 0) scale(0.99);
  }
}

@keyframes stPgPremiumEnterPrevious {
  0% {
    opacity: 0;

    transform: translate3d(-44px, 0, 0) scale(0.985);
  }

  55% {
    opacity: 1;
  }

  100% {
    opacity: 1;

    transform: translate3d(0, 0, 0) scale(1);
  }
}

@keyframes stPgPremiumExitPrevious {
  0% {
    opacity: 1;

    transform: translate3d(0, 0, 0) scale(1);
  }

  100% {
    opacity: 0;

    transform: translate3d(34px, 0, 0) scale(0.99);
  }
}

/* ========================================================
   TRAVELLING APPLE-INSPIRED PAGINATION
   ======================================================== */

/*
 * Each position is 23px:
 *
 * 15px button + 8px gap.
 *
 * The mustard capsule moves physically from one position
 * to another rather than each dot morphing independently.
 */

.st-pg-modern__pagination {
  --st-dot-width: 15px;
  --st-dot-gap: 8px;
  --st-dot-step: calc(var(--st-dot-width) + var(--st-dot-gap));

  position: absolute !important;

  display: flex !important;

  gap: var(--st-dot-gap) !important;

  padding: 8px 13px !important;

  overflow: visible !important;
}

/*
 * Real moving mustard selection capsule.
 */
.st-pg-modern__active-track {
  position: absolute;

  top: 50%;
  left: 13px;

  width: 15px;
  height: 7px;

  border-radius: 999px;

  background: #f5b335;

  box-shadow: 0 4px 14px rgba(245, 179, 53, 0.24);

  pointer-events: none;

  z-index: 0;

  transform: translate3d(
    calc(var(--st-gallery-index) * var(--st-dot-step)),
    -50%,
    0
  );

  transition:
    transform 440ms cubic-bezier(0.22, 0.61, 0.36, 1),
    width 320ms cubic-bezier(0.22, 0.61, 0.36, 1),
    box-shadow 300ms ease;

  will-change: transform;
}

/*
 * Active selector stretches slightly during motion,
 * making it feel more fluid rather than mechanical.
 */
.st-pg-modern__pagination:active .st-pg-modern__active-track {
  width: 19px;
}

/*
 * Buttons stay fixed in place.
 */
.st-pg-modern__dot,
.st-pg-modern__dot.is-active {
  position: relative;

  width: var(--st-dot-width) !important;

  height: 28px !important;

  z-index: 1;

  transition: opacity 220ms ease !important;
}

/*
 * All real dots remain small gray points.
 * The moving mustard layer sits over the active position.
 */
.st-pg-modern__dot > span,
.st-pg-modern__dot.is-active > span {
  width: 7px !important;
  height: 7px !important;

  background: #b8b8bd !important;

  box-shadow: none !important;

  transform: none !important;

  transition:
    background-color 260ms ease,
    opacity 850ms ease,
    transform 260ms cubic-bezier(0.22, 0.61, 0.36, 1) !important;
}

/*
 * Hide the gray dot currently under the mustard capsule.
 */
.st-pg-modern__dot[aria-current="true"] > span {
  opacity: 0;
}

/*
 * Elegant pointer feedback without moving layout.
 */
.st-pg-modern__dot:not([aria-current="true"]):hover > span {
  background: #8a8a8f !important;

  transform: scale(1.18) !important;
}

/* ========================================================
   MICRO POLISH
   ======================================================== */

.st-pg-modern__viewport {
  contain: layout paint;

  transform: translateZ(0);
}

.st-pg-modern__image {
  transition: none !important;
}

/* ========================================================
   REDUCED MOTION
   ======================================================== */

@media (prefers-reduced-motion: reduce) {
  .st-pg-modern__image--incoming,
  .st-pg-modern__image--outgoing {
    animation: none !important;
  }

  .st-pg-modern__active-track {
    transition: none !important;
  }
}

/* === ST PREMIUM CAROUSEL MOTION END === */

/* === ST CENTERED PRODUCT SUCCESS TOAST START === */

/*
 * Product-page feedback notification.
 *
 * Important:
 * - bottom CENTER, never bottom-right
 * - black text
 * - mustard success identity
 * - no green inherited from older versions
 */

[data-st-product-message="success"] {
  position: fixed !important;

  left: 50% !important;
  right: auto !important;

  top: auto !important;
  bottom: 24px !important;

  width: max-content !important;
  min-width: 0 !important;

  max-width: min(620px, calc(100vw - 40px)) !important;

  margin: 0 !important;

  padding: 14px 20px !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  gap: 11px !important;

  color: #1d1d1f !important;

  background: rgba(255, 249, 232, 0.97) !important;

  border: 1px solid rgba(245, 179, 53, 0.72) !important;

  border-radius: 14px !important;

  box-shadow:
    0 12px 34px rgba(29, 29, 31, 0.1),
    0 3px 10px rgba(245, 179, 53, 0.1) !important;

  transform: translate3d(-50%, 0, 0) !important;

  font-size: 14px !important;

  font-weight: 500 !important;

  line-height: 1.35 !important;

  text-align: center !important;

  white-space: normal !important;

  z-index: 2147483000 !important;

  -webkit-font-smoothing: antialiased;

  animation: stProductToastEnter 260ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

/* --------------------------------------------------------
   FORCE SUCCESS TEXT TO BLACK
   -------------------------------------------------------- */

[data-st-product-message="success"],
[data-st-product-message="success"] *,
[data-st-product-message="success"] p,
[data-st-product-message="success"] span,
[data-st-product-message="success"] strong {
  color: #1d1d1f !important;

  -webkit-text-fill-color: #1d1d1f !important;
}

/* --------------------------------------------------------
   REMOVE OLD GREEN SUCCESS ICON COLOR
   -------------------------------------------------------- */

[data-st-product-message="success"] svg {
  color: #1d1d1f !important;

  stroke: currentColor !important;
}

[data-st-product-message="success"] svg path,
[data-st-product-message="success"] svg circle,
[data-st-product-message="success"] svg polyline,
[data-st-product-message="success"] svg line {
  stroke: currentColor !important;
}

/* If an older implementation uses a colored indicator/dot. */

[data-st-product-message="success"] i,
[data-st-product-message="success"]::before {
  color: #1d1d1f !important;

  border-color: #f5b335 !important;
}

/* --------------------------------------------------------
   SUBTLE ENTRANCE
   -------------------------------------------------------- */

@keyframes stProductToastEnter {
  0% {
    opacity: 0;

    transform: translate3d(-50%, 8px, 0);
  }

  100% {
    opacity: 1;

    transform: translate3d(-50%, 0, 0);
  }
}

/* --------------------------------------------------------
   MOBILE
   -------------------------------------------------------- */

@media (max-width: 700px) {
  [data-st-product-message="success"] {
    bottom: 18px !important;

    width: calc(100vw - 28px) !important;

    max-width: calc(100vw - 28px) !important;

    padding: 13px 16px !important;

    font-size: 13px !important;

    border-radius: 12px !important;
  }
}

/* Accessibility */

@media (prefers-reduced-motion: reduce) {
  [data-st-product-message="success"] {
    animation: none !important;
  }
}

