/* === ST REAL PDP COMPACT FINAL END === */

/* === ST APPLE HEADER MOTION V3 START === */

/*
   =========================================================
   STEREOPHONIE — HEADER REVEAL SYSTEM

   Motion model:
   CLOSED
       panel lives directly under header, vertically clipped

   OPEN
       clip grows downward
       panel settles down a few pixels
       opacity becomes fully visible

   CATEGORY SWITCH
       outer panel remains physically stable
       only inner content changes softly

   CLOSE
       exact reverse:
       panel retracts upward into header

   No bounce.
   No large scaling.
   No gaming-style movement.
   =========================================================
*/

:root {
  --st-header-open-duration: 390ms;
  --st-header-close-duration: 420ms;

  --st-header-reveal-ease: cubic-bezier(0.22, 0.61, 0.36, 1);

  --st-header-close-ease: cubic-bezier(0.32, 0, 0.18, 1);
}

/* =========================================================
   1. MEGA MENU ROOT
   ========================================================= */

.st3-header .st3-mega {
  /*
   * clip-path is what creates the actual top-to-bottom
   * reveal instead of making the panel merely "fade".
   */

  transform-origin: top center !important;

  overflow: hidden !important;

  will-change: clip-path, opacity, transform !important;

  backface-visibility: hidden !important;

  -webkit-backface-visibility: hidden !important;

  /*
   * Starting position — tucked slightly into the header.
   */

  opacity: 0 !important;

  clip-path: inset(0 0 100% 0) !important;

  transform: translate3d(0, -12px, 0) !important;

  transition:
    clip-path var(--st-header-close-duration) var(--st-header-close-ease),
    transform var(--st-header-close-duration) var(--st-header-close-ease),
    opacity 850ms ease,
    visibility 0s linear var(--st-header-close-duration) !important;
}

/* =========================================================
   2. OPEN
   Panel visibly unfolds DOWN from the header.
   ========================================================= */

.st3-header .st3-mega.st3-mega--open {
  visibility: visible !important;

  pointer-events: auto !important;

  opacity: 1 !important;

  clip-path: inset(0 0 0 0) !important;

  transform: translate3d(0, 0, 0) !important;

  transition:
    clip-path var(--st-header-open-duration) var(--st-header-reveal-ease),
    transform var(--st-header-open-duration) var(--st-header-reveal-ease),
    opacity 850ms ease,
    visibility 0s linear 0s !important;
}

/* =========================================================
   3. CLOSING
   Keep it rendered while it retracts UP into the header.
   ========================================================= */

.st3-header .st3-mega.st3-mega--closing {
  visibility: visible !important;

  pointer-events: none !important;

  opacity: 0 !important;

  clip-path: inset(0 0 100% 0) !important;

  transform: translate3d(0, -12px, 0) !important;

  transition:
    clip-path var(--st-header-close-duration) var(--st-header-close-ease),
    transform var(--st-header-close-duration) var(--st-header-close-ease),
    opacity 300ms ease,
    visibility 0s linear var(--st-header-close-duration) !important;
}

/* =========================================================
   4. CLOSED
   Completely inert after retract animation completes.
   ========================================================= */

.st3-header .st3-mega.st3-mega--closed {
  visibility: hidden !important;

  pointer-events: none !important;

  opacity: 0 !important;

  clip-path: inset(0 0 100% 0) !important;

  transform: translate3d(0, -12px, 0) !important;
}

/* =========================================================
   5. INNER CONTENT
   Do NOT reanimate the whole panel when moving:
   Phones → Smart Watches → Fitness Watches.
   ========================================================= */

.st3-mega__inner {
  transform: translate3d(0, 0, 0);

  will-change: opacity, transform;
}

/*
 * When the complete menu first opens, content settles
 * softly after the panel starts revealing.
 */

.st3-mega--open .st3-mega__inner {
  animation: st3AppleMegaContentEnter 330ms 55ms cubic-bezier(0.16, 1, 0.3, 1)
    both !important;
}

@keyframes st3AppleMegaContentEnter {
  0% {
    opacity: 0;

    transform: translate3d(0, -7px, 0);
  }

  100% {
    opacity: 1;

    transform: translate3d(0, 0, 0);
  }
}

/* =========================================================
   6. CATEGORY CONTENT SWITCHING
   Outer panel does not collapse.
   Only content shifts subtly.
   ========================================================= */

.st3-mega__inner--switch {
  animation: st3AppleCategorySwitch 250ms cubic-bezier(0.22, 0.61, 0.36, 1) both !important;
}

@keyframes st3AppleCategorySwitch {
  0% {
    opacity: 0.35;

    transform: translate3d(0, 5px, 0);
  }

  100% {
    opacity: 1;

    transform: translate3d(0, 0, 0);
  }
}

/*
 * Closing content does not run another elaborate animation.
 * It simply follows the retracting container.
 */

.st3-mega--closing .st3-mega__inner {
  animation: none !important;

  opacity: 0.82 !important;

  transform: translate3d(0, -3px, 0) !important;

  transition:
    opacity 850ms ease,
    transform 340ms var(--st-header-close-ease) !important;
}

/* =========================================================
   7. BACKGROUND SCRIM
   Synchronised with the panel.
   ========================================================= */

.st3-header__scrim,
.st3-header__scrim--v3 {
  transition:
    opacity 320ms ease,
    visibility 0s linear 420ms !important;
}

.st3-header__scrim--open {
  visibility: visible !important;

  transition:
    opacity 340ms ease,
    visibility 0s linear 0s !important;
}

.st3-header__scrim--closing {
  visibility: visible !important;

  pointer-events: none !important;

  opacity: 0 !important;

  transition:
    opacity 360ms ease,
    visibility 0s linear 420ms !important;
}

/* =========================================================
   8. HEADER CATEGORY LABELS
   ========================================================= */

.st3-header__nav-item {
  transition:
    color 190ms ease,
    opacity 190ms ease,
    background-color 190ms ease !important;
}

/* =========================================================
   9. LINKS INSIDE MEGA MENU
   Small visual response only. No jumping.
   ========================================================= */

.st3-mega__primary-link,
.st3-mega__secondary-link {
  transition:
    color 190ms ease,
    opacity 190ms ease,
    background-color 190ms ease !important;
}

/*
 * Slightly soften inactive links when another one is hovered.
 * Gives navigation a cleaner hierarchy.
 */

@media (hover: hover) {
  .st3-mega__links:hover .st3-mega__primary-link:not(:hover),
  .st3-mega__secondary-links:hover .st3-mega__secondary-link:not(:hover) {
    opacity: 0.58;
  }

  .st3-mega__primary-link:hover,
  .st3-mega__secondary-link:hover {
    opacity: 1;

    color: #1d1d1f;
  }
}

/* =========================================================
   10. ACCESSIBILITY
   ========================================================= */

@media (prefers-reduced-motion: reduce) {
  .st3-header .st3-mega,
  .st3-header .st3-mega *,
  .st3-header__scrim,
  .st3-header__scrim--v3 {
    animation: none !important;

    transition: none !important;
  }
}

/* === ST APPLE HEADER MOTION V3 END === */

/* === ST CLEAN INTERACTION MOTION V1 START === */

/*
   =========================================================
   STEREOPHONIE — CLEAN MICRO INTERACTIONS

   Philosophy:
   - short
   - responsive
   - no bounce
   - no large movement
   - no page transition
   - no loader animation
   =========================================================
*/

:root {
  --st-ui-fast: 150ms;
  --st-ui-normal: 210ms;
  --st-ui-panel: 240ms;

  --st-ui-ease: cubic-bezier(0.22, 0.61, 0.36, 1);

  --st-ui-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
}

/* =========================================================
   1. AI ASSISTANT PANEL
   ========================================================= */

/*
 * The assistant <aside> stays mounted at all times,
 * which means we can animate both directions properly.
 */

.st3-ai-panel {
  opacity: 0 !important;

  visibility: hidden !important;

  pointer-events: none !important;

  transform: translate3d(0, 10px, 0) scale(0.985) !important;

  transform-origin: bottom right !important;

  transition:
    opacity var(--st-ui-panel) var(--st-ui-ease),
    transform var(--st-ui-panel) var(--st-ui-ease-out),
    visibility 0s linear var(--st-ui-panel) !important;

  will-change: opacity, transform;
}

.st3-ai-panel.st3-ai-panel--open {
  opacity: 1 !important;

  visibility: visible !important;

  pointer-events: auto !important;

  transform: translate3d(0, 0, 0) scale(1) !important;

  transition:
    opacity var(--st-ui-panel) var(--st-ui-ease),
    transform var(--st-ui-panel) var(--st-ui-ease-out),
    visibility 0s linear 0s !important;
}

/*
 * Inner content settles very slightly after the surface.
 */

.st3-ai-panel__top,
.st3-ai-panel__messages,
.st3-ai-composer,
.st3-ai-disclaimer {
  transition:
    opacity 190ms var(--st-ui-ease),
    transform 210ms var(--st-ui-ease-out) !important;
}

.st3-ai-panel:not(.st3-ai-panel--open)
  :is(
    .st3-ai-panel__top,
    .st3-ai-panel__messages,
    .st3-ai-composer,
    .st3-ai-disclaimer
  ) {
  opacity: 0.72;

  transform: translate3d(0, 3px, 0);
}

.st3-ai-panel.st3-ai-panel--open
  :is(
    .st3-ai-panel__top,
    .st3-ai-panel__messages,
    .st3-ai-composer,
    .st3-ai-disclaimer
  ) {
  opacity: 1;

  transform: translate3d(0, 0, 0);
}

/*
 * IMPORTANT:
 * Do not touch transform/animation on the launcher itself.
 * Its existing mustard breathing + float remain authoritative.
 */

.st3-ai-launcher {
  transition:
    border-color var(--st-ui-fast) ease,
    background-color var(--st-ui-fast) ease,
    box-shadow var(--st-ui-fast) ease,
    filter var(--st-ui-fast) ease !important;
}

.st3-ai-launcher:active {
  filter: brightness(0.975);
}

/* =========================================================
   2. PRICE RANGE — REAL OPEN + CLOSE
   ========================================================= */

.st-filter-v4__price-backdrop {
  opacity: 1 !important;

  visibility: visible !important;

  transition: opacity 180ms ease !important;
}

.st-filter-v4__price-backdrop.is-closing {
  opacity: 0 !important;

  pointer-events: none !important;
}

.st-filter-v4__price-popover {
  transform-origin: top left !important;

  will-change: opacity, transform;

  transition:
    opacity var(--st-ui-panel) var(--st-ui-ease),
    transform var(--st-ui-panel) var(--st-ui-ease-out),
    box-shadow var(--st-ui-normal) ease !important;
}

.st-filter-v4__price-popover.is-open {
  opacity: 1 !important;

  visibility: visible !important;

  pointer-events: auto !important;

  transform: translate3d(0, 0, 0) scale(1) !important;
}

.st-filter-v4__price-popover.is-closing {
  opacity: 0 !important;

  visibility: visible !important;

  pointer-events: none !important;

  transform: translate3d(0, -5px, 0) scale(0.988) !important;
}

/* =========================================================
   3. CATEGORY / BRAND / SORT CONTROLS
   ========================================================= */

/*
 * Native select menus are controlled by Safari/macOS.
 * We animate the storefront control itself cleanly.
 */

.st-filter-v4__select,
.st-filter-v4__sort {
  transition:
    background-color var(--st-ui-normal) var(--st-ui-ease),
    border-color var(--st-ui-normal) var(--st-ui-ease),
    color var(--st-ui-normal) var(--st-ui-ease),
    box-shadow var(--st-ui-normal) var(--st-ui-ease) !important;
}

.st-filter-v4__select:hover,
.st-filter-v4__sort:hover {
  border-color: rgba(29, 29, 31, 0.22) !important;
}

.st-filter-v4__select:focus-within,
.st-filter-v4__sort:focus-within {
  border-color: rgba(245, 179, 53, 0.72) !important;

  box-shadow: 0 0 0 3px rgba(245, 179, 53, 0.1) !important;
}

/*
 * Chevron receives subtle feedback.
 */

.st-filter-v4__select > svg,
.st-filter-v4__sort > svg {
  transition:
    opacity 180ms ease,
    color 180ms ease,
    transform 210ms var(--st-ui-ease) !important;
}

.st-filter-v4__select:focus-within > svg,
.st-filter-v4__sort:focus-within > svg {
  color: #a86b00;

  transform: translate3d(0, 1px, 0);
}

/* =========================================================
   4. FILTER PILLS
   ========================================================= */

.st-filter-v4__pill,
.st-filter-v4__search-button,
.st-filter-v4__price-title button,
.st-filter-v4__price-actions button {
  transition:
    background-color var(--st-ui-normal) var(--st-ui-ease),
    border-color var(--st-ui-normal) var(--st-ui-ease),
    color var(--st-ui-normal) var(--st-ui-ease),
    box-shadow var(--st-ui-normal) var(--st-ui-ease),
    filter var(--st-ui-fast) ease !important;
}

/*
 * No jumping.
 */

.st-filter-v4__pill:hover,
.st-filter-v4__pill:active,
.st-filter-v4__search-button:hover,
.st-filter-v4__search-button:active,
.st-filter-v4__price-title button:hover,
.st-filter-v4__price-title button:active,
.st-filter-v4__price-actions button:hover,
.st-filter-v4__price-actions button:active {
  transform: none !important;

  translate: none !important;

  scale: 1 !important;
}

.st-filter-v4__pill:active,
.st-filter-v4__search-button:active,
.st-filter-v4__price-actions button:active {
  filter: brightness(0.975);
}

/* =========================================================
   5. HEADER BUTTON / LINK FEEDBACK
   ========================================================= */

/*
 * This does NOT replace your new header reveal animation.
 * It only refines the individual controls.
 */

.st3-header__nav-item,
.st3-header__icon {
  transition:
    background-color var(--st-ui-normal) var(--st-ui-ease),
    color var(--st-ui-normal) var(--st-ui-ease),
    opacity var(--st-ui-normal) var(--st-ui-ease),
    box-shadow var(--st-ui-normal) var(--st-ui-ease) !important;
}

/* =========================================================
   6. PRODUCT / STOREFRONT BUTTON FEEDBACK
   ========================================================= */

/*
 * Color/shadow feedback only.
 * We deliberately DO NOT globally translate buttons.
 */

.st-retail-card button,
.st-product-v5 button,
.st-purchase-v6 button,
.st3-ai-panel button {
  transition:
    background-color var(--st-ui-normal) var(--st-ui-ease),
    border-color var(--st-ui-normal) var(--st-ui-ease),
    color var(--st-ui-normal) var(--st-ui-ease),
    box-shadow var(--st-ui-normal) var(--st-ui-ease),
    opacity var(--st-ui-fast) ease,
    filter var(--st-ui-fast) ease !important;
}

/*
 * Do NOT disturb:
 * - wishlist/new-badge breathing
 * - AI breathing
 * - product carousel movement
 */

.st-retail-card button:active,
.st-product-v5 button:active,
.st-purchase-v6 button:active,
.st3-ai-panel button:active {
  filter: brightness(0.975);
}

/* =========================================================
   7. INPUT FOCUS
   ========================================================= */

.st-filter-v4 input,
.st3-ai-composer input {
  transition:
    border-color var(--st-ui-normal) var(--st-ui-ease),
    box-shadow var(--st-ui-normal) var(--st-ui-ease),
    background-color var(--st-ui-normal) var(--st-ui-ease) !important;
}

/* =========================================================
   8. ACCESSIBILITY
   ========================================================= */

@media (prefers-reduced-motion: reduce) {
  .st3-ai-panel,
  .st3-ai-panel *,
  .st-filter-v4__price-popover,
  .st-filter-v4__price-backdrop,
  .st-filter-v4__select,
  .st-filter-v4__sort,
  .st-filter-v4__pill,
  .st-filter-v4__search-button {
    transition: none !important;
  }
}

/* === ST CLEAN INTERACTION MOTION V1 END === */

/* === ST SHOP CLEAN MOTION FINAL START === */

/*
   =========================================================
   STEREOPHONIE SHOP — PREMIUM MICRO MOTION

   Motion language:
   - responsive
   - subtle
   - no bounce
   - no layout movement
   - no heavy blur animation
   - no gaming-style scaling
   =========================================================
*/

:root {
  --st-shop-motion-fast: 150ms;

  --st-shop-motion-normal: 210ms;

  --st-shop-motion-panel: 240ms;

  --st-shop-motion-ease: cubic-bezier(0.22, 0.61, 0.36, 1);

  --st-shop-motion-ease-out: cubic-bezier(0.16, 1, 0.3, 1);

  --st-shop-mustard: #f5b335;

  --st-shop-mustard-soft: rgba(245, 179, 53, 0.1);

  --st-shop-ink: #1d1d1f;
}

/* =========================================================
   1. PRICE BUTTON
   ========================================================= */

.st-retail-shop .st-filter-v4__price-wrap .st-filter-v4__pill {
  transition:
    background-color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    border-color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    box-shadow var(--st-shop-motion-normal) var(--st-shop-motion-ease) !important;

  transform: none !important;

  translate: none !important;
}

.st-retail-shop .st-filter-v4__price-wrap .st-filter-v4__pill:hover {
  box-shadow: 0 5px 16px rgba(0, 0, 0, 0.055) !important;
}

.st-retail-shop .st-filter-v4__price-wrap .st-filter-v4__pill:active {
  filter: brightness(0.975);

  transform: none !important;
}

/* Chevron gets a tiny visual response. */

.st-retail-shop .st-filter-v4__price-wrap .st-filter-v4__pill > svg:last-child {
  transition:
    transform var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    color var(--st-shop-motion-normal) ease !important;
}

.st-retail-shop
  .st-filter-v4__price-wrap
  .st-filter-v4__pill[aria-expanded="true"]
  > svg:last-child {
  transform: rotate(180deg) !important;
}

/* =========================================================
   2. PRICE RANGE POPOVER
   ========================================================= */

/*
 * OPEN state.
 */

.st-retail-shop .st-filter-v4__price-popover.is-open {
  opacity: 1 !important;

  visibility: visible !important;

  pointer-events: auto !important;

  transform: translate3d(0, 0, 0) scale(1) !important;

  transition:
    opacity var(--st-shop-motion-panel) var(--st-shop-motion-ease),
    transform var(--st-shop-motion-panel) var(--st-shop-motion-ease-out),
    box-shadow var(--st-shop-motion-normal) ease !important;
}

/*
 * CLOSING state.
 *
 * If priceMounted exists, React keeps this element alive long
 * enough to visibly animate to this state.
 */

.st-retail-shop .st-filter-v4__price-popover.is-closing {
  opacity: 0 !important;

  visibility: visible !important;

  pointer-events: none !important;

  transform: translate3d(0, -7px, 0) scale(0.987) !important;

  transition:
    opacity var(--st-shop-motion-panel) var(--st-shop-motion-ease),
    transform var(--st-shop-motion-panel) var(--st-shop-motion-ease) !important;
}

/*
 * Compatibility with the version that mounts the panel
 * directly without state classes.
 */

.st-retail-shop .st-filter-v4__price-popover:not(.is-closing) {
  transform-origin: top left !important;

  will-change: opacity, transform;
}

/*
 * Outside-click layer fades instead of flashing.
 */

.st-retail-shop .st-filter-v4__price-backdrop {
  transition: opacity 190ms ease !important;
}

.st-retail-shop .st-filter-v4__price-backdrop.is-open {
  opacity: 1 !important;
}

.st-retail-shop .st-filter-v4__price-backdrop.is-closing {
  opacity: 0 !important;

  pointer-events: none !important;
}

/* =========================================================
   3. CATEGORY + BRAND
   ========================================================= */

/*
 * These are native Safari/macOS selects.
 *
 * We animate the storefront shell, not Apple's operating-
 * system dropdown window.
 */

.st-retail-shop .st-filter-v4__select {
  transition:
    background-color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    border-color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    box-shadow var(--st-shop-motion-normal) var(--st-shop-motion-ease) !important;

  transform: none !important;
}

.st-retail-shop .st-filter-v4__select:hover {
  border-color: rgba(29, 29, 31, 0.24) !important;

  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.035) !important;
}

.st-retail-shop .st-filter-v4__select:focus-within {
  border-color: rgba(245, 179, 53, 0.7) !important;

  box-shadow: 0 0 0 3px rgba(245, 179, 53, 0.1) !important;
}

/*
 * Chevron motion.
 */

.st-retail-shop .st-filter-v4__select > svg {
  transition:
    transform var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    color var(--st-shop-motion-normal) ease,
    opacity var(--st-shop-motion-normal) ease !important;
}

.st-retail-shop .st-filter-v4__select:focus-within > svg {
  color: #a86b00 !important;

  transform: translate3d(0, 1px, 0) !important;
}

/* Native select itself must stay instant/responsive. */

.st-retail-shop .st-filter-v4__select select {
  cursor: pointer;

  transition: color var(--st-shop-motion-normal) ease !important;
}

/* =========================================================
   4. SORT
   ========================================================= */

.st-retail-shop .st-filter-v4__sort {
  transition:
    background-color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    border-color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    box-shadow var(--st-shop-motion-normal) var(--st-shop-motion-ease) !important;

  transform: none !important;
}

.st-retail-shop .st-filter-v4__sort:hover {
  border-color: rgba(29, 29, 31, 0.24) !important;

  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.035) !important;
}

.st-retail-shop .st-filter-v4__sort:focus-within {
  border-color: rgba(245, 179, 53, 0.7) !important;

  box-shadow: 0 0 0 3px rgba(245, 179, 53, 0.1) !important;
}

.st-retail-shop .st-filter-v4__sort > svg {
  transition:
    color var(--st-shop-motion-normal) ease,
    transform var(--st-shop-motion-normal) var(--st-shop-motion-ease) !important;
}

.st-retail-shop .st-filter-v4__sort:focus-within > svg {
  color: #a86b00 !important;

  transform: translate3d(0, 1px, 0) !important;
}

/* =========================================================
   5. IN STOCK
   ========================================================= */

/*
 * Smooth transition between:
 *
 * OFF
 * white pill / dark text / mustard dot
 *
 * ON
 * black pill / white text / mustard dot
 */

.st-retail-shop .st-filter-v4__pill {
  transition:
    background-color 230ms var(--st-shop-motion-ease),
    border-color 230ms var(--st-shop-motion-ease),
    color 230ms var(--st-shop-motion-ease),
    box-shadow 230ms var(--st-shop-motion-ease),
    filter var(--st-shop-motion-fast) ease !important;

  transform: none !important;

  translate: none !important;

  scale: 1 !important;
}

.st-retail-shop .st-filter-v4__pill:hover {
  transform: none !important;

  translate: none !important;

  scale: 1 !important;
}

.st-retail-shop .st-filter-v4__pill:active {
  filter: brightness(0.975);
}

.st-retail-shop .st-filter-v4__pill.is-active {
  background: var(--st-shop-ink) !important;

  border-color: var(--st-shop-ink) !important;

  color: #fff !important;

  box-shadow: 0 7px 20px rgba(0, 0, 0, 0.075) !important;
}

/*
 * Mustard dot smoothly breathes into the active state,
 * but does NOT bounce or change layout.
 */

.st-retail-shop .st-filter-v4__stock-dot {
  background: var(--st-shop-mustard) !important;

  transition:
    background-color 230ms var(--st-shop-motion-ease),
    box-shadow 230ms var(--st-shop-motion-ease),
    opacity 230ms var(--st-shop-motion-ease) !important;
}

.st-retail-shop .st-filter-v4__pill.is-active .st-filter-v4__stock-dot {
  background: var(--st-shop-mustard) !important;

  box-shadow: 0 0 0 4px rgba(245, 179, 53, 0.12) !important;
}

/* =========================================================
   6. PRICE PANEL INTERNAL CONTROLS
   ========================================================= */

.st-retail-shop .st-filter-v4__price-title button,
.st-retail-shop .st-filter-v4__price-actions button,
.st-retail-shop .st-filter-v4__price-fields input {
  transition:
    background-color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    border-color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    box-shadow var(--st-shop-motion-normal) var(--st-shop-motion-ease),
    filter var(--st-shop-motion-fast) ease !important;
}

.st-retail-shop .st-filter-v4__price-title button:hover,
.st-retail-shop .st-filter-v4__price-title button:active,
.st-retail-shop .st-filter-v4__price-actions button:hover,
.st-retail-shop .st-filter-v4__price-actions button:active {
  transform: none !important;

  translate: none !important;

  scale: 1 !important;
}

/* =========================================================
   7. SEARCH
   ========================================================= */

.st-retail-shop .st-filter-v4__search,
.st-retail-shop .st-filter-v4__search-button {
  transition:
    background-color var(--st-shop-motion-normal) var(--st-shop-motion-ease),
