/*
   ==========================================================
   PRICE RANGE — GUARANTEED ENTERING -> OPEN ANIMATION

   React now gives us three real visual states:

   is-entering
       invisible / slightly raised

   is-open
       fully visible / settled

   is-closing
       fades and lifts away

   No keyframe is required for opening.
   A transition between two browser-painted states is more
   reliable here.
   ==========================================================
*/

/* ----------------------------------------------------------
   BASE
   ---------------------------------------------------------- */

.st-retail-shop .st-filter-v4__price-popover {
  transform-origin: top left !important;

  will-change: opacity, transform !important;

  transition:
    opacity 290ms cubic-bezier(0.22, 0.61, 0.36, 1),
    transform 320ms cubic-bezier(0.16, 1, 0.3, 1),
    box-shadow 190ms ease !important;

  animation: none !important;
}

/* ----------------------------------------------------------
   ENTERING
   This state is now physically painted BEFORE is-open.
   ---------------------------------------------------------- */

.st-retail-shop .st-filter-v4__price-popover.is-entering {
  opacity: 0 !important;

  visibility: visible !important;

  pointer-events: none !important;

  transform: translate3d(0, -12px, 0) scale(0.972) !important;
}

/* ----------------------------------------------------------
   OPEN
   Browser transitions from ENTERING -> here.
   ---------------------------------------------------------- */

.st-retail-shop .st-filter-v4__price-popover.is-open {
  opacity: 1 !important;

  visibility: visible !important;

  pointer-events: auto !important;

  transform: translate3d(0, 0, 0) scale(1) !important;

  animation: none !important;
}

/* ----------------------------------------------------------
   CLOSE
   Keep the working closing behavior.
   ---------------------------------------------------------- */

.st-retail-shop .st-filter-v4__price-popover.is-closing {
  opacity: 0 !important;

  visibility: visible !important;

  pointer-events: none !important;

  transform: translate3d(0, -9px, 0) scale(0.982) !important;

  transition:
    opacity 250ms cubic-bezier(0.4, 0, 0.2, 1),
    transform 270ms cubic-bezier(0.4, 0, 0.2, 1) !important;

  animation: none !important;
}

/* ----------------------------------------------------------
