  box-sizing: border-box;
}

.st-account-verification {
  position: relative;
  min-height: calc(100vh - 76px);
  overflow: hidden;
  background:
    radial-gradient(
      circle at 88% 17%,
      rgba(245, 179, 53, 0.12),
      transparent 26rem
    ),
    radial-gradient(
      circle at 8% 88%,
      rgba(29, 29, 31, 0.045),
      transparent 24rem
