    #f8f7f4;
  color: #1d1d1f;
}

.st-account-verification__ambient {
  position: absolute;
  border-radius: 999px;
  pointer-events: none;
  filter: blur(1px);
}

.st-account-verification__ambient--one {
  width: 420px;
  height: 420px;
  right: -170px;
  top: 30px;
  background: rgba(245, 179, 53, 0.07);
}

.st-account-verification__ambient--two {
  width: 320px;
  height: 320px;
  left: -150px;
  bottom: -100px;
  background: rgba(29, 29, 31, 0.028);
}

.st-account-verification__stage {
  position: relative;
  z-index: 1;
