.st-account-verification__message > svg {
  flex: 0 0 auto;
}

.st-account-verification__message > span {
  width: 22px;
  height: 22px;

  display: grid;
  place-items: center;

  border-radius: 999px;

  font-size: 11px;
  font-weight: 750;
}

.st-account-verification__message > svg {
  width: 18px;
  height: 18px;
}

.st-account-verification__message--error {
  border: 1px solid rgba(197, 48, 48, 0.13);
  background: #fff7f7;
  color: #b4232d;
}

.st-account-verification__message--error > span {
  background: #fff0f0;
}

.st-account-verification__message--success {
  border: 1px solid rgba(31, 169, 113, 0.14);
  background: #f2fbf6;
  color: #16815d;
}

.st-account-verification__form {
  margin-top: 28px;
}

.st-account-verification__form fieldset {
  margin: 0;
  padding: 0;
  border: 0;
}

.st-account-verification__form legend {
  width: 100%;
  margin: 0 0 11px;

  color: #6e6e73;

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-align: center;
  text-transform: uppercase;
}

.st-account-verification__digits {
  width: min(100%, 440px);
  margin: 0 auto;

  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 9px;
}

.st-account-verification__digits input {
  width: 100%;
  aspect-ratio: 1 / 1;
  min-width: 0;

  border: 1px solid rgba(29, 29, 31, 0.1);
  border-radius: 14px;

  background: #f8f8f9;
  color: #1d1d1f;

  outline: none;

  text-align: center;

  font-size: 22px;
  font-weight: 650;

  caret-color: #b97700;

  transition:
    border-color 150ms ease,
    background-color 150ms ease,
    box-shadow 150ms ease,
    transform 150ms ease;
}

.st-account-verification__digits input:hover {
  background: #fff;
  border-color: rgba(29, 29, 31, 0.18);
}

.st-account-verification__digits input:focus {
  border-color: rgba(245, 179, 53, 0.75);
  background: #fff;

  box-shadow: 0 0 0 4px rgba(245, 179, 53, 0.11);

  transform: translateY(-1px);
}

.st-account-verification__digits input.is-filled {
  border-color: rgba(245, 179, 53, 0.34);
  background: #fff9ed;
}

.st-account-verification__primary {
  width: 100%;
  min-height: 52px;
  margin-top: 22px;
  padding: 0 18px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  border: 1px solid #1d1d1f;
  border-radius: 14px;

  background: #1d1d1f;
  color: #fff;

  cursor: pointer;

  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;

  transition:
    transform 160ms ease,
    background-color 160ms ease,
    box-shadow 160ms ease;
}

.st-account-verification__primary svg {
  width: 16px;
  height: 16px;
  transition: transform 160ms ease;
}

.st-account-verification__primary:hover:not(:disabled) {
  background: #000;
  transform: translateY(-1px);

  box-shadow: 0 10px 24px rgba(29, 29, 31, 0.12);
}

.st-account-verification__primary:hover:not(:disabled) svg {
  transform: translateX(2px);
}

.st-account-verification__primary:disabled {
  border-color: #ececef;
  background: #f4f4f5;
  color: #b7b7bc;
  cursor: not-allowed;
  box-shadow: none;
}

.st-account-verification__resend {
  margin-top: 25px;
  padding-top: 22px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  border-top: 1px solid rgba(29, 29, 31, 0.07);
}

.st-account-verification__resend > div strong,
.st-account-verification__resend > div span {
  display: block;
}

.st-account-verification__resend > div strong {
  color: #1d1d1f;

  font-size: 12px;
  font-weight: 650;
}

.st-account-verification__resend > div span {
  margin-top: 4px;

  color: #a1a1a6;

  font-size: 10px;
  line-height: 1.4;
}

.st-account-verification__resend-button {
  min-height: 38px;
  padding: 0 13px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;

  border: 1px solid rgba(29, 29, 31, 0.09);
  border-radius: 11px;

  background: #fff;
  color: #1d1d1f;

  cursor: pointer;

  font-size: 10px;
  font-weight: 650;

  white-space: nowrap;

  transition:
    border-color 150ms ease,
    background-color 150ms ease;
}

.st-account-verification__resend-button svg {
  width: 13px;
  height: 13px;
}

.st-account-verification__resend-button:hover:not(:disabled) {
  border-color: rgba(245, 179, 53, 0.45);
  background: #fffaf0;
}

.st-account-verification__resend-button:disabled {
  color: #a1a1a6;
  cursor: not-allowed;
}

.st-account-verification__note {
  margin-top: 22px;
  padding: 14px 15px;

  display: flex;
  align-items: flex-start;
  gap: 10px;

  border-radius: 13px;

  background: #f7f7f8;
  color: #86868b;
}

.st-account-verification__note svg {
  width: 16px;
  height: 16px;
  margin-top: 1px;
  flex: 0 0 auto;
  color: #6e6e73;
}

.st-account-verification__note p {
  margin: 0;

  font-size: 10px;
  line-height: 1.55;
}

@media (max-width: 640px) {
  .st-account-verification__stage {
    padding: 32px 14px 50px;
  }

  .st-account-verification__card {
    padding: 24px 18px 24px;

    border-radius: 21px;
  }

  .st-account-verification__top {
    align-items: flex-start;
  }

  .st-account-verification__secure {
    font-size: 8px;
  }

  .st-account-verification__logo {
    margin-top: 26px;
  }

  .st-account-verification__intro {
    margin-top: 25px;
  }

  .st-account-verification__digits {
    gap: 6px;
  }

  .st-account-verification__digits input {
    border-radius: 10px;

    font-size: 19px;
  }

  .st-account-verification__resend {
    align-items: stretch;
    flex-direction: column;
  }

  .st-account-verification__resend-button {
    width: 100%;
  }
