/* === STEREOPHONIE ACCOUNT VERIFICATION — APPLE RETAIL V1 END === */

/* === ST VERIFICATION MATCH AUTH CARD V1 START === */

/*
 * Make /account/verify feel like the immediate next step
 * of the new Sign in / Create account experience.
 */

html body .st-account-verify,
html body .st-verify-page,
html body [class*="verify-page"] {
  font-family:
    -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text",
    "Helvetica Neue", Arial, sans-serif;
}

/* ---------------------------------------------------------
   PAGE STAGE
   --------------------------------------------------------- */

html body .st-account-verify,
html body .st-verify-page {
  min-height: calc(100vh - 84px);

  padding: 58px 20px 80px;

  display: flex;

  align-items: flex-start;

  justify-content: center;

  background:
    radial-gradient(
      circle at 92% 8%,
      rgba(245, 179, 53, 0.13),
      transparent 30rem
    ),
    radial-gradient(
      circle at 4% 88%,
      rgba(29, 29, 31, 0.045),
      transparent 25rem
    ),
    #f7f6f2;
}

/* ---------------------------------------------------------
   MAIN CARD
   --------------------------------------------------------- */

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"]) {
  width: min(100%, 610px);

  margin: 0 auto;

  padding: 32px 34px 34px;

  border: 1px solid rgba(29, 29, 31, 0.07);

  border-radius: 25px;

  background: rgba(255, 255, 255, 0.96);

  box-shadow: 0 24px 70px rgba(29, 29, 31, 0.09);

  box-sizing: border-box;
}

/* ---------------------------------------------------------
   BRAND
   --------------------------------------------------------- */

.st-auth-match-verify__brand {
  min-height: 42px;

  margin: 0 0 22px;

  display: flex;

  align-items: center;

  justify-content: flex-start;
}

.st-auth-match-verify__brand img {
  max-height: 42px;

  object-fit: contain;
}

/* ---------------------------------------------------------
   TOP BAR
   --------------------------------------------------------- */

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  :is([class*="top"], [class*="header"]) {
  border: 0;
}

/*
 * Back + security pill should feel like the auth card header.
 */
html body :is(.st-verify-back, [class*="verify"][class*="back"]) {
  color: #6e6e73;

  font-size: 12px;

  font-weight: 560;

  text-decoration: none;
}

html body :is(.st-verify-secure, [class*="verify"][class*="secure"]) {
  padding: 8px 12px;

  border: 1px solid rgba(31, 169, 113, 0.14);

  border-radius: 999px;

  background: #effaf5;

  color: #16815d;

  font-size: 9px;

  font-weight: 700;

  letter-spacing: 0.1em;

  text-transform: uppercase;
}

/* ---------------------------------------------------------
   MAIN CONTENT
   --------------------------------------------------------- */

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  h1 {
  margin: 10px 0 0;

  color: #1d1d1f;

  font-size: clamp(2rem, 4vw, 2.75rem);

  line-height: 1.03;

  letter-spacing: -0.055em;

  font-weight: 650;

  text-align: left;
}

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  p {
  color: #86868b;
}

/*
 * Eyebrow.
 */
html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  :is([class*="eyebrow"], [class*="kicker"]) {
  color: #a66a00;

  font-size: 9px;

  font-weight: 700;

  letter-spacing: 0.18em;

  text-transform: uppercase;
}

/* Email icon */
html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  :is([class*="mail"], [class*="email-icon"], [class*="verify-icon"]) {
  border-radius: 14px;
}

/* ---------------------------------------------------------
   EMAIL / STATUS
   --------------------------------------------------------- */

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  :is([class*="success"], [class*="sent"]) {
  border: 1px solid rgba(31, 169, 113, 0.13);

  border-radius: 13px;

  background: #f0faf5;
}

/* ---------------------------------------------------------
   OTP INPUTS
   --------------------------------------------------------- */

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  :is([class*="otp"], [class*="code"])
  input {
  width: 58px;

  height: 58px;

  min-height: 58px;

  border: 1px solid rgba(29, 29, 31, 0.11);

  border-radius: 14px;

  background: #f8f8f9;

  color: #1d1d1f;

  font-family:
    -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue",
    Arial, sans-serif;

  font-size: 20px;

  font-weight: 600;

  text-align: center;

  outline: none;

  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    background-color 160ms ease;
}

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  :is([class*="otp"], [class*="code"])
  input:focus {
  border-color: rgba(245, 179, 53, 0.86);

  background: #ffffff;

  box-shadow: 0 0 0 4px rgba(245, 179, 53, 0.11);
}

/* ---------------------------------------------------------
   PRIMARY CTA
   --------------------------------------------------------- */

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  button[type="submit"] {
  min-height: 52px;

  border: 0;

  border-radius: 13px;

  background: #1d1d1f;

  color: #fff;

  font-size: 10px;

  font-weight: 700;

  letter-spacing: 0.12em;

  text-transform: uppercase;

  transition:
    transform 160ms ease,
    background-color 160ms ease,
    opacity 160ms ease;
}

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  button[type="submit"]:hover:not(:disabled) {
  background: #000;

  transform: translateY(-1px);
}

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  button[type="submit"]:disabled {
  background: #f2f2f4;

  color: #a1a1a6;

  opacity: 1;
}

/* ---------------------------------------------------------
   RESEND AREA
   --------------------------------------------------------- */

html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  :is([class*="resend"], [class*="footer"]) {
  border-color: rgba(29, 29, 31, 0.07);
}

/* Security info becomes quiet, like auth privacy copy. */
html
  body
  :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
  :is([class*="security-note"], [class*="warning"], [class*="notice"]) {
  border: 0;

  border-radius: 12px;

  background: #f7f7f8;

  color: #86868b;
}

/* ---------------------------------------------------------
   MOBILE
   --------------------------------------------------------- */

@media (max-width: 680px) {
  html body .st-account-verify,
  html body .st-verify-page {
    padding: 26px 14px 50px;
  }

  html
    body
    :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"]) {
    padding: 24px 20px 26px;

    border-radius: 21px;
  }

  .st-auth-match-verify__brand {
    justify-content: center;

    margin-bottom: 20px;
  }

  html
    body
    :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
    h1 {
    text-align: center;
  }

  html
    body
    :is(.st-verify-card, .st-account-verify__card, [class*="verify-card"])
    :is([class*="otp"], [class*="code"])
    input {
    width: clamp(43px, 12vw, 52px);

    height: clamp(50px, 13vw, 56px);

    min-height: 50px;
  }
}

/* === ST VERIFICATION MATCH AUTH CARD V1 END === */

/* === VERIFICATION BRAND ALIGNMENT START === */

.st-account-verification__brand {
  margin-top: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.st-account-verification__brand img {
  display: block;
  width: auto;
  height: auto;
  max-height: 44px;
  object-fit: contain;
}

/*
 * Keep the next section close enough that the logo and
 * verification content feel like one continuous auth card.
 */
.st-account-verification__brand + .st-account-verification__intro {
  margin-top: 24px;
}

@media (max-width: 640px) {
  .st-account-verification__brand {
    margin-top: 22px;
  }

  .st-account-verification__brand + .st-account-verification__intro {
    margin-top: 20px;
  }
}

/* === VERIFICATION BRAND ALIGNMENT END === */

/* === STEREOPHONIE CLEAN AUTH WHITE BACKGROUND START === */

/*
 * Keep Sign in, Create account and Email verification
 * on the same clean white storefront canvas.
 *
 * Authentication logic is untouched.
 */

.st-auth-clean,
.st-retail-auth,
.st-account-verification {
  background: #ffffff !important;
}

/*
 * Remove warm / beige decorative auth-page glows.
 * The cards themselves remain white and elevated.
 */
.st-auth-clean::before,
.st-auth-clean::after,
.st-retail-auth::before,
.st-retail-auth::after,
.st-account-verification::before,
.st-account-verification::after,
.st-auth-clean__glow,
.st-retail-auth__glow,
.st-account-verification__glow {
  display: none !important;
}

/*
 * Some previous auth versions place the background
 * on an inner stage rather than the page wrapper.
 */
.st-auth-clean__stage,
.st-retail-auth__stage,
.st-account-verification__stage {
  background: #ffffff !important;

  background-image: none !important;
}

/*
 * Preserve the premium card distinction without
 * creating another coloured page section.
 */
.st-auth-clean__card,
.st-account-verification__card {
  background: #ffffff !important;
}

/*
 * Ensure the transition into the storefront footer
 * stays visually continuous.
 */
.st-auth-clean,
.st-retail-auth,
.st-account-verification {
  box-shadow: none !important;
}

/* === STEREOPHONIE CLEAN AUTH WHITE BACKGROUND END === */

/* === PREMIUM AUTH CTA START === */

/*
 * Refined storefront CTA.
 * Neutral by default, warm Stereophonie mustard on interaction.
 */

.st-auth-clean button[type="submit"] {
  position: relative;
  overflow: hidden;

  background: #fff !important;
  color: #1d1d1f !important;

  border: 1px solid rgba(185, 132, 37, 0.34) !important;
  border-radius: 13px !important;

  box-shadow:
    0 1px 2px rgba(0, 0, 0, 0.025),
    0 5px 16px rgba(0, 0, 0, 0.025) !important;

  transition:
    background-color 220ms ease,
    border-color 220ms ease,
    box-shadow 220ms ease,
    transform 220ms ease,
    color 220ms ease !important;
}

/* Very subtle warm surface before hover. */
.st-auth-clean button[type="submit"]::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;

  background: linear-gradient(
    100deg,
    rgba(244, 181, 62, 0),
    rgba(244, 181, 62, 0.1),
    rgba(244, 181, 62, 0)
  );

  opacity: 0;
  transform: translateX(-18%);

  transition:
    opacity 240ms ease,
    transform 420ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* Premium mustard interaction — not a solid yellow button. */
@media (hover: hover) {
  .st-auth-clean button[type="submit"]:not(:disabled):hover {
    background: #fffaf0 !important;
    border-color: rgba(190, 132, 24, 0.62) !important;

    box-shadow:
      0 1px 2px rgba(0, 0, 0, 0.02),
      0 8px 24px rgba(184, 127, 23, 0.1) !important;

    transform: translateY(-1px);
  }

  .st-auth-clean button[type="submit"]:not(:disabled):hover::before {
    opacity: 1;
    transform: translateX(18%);
  }

  .st-auth-clean button[type="submit"]:not(:disabled):hover svg {
    transform: translateX(3px);
  }
}

.st-auth-clean button[type="submit"] svg {
  position: relative;
  z-index: 1;

  transition: transform 260ms cubic-bezier(0.16, 1, 0.3, 1);
}

.st-auth-clean button[type="submit"] > * {
  position: relative;
  z-index: 1;
}

/* Keyboard accessibility */
.st-auth-clean button[type="submit"]:focus-visible {
  outline: none !important;

  border-color: rgba(183, 125, 20, 0.75) !important;

  box-shadow:
    0 0 0 4px rgba(217, 164, 63, 0.13),
    0 6px 20px rgba(0, 0, 0, 0.04) !important;
}

/* Keep disabled registration/sign-in states quiet. */
.st-auth-clean button[type="submit"]:disabled {
  background: #f7f7f8 !important;
  color: #aaa9ad !important;

  border-color: #ececef !important;

  box-shadow: none !important;
  cursor: not-allowed;
  transform: none !important;
}

/* Touch feedback */
.st-auth-clean button[type="submit"]:not(:disabled):active {
  transform: scale(0.995);
  background: #fff7e8 !important;
}

/* === PREMIUM AUTH CTA END === */

/* === STEREOPHONIE PREMIUM SIGN OUT MODAL START === */

/*
 * Visual-only refinement.
 * Sign-out logic and Supabase actions remain untouched.
 */

/* Modal shell / rounded architecture */
.stable-modal,
[role="dialog"] .st-retail-signout {
  border-radius: 24px !important;
}

/* Main sign-out content spacing */
.st-retail-signout {
  border-radius: 22px !important;
}

/* Top sign-out icon */
.st-retail-signout__icon {
  width: 44px;
  height: 44px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px !important;

  border: 1px solid rgba(190, 132, 24, 0.18);
  background: #fff9ee;

  color: #9a6508;
}

/* Information note */
.st-retail-signout__note {
  border-radius: 14px !important;

  border: 1px solid rgba(29, 29, 31, 0.08) !important;

  background: #f7f7f8 !important;
  color: #6e6e73 !important;

  padding: 14px 16px;
}

/* Action row */
.st-retail-signout__actions {
  gap: 12px;
}

.st-retail-signout__actions form {
  width: 100%;
}

/* Shared premium button system */
.st-retail-signout__cancel,
.st-retail-signout__confirm {
  position: relative;
  overflow: hidden;

  width: 100%;

  min-height: 48px;

  border-radius: 14px !important;

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;

  transition:
    background-color 220ms ease,
    border-color 220ms ease,
    color 220ms ease,
    box-shadow 220ms ease,
    transform 220ms ease !important;
}

/* -------------------------------------------------------
   STAY SIGNED IN
   White + mustard outline + soft mustard interaction
-------------------------------------------------------- */

.st-retail-signout__cancel {
  border: 1px solid rgba(185, 132, 37, 0.42) !important;

  background: #ffffff !important;
  color: #7d560b !important;

