}

.st-retail-signout__cancel::before {
  content: "";
  position: absolute;
  inset: 0;

  pointer-events: none;

  background: linear-gradient(
    100deg,
    rgba(244, 181, 62, 0),
    rgba(244, 181, 62, 0.12),
    rgba(244, 181, 62, 0)
  );

  opacity: 0;
  transform: translateX(-18%);

  transition:
    opacity 240ms ease,
    transform 420ms cubic-bezier(0.16, 1, 0.3, 1);
}

@media (hover: hover) {
  .st-retail-signout__cancel:hover {
    background: #fffaf0 !important;

    border-color: rgba(190, 132, 24, 0.68) !important;

    color: #6f4a06 !important;

    box-shadow: 0 7px 22px rgba(184, 127, 23, 0.1) !important;

    transform: translateY(-1px);
  }

  .st-retail-signout__cancel:hover::before {
    opacity: 1;
    transform: translateX(18%);
  }
}

.st-retail-signout__cancel:active {
