 */
button.st3-whatsapp-launcher .st3-ai-launcher__icon-layer--ai,
button.st3-whatsapp-launcher .st3-ai-launcher__icon-layer--close {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  transform: scale(0.84) !important;
}

/*
 * WhatsApp icon is permanently visible.
 */
button.st3-whatsapp-launcher .st3-ai-launcher__icon-layer--whatsapp {
  opacity: 1 !important;
  visibility: visible !important;
  transform: none !important;
}

/* ==========================================================
   NEW AI VERTICAL EDGE TAB
   ========================================================== */

.st3-ai-edge-tab {
  --st-ai-drawer-width: min(410px, calc(100vw - 24px));

  position: fixed;

  right: 0;

  top: 50%;

  z-index: 1302;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  gap: 11px;

  width: 52px;

  min-height: 174px;

  padding: 16px 10px 18px;

  transform: translateY(-50%);

  border: 1px solid rgba(29, 29, 31, 0.1);

  border-right: 0;

  border-radius: 18px 0 0 18px;

  background: rgba(255, 255, 255, 0.94);

  color: #1d1d1f;

  box-shadow:
    -10px 14px 36px rgba(0, 0, 0, 0.08),
    -1px 0 0 rgba(255, 255, 255, 0.9) inset;

  -webkit-backdrop-filter: blur(22px) saturate(145%);

  backdrop-filter: blur(22px) saturate(145%);

  cursor: pointer;

  overflow: hidden;

  transition:
    right 520ms cubic-bezier(0.16, 1, 0.3, 1),
    width 260ms cubic-bezier(0.16, 1, 0.3, 1),
    background-color 220ms ease,
    border-color 220ms ease,
    box-shadow 220ms ease,
    transform 220ms ease;
}

/*
 * Warm Stereophonie light wash.
 */
.st3-ai-edge-tab::before {
  content: "";

  position: absolute;

  inset: 0;

  pointer-events: none;

  background: linear-gradient(
    180deg,
    rgba(245, 179, 53, 0),
    rgba(245, 179, 53, 0.075),
    rgba(245, 179, 53, 0)
  );

  opacity: 0.75;
}

/*
 * When open, the tab travels left together with the drawer.
 */
.st3-ai-edge-tab.is-open {
  right: var(--st-ai-drawer-width);

  border-right: 1px solid rgba(29, 29, 31, 0.08);

  border-radius: 18px 0 0 18px;

  box-shadow: -8px 12px 32px rgba(0, 0, 0, 0.07);
}

@media (hover: hover) {
  .st3-ai-edge-tab:hover {
    background: #fffaf0;

    border-color: rgba(185, 132, 37, 0.28);

    box-shadow: -12px 18px 42px rgba(157, 108, 21, 0.1);

    transform: translateY(-50%) translateX(-3px);
  }

  .st3-ai-edge-tab.is-open:hover {
    transform: translateY(-50%);
  }
}

.st3-ai-edge-tab:focus-visible {
  outline: none;

  box-shadow:
    -8px 12px 32px rgba(0, 0, 0, 0.07),
    0 0 0 4px rgba(217, 164, 63, 0.14);
}

/* Live indicator */
.st3-ai-edge-tab__status {
  position: relative;

  z-index: 2;

  width: 8px;

  height: 8px;

  flex: 0 0 auto;

  border-radius: 999px;

  background: #c58b23;

  box-shadow: 0 0 0 5px rgba(197, 139, 35, 0.1);
}

/* Robot */
.st3-ai-edge-tab__icon {
  position: relative;

  z-index: 2;

  display: grid;

  place-items: center;

  width: 27px;

  height: 27px;

  color: #1d1d1f;
}

.st3-ai-edge-tab__icon svg {
  width: 21px;

  height: 21px;

  display: block;
}

/* Vertical label */
.st3-ai-edge-tab__text {
  position: relative;

  z-index: 2;

  writing-mode: vertical-rl;

  transform: rotate(180deg);

  white-space: nowrap;

  font-size: 9px;

  font-weight: 700;

  line-height: 1;

  letter-spacing: 0.18em;

  text-transform: uppercase;

  color: rgba(29, 29, 31, 0.7);
}

/* ==========================================================
   AI PANEL — APPLE-LIKE RIGHT DRAWER
   ========================================================== */

.st3-ai-panel {
  --st-ai-drawer-width: min(410px, calc(100vw - 24px));

  position: fixed !important;

  top: 0 !important;

  right: 0 !important;

  bottom: 0 !important;

  left: auto !important;

  z-index: 1301 !important;

  width: var(--st-ai-drawer-width) !important;

  max-width: none !important;

  height: 100dvh !important;

  max-height: none !important;

  margin: 0 !important;

  display: flex !important;

  flex-direction: column !important;

  border: 1px solid rgba(29, 29, 31, 0.09) !important;

  border-right: 0 !important;

  border-radius: 26px 0 0 26px !important;

  background: rgba(255, 255, 255, 0.975) !important;

  color: #1d1d1f !important;

  box-shadow: -30px 0 80px rgba(0, 0, 0, 0.11) !important;

  -webkit-backdrop-filter: blur(28px) saturate(145%) !important;

  backdrop-filter: blur(28px) saturate(145%) !important;

  overflow: hidden !important;

  opacity: 0 !important;

  visibility: hidden !important;

  pointer-events: none !important;

  transform: translate3d(102%, 0, 0) !important;

  transform-origin: right center !important;

  transition:
    transform 520ms cubic-bezier(0.16, 1, 0.3, 1),
    opacity 280ms ease,
    visibility 0s linear 520ms !important;
}

.st3-ai-panel.st3-ai-panel--open {
