  }
}

/* ==========================================================
   GENERAL DRAWER SURFACES
   ========================================================== */

/*
 * Convert legacy black assistant surfaces to the current
 * Stereophonie white / Apple-like visual system.
 */

.st3-ai-panel
  :is(
    [class*="body"],
    [class*="content"],
    [class*="conversation"],
    [class*="messages"],
    [class*="scroll"]
  ) {
  background: transparent !important;

  color: #1d1d1f !important;
}

.st3-ai-panel :is(p, span, label) {
  border-color: rgba(29, 29, 31, 0.08);
}

.st3-ai-panel
  :is(
    [class*="message"],
    [class*="bubble"],
    [class*="card"],
    [class*="suggestion"],
    [class*="prompt"]
  ) {
  border-color: rgba(29, 29, 31, 0.085) !important;

  border-radius: 16px !important;
}

/*
 * Neutral assistant bubbles/cards.
 */
.st3-ai-panel :is([class*="message"], [class*="bubble"], [class*="card"]) {
  color: #1d1d1f;
}

/* ==========================================================
   INPUT AREA
   ========================================================== */

.st3-ai-panel :is(input, textarea) {
  border: 1px solid rgba(29, 29, 31, 0.1) !important;

  border-radius: 14px !important;

  background: #f7f7f8 !important;

  color: #1d1d1f !important;

  box-shadow: none !important;

  outline: none !important;

  transition:
    background-color 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease !important;
}

.st3-ai-panel :is(input, textarea)::placeholder {
  color: rgba(29, 29, 31, 0.36) !important;
}

.st3-ai-panel :is(input, textarea):focus {
  background: #fff !important;

  border-color: rgba(190, 132, 24, 0.45) !important;

  box-shadow: 0 0 0 4px rgba(217, 164, 63, 0.1) !important;
}

/* ==========================================================
   DRAWER BUTTON SYSTEM
   ========================================================== */

.st3-ai-panel button {
  border-radius: 12px;
}

/*
 * Remove aggressive dark buttons where the assistant
 * previously used the old black interface.
 */
.st3-ai-panel button:not([aria-label*="Close" i]) {
  transition:
    background-color 190ms ease,
    border-color 190ms ease,
    color 190ms ease,
    box-shadow 190ms ease,
    transform 190ms ease;
}

/*
 * Send/action controls get the same restrained mustard
 * language used on the login/create-account buttons.
 */
.st3-ai-panel button[type="submit"] {
  border: 1px solid rgba(185, 132, 37, 0.38) !important;

  background: #ffffff !important;

  color: #795208 !important;

  box-shadow: 0 4px 14px rgba(184, 127, 23, 0.04) !important;
}

@media (hover: hover) {
  .st3-ai-panel button[type="submit"]:hover {
