}

.st3-ai-panel *::-webkit-scrollbar-track {
  background: transparent;
}

.st3-ai-panel *::-webkit-scrollbar-thumb {
  background: rgba(29, 29, 31, 0.16);

  border-radius: 999px;
}

/* ==========================================================
   MOBILE / TABLET
   ========================================================== */

@media (max-width: 700px) {
  .st3-ai-edge-tab {
    --st-ai-drawer-width: calc(100vw - 18px);

    width: 46px;

    min-height: 146px;

    padding: 14px 8px;

    border-radius: 16px 0 0 16px;
  }

  .st3-ai-edge-tab__text {
    font-size: 8px;

    letter-spacing: 0.16em;
  }

