    --st-ai-drawer-width: calc(100vw - 18px);

    border-radius: 22px 0 0 22px !important;
  }

  .st3-ai-panel__top {
    padding: 22px 20px 18px !important;
  }

  button.st3-whatsapp-launcher,
  button.st3-ai-launcher.st3-whatsapp-launcher {
    right: 18px !important;

    bottom: 18px !important;
  }
