/* ==========================================================
   REDUCED MOTION
   ========================================================== */

@media (prefers-reduced-motion: reduce) {
  .st3-ai-edge-tab,
  .st3-ai-panel {
    transition-duration: 1ms !important;
  }
}

/* === STEREOPHONIE APPLE AI DRAWER END === */

/* === STEREOPHONIE COMPACT APPLE AI ASSISTANT START === */

/*
 * =========================================================
 * STEREOPHONIE AI ASSISTANT
 *
 * Final architecture:
 *
 * - Bottom-right launcher = WhatsApp only
 * - AI control = compact vertical side tab
 * - Side tab remains vertically centered at all times
 * - No breathing / live dot
 * - Small mustard AI icon
 * - Compact floating assistant instead of full-height drawer
 * - Apple-inspired white / glass interface
 * =========================================================
 */

/* ---------------------------------------------------------
   SHARED DRAWER SIZE
   --------------------------------------------------------- */

:root {
  --st-ai-compact-width: min(390px, calc(100vw - 90px));

  --st-ai-compact-height: min(570px, calc(100dvh - 110px));
}

/* =========================================================
   1. COMPACT VERTICAL AI TAB
   ========================================================= */

button.st3-ai-edge-tab,
.st3-ai-edge-tab[data-st-ai-edge-launcher="true"],
button[data-st-ai-edge-launcher="true"] {
  position: fixed !important;

  top: 50% !important;

  right: 9px !important;

  bottom: auto !important;

  left: auto !important;

  z-index: 9998 !important;

  /*
   * IMPORTANT:
   * This keeps the button locked to the exact same
   * vertical position whether open or closed.
   */
  transform: translateY(-50%) !important;

  width: 44px !important;

  min-width: 44px !important;

  max-width: 44px !important;

  height: 142px !important;

  min-height: 142px !important;

  max-height: 142px !important;

  padding: 10px 6px !important;

  display: flex !important;

  flex-direction: column !important;

  align-items: center !important;

  justify-content: center !important;

  gap: 10px !important;

  border: 1px solid rgba(185, 132, 37, 0.24) !important;

  border-right: 0 !important;

  border-radius: 17px 0 0 17px !important;

  background: rgba(255, 255, 255, 0.94) !important;

  color: #1d1d1f !important;

  box-shadow:
    -8px 12px 34px rgba(0, 0, 0, 0.075),
    inset 0 1px 0 rgba(255, 255, 255, 0.95) !important;

  backdrop-filter: blur(22px) saturate(145%) !important;

  -webkit-backdrop-filter: blur(22px) saturate(145%) !important;

  overflow: hidden !important;

  transition:
    right 360ms cubic-bezier(0.16, 1, 0.3, 1),
    border-color 220ms ease,
    background-color 220ms ease,
    box-shadow 260ms ease !important;
}

/*
 * When the assistant opens:
 *
 * ONLY move horizontally.
 *
 * No translateY change.
 * No top change.
 * No jumping down.
 */
button.st3-ai-edge-tab.is-open,
.st3-ai-edge-tab.is-open[data-st-ai-edge-launcher="true"],
button[data-st-ai-edge-launcher="true"].is-open {
  right: calc(var(--st-ai-compact-width) + 29px) !important;

  top: 50% !important;

  transform: translateY(-50%) !important;
}

/* ---------------------------------------------------------
   Hover
   --------------------------------------------------------- */

@media (hover: hover) {
  button.st3-ai-edge-tab:hover,
  .st3-ai-edge-tab[data-st-ai-edge-launcher="true"]:hover {
    background: #fffaf1 !important;

    border-color: rgba(190, 132, 24, 0.48) !important;

    box-shadow:
      -9px 14px 38px rgba(174, 116, 16, 0.1),
      inset 0 1px 0 rgba(255, 255, 255, 0.98) !important;
  }
}

/* =========================================================
   2. REMOVE THE BREATHING / LIVE DOT
   ========================================================= */

.st3-ai-edge-tab__status {
  display: none !important;

  opacity: 0 !important;

  visibility: hidden !important;

  animation: none !important;
}

/*
 * Defensive:
 * remove pseudo-element status glows from the tab.
 */
.st3-ai-edge-tab__status::before,
.st3-ai-edge-tab__status::after {
  content: none !important;

  display: none !important;

  animation: none !important;
}

/* =========================================================
   3. MUSTARD AI ICON
   ========================================================= */

/*
 * This is the element which currently appears as
 * the small dark / black square.
 */

.st3-ai-edge-tab__icon {
  flex: 0 0 auto !important;

  width: 25px !important;

  height: 25px !important;

  display: grid !important;

  place-items: center !important;

  margin: 0 !important;

  border: 1px solid rgba(180, 119, 15, 0.24) !important;

  border-radius: 8px !important;

  background: #f5b335 !important;

  color: #1d1d1f !important;

  box-shadow: 0 4px 12px rgba(209, 143, 22, 0.15) !important;

  transform: none !important;

  animation: none !important;
}

.st3-ai-edge-tab__icon svg {
  width: 13px !important;

  height: 13px !important;

  display: block !important;

  transform: none !important;
}

/* =========================================================
   4. VERTICAL AI ASSISTANT LABEL
   ========================================================= */

.st3-ai-edge-tab__text {
  display: block !important;

  writing-mode: vertical-rl !important;

  text-orientation: mixed !important;

  transform: rotate(180deg) !important;

  margin: 0 !important;

  font-size: 8px !important;

  line-height: 1 !important;

  font-weight: 650 !important;

  letter-spacing: 0.18em !important;

  text-transform: uppercase !important;

  white-space: nowrap !important;

  color: #49494d !important;
}

/* =========================================================
   5. COMPACT FLOATING AI ASSISTANT
   ========================================================= */

/*
 * Replace the current full-height right drawer with
 * the compact floating assistant window.
 */

.st3-ai-panel,
#stereophonie-ai-drawer {
  position: fixed !important;

  top: 50% !important;

  right: 18px !important;

  bottom: auto !important;

  left: auto !important;

  width: var(--st-ai-compact-width) !important;

  min-width: 0 !important;

  max-width: 390px !important;

  height: var(--st-ai-compact-height) !important;

  min-height: 0 !important;

  max-height: 570px !important;

  z-index: 9997 !important;

  border: 1px solid rgba(29, 29, 31, 0.09) !important;

  border-radius: 26px !important;

  background: rgba(255, 255, 255, 0.965) !important;

  color: #1d1d1f !important;

  overflow: hidden !important;

  box-shadow:
    0 30px 90px rgba(0, 0, 0, 0.14),
    0 8px 28px rgba(0, 0, 0, 0.055),
    inset 0 1px 0 rgba(255, 255, 255, 0.95) !important;

  backdrop-filter: blur(30px) saturate(150%) !important;

  -webkit-backdrop-filter: blur(30px) saturate(150%) !important;

  /*
   * CLOSED STATE
   *
   * Keep vertical centering constant.
   * Only X changes.
   */
  transform: translate3d(calc(100% + 40px), -50%, 0) !important;

  opacity: 0 !important;

  pointer-events: none !important;

  transition:
    transform 420ms cubic-bezier(0.16, 1, 0.3, 1),
    opacity 240ms ease !important;
}

/* ---------------------------------------------------------
   OPEN DRAWER
   --------------------------------------------------------- */

.st3-ai-panel.st3-ai-panel--open,
#stereophonie-ai-drawer.st3-ai-panel--open {
  transform: translate3d(0, -50%, 0) !important;

  opacity: 1 !important;

  pointer-events: auto !important;
}

/* =========================================================
   6. ASSISTANT INTERNAL ARCHITECTURE
   ========================================================= */

/*
 * The assistant content must stay inside the compact card,
 * never force the panel to become full-height.
 */

.st3-ai-panel {
  display: flex !important;

  flex-direction: column !important;
}

/* Header */

.st3-ai-panel__top {
  flex: 0 0 auto !important;

  padding: 18px 18px 15px !important;

  border-bottom: 1px solid rgba(29, 29, 31, 0.075) !important;

  background: rgba(255, 255, 255, 0.92) !important;
}

.st3-ai-panel__top h2 {
  color: #1d1d1f !important;

  font-size: 21px !important;

  line-height: 1.05 !important;

  letter-spacing: -0.035em !important;
}

.st3-ai-panel__eyebrow {
  color: #9a680d !important;
}

/*
 * Make close buttons Apple-like.
 */

.st3-ai-panel__top button {
  border-radius: 50% !important;
}

/* =========================================================
   7. SCROLLABLE CHAT CONTENT
   ========================================================= */

/*
 * Allow whatever existing message/body container exists
 * to consume remaining height without expanding the drawer.
 */

.st3-ai-panel > :not(.st3-ai-panel__top):not(form) {
  min-height: 0;
}

/*
 * Common message-area selectors.
 */

.st3-ai-panel__messages,
.st3-ai-panel__conversation,
.st3-ai-panel__body,
.st3-ai-panel__content {
  min-height: 0 !important;

  flex: 1 1 auto !important;

  overflow-y: auto !important;

  overscroll-behavior: contain !important;
}

/* =========================================================
   8. CHAT CARDS / SUGGESTIONS
   ========================================================= */

.st3-ai-panel
  :is(
    .st3-ai-message,
    .st3-ai-panel__message,
    .st3-ai-panel__suggestion,
    [class*="message"]
  ) {
  border-radius: 16px !important;
}

/*
 * Suggested prompt pills / cards.
 */

.st3-ai-panel button:not([aria-label]) {
  border-radius: 14px;
}

/* =========================================================
   9. INPUT AREA
   ========================================================= */

.st3-ai-panel form {
  flex: 0 0 auto !important;
}

.st3-ai-panel input,
.st3-ai-panel textarea {
  border-radius: 14px !important;
}

/* =========================================================
   10. DESKTOP VERTICAL STABILITY
   ========================================================= */

/*
 * Very important:
 *
 * Old CSS may try to change:
 * - top
 * - bottom
 * - translateY
 * - margin-top
 *
 * Prevent that from lowering the tab when open.
 */

.st3-ai-edge-tab,
.st3-ai-edge-tab.is-open {
  margin-top: 0 !important;

  margin-bottom: 0 !important;

  translate: none !important;
}

/* =========================================================
   11. TABLET
   ========================================================= */

@media (max-width: 900px) {
  :root {
    --st-ai-compact-width: min(370px, calc(100vw - 78px));

    --st-ai-compact-height: min(560px, calc(100dvh - 90px));
  }

  button.st3-ai-edge-tab,
  .st3-ai-edge-tab[data-st-ai-edge-launcher="true"] {
    width: 42px !important;

    min-width: 42px !important;

    height: 136px !important;

    min-height: 136px !important;
  }

  button.st3-ai-edge-tab.is-open,
  .st3-ai-edge-tab.is-open[data-st-ai-edge-launcher="true"] {
    right: calc(var(--st-ai-compact-width) + 24px) !important;
  }

  .st3-ai-panel,
  #stereophonie-ai-drawer {
    right: 12px !important;
  }
}

/* =========================================================
   12. MOBILE
   ========================================================= */

@media (max-width: 640px) {
  :root {
    --st-ai-compact-width: calc(100vw - 24px);

    --st-ai-compact-height: min(560px, calc(100dvh - 78px));
  }

  .st3-ai-panel,
  #stereophonie-ai-drawer {
    width: calc(100vw - 24px) !important;

    max-width: none !important;

    height: var(--st-ai-compact-height) !important;

    max-height: calc(100dvh - 78px) !important;

    right: 12px !important;

    border-radius: 23px !important;
  }

  /*
   * Keep the mobile tab compact.
   */

  button.st3-ai-edge-tab,
  .st3-ai-edge-tab[data-st-ai-edge-launcher="true"] {
    right: 4px !important;

    width: 39px !important;

    min-width: 39px !important;

    height: 126px !important;

    min-height: 126px !important;

    border-radius: 15px 0 0 15px !important;
  }

  /*
   * Do not move the tab outside the viewport on phones.
   * Drawer remains independently closable.
   */

  button.st3-ai-edge-tab.is-open,
  .st3-ai-edge-tab.is-open[data-st-ai-edge-launcher="true"] {
    right: 4px !important;

    top: 50% !important;

    transform: translateY(-50%) !important;
  }

  .st3-ai-edge-tab__icon {
    width: 23px !important;

    height: 23px !important;
  }

  .st3-ai-edge-tab__text {
    font-size: 7px !important;
  }
}

/* =========================================================
   13. REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {
  .st3-ai-edge-tab,
  .st3-ai-panel,
  #stereophonie-ai-drawer {
    transition: none !important;
  }
}

/* === STEREOPHONIE COMPACT APPLE AI ASSISTANT END === */

/* === STEREOPHONIE FINAL AI SIDE TAB POLISH START === */

/*
 * =========================================================
 * COMPACT AI SIDE CONTROL
 *
 * - substantially thinner
 * - shorter
 * - tiny mustard indicator
 * - fixed vertical centre
 * - sits beside popup when open
 * - small intentional gap
 * - no X inside popup
 * =========================================================
 */

/* ---------------------------------------------------------
   1. THINNER SIDE TAB
   --------------------------------------------------------- */

button.st3-ai-edge-tab,
.st3-ai-edge-tab[data-st-ai-edge-launcher="true"],
button[data-st-ai-edge-launcher="true"] {
  top: 50% !important;

  bottom: auto !important;

  right: 6px !important;

  width: 34px !important;

  min-width: 34px !important;

  max-width: 34px !important;

  height: 118px !important;

  min-height: 118px !important;

  max-height: 118px !important;

  padding: 8px 4px !important;

  gap: 7px !important;

  border-radius: 14px 0 0 14px !important;

  transform: translateY(-50%) !important;

  margin: 0 !important;

  transition:
    right 380ms cubic-bezier(0.16, 1, 0.3, 1),
    background-color 220ms ease,
    border-color 220ms ease,
    box-shadow 240ms ease !important;
}

/* ---------------------------------------------------------
   2. KEEP IT PERFECTLY CENTRED WHEN OPEN
   --------------------------------------------------------- */

button.st3-ai-edge-tab.is-open,
.st3-ai-edge-tab.is-open[data-st-ai-edge-launcher="true"],
button[data-st-ai-edge-launcher="true"].is-open {
  top: 50% !important;

  bottom: auto !important;

  /*
   * Assistant:
   * 18px from viewport edge
   *
   * Tab:
   * 8px gap from assistant edge
   */
  right: calc(var(--st-ai-compact-width) + 26px) !important;

  transform: translateY(-50%) !important;

  margin: 0 !important;
}

/* ---------------------------------------------------------
   3. REMOVE OLD BREATHING STATUS DOT ENTIRELY
   --------------------------------------------------------- */

.st3-ai-edge-tab__status,
.st3-ai-edge-tab__status::before,
.st3-ai-edge-tab__status::after {
  display: none !important;

  content: none !important;

  width: 0 !important;

  height: 0 !important;

  opacity: 0 !important;

  visibility: hidden !important;

  animation: none !important;
}

/* ---------------------------------------------------------
   4. TINY MUSTARD INDICATOR
   --------------------------------------------------------- */

/*
 * This replaces the oversized mustard square.
 *
 * It is intentionally approximately the same visual
 * scale as the AI ASSISTANT lettering.
 */

.st3-ai-edge-tab__icon {
  width: 9px !important;

  height: 9px !important;

  min-width: 9px !important;

  min-height: 9px !important;

  flex: 0 0 9px !important;

  padding: 0 !important;

  margin: 0 !important;

  border: 0 !important;

  border-radius: 3px !important;

  background: #f5b335 !important;

  color: transparent !important;

  box-shadow: 0 0 0 3px rgba(245, 179, 53, 0.09) !important;

  overflow: hidden !important;
}

/*
 * Hide the robot drawing inside this tiny indicator.
 * The mustard square itself becomes the visual signal.
 */
.st3-ai-edge-tab__icon svg,
.st3-ai-edge-tab__icon > * {
  display: none !important;
}

/* ---------------------------------------------------------
   5. SMALLER VERTICAL LABEL
   --------------------------------------------------------- */

.st3-ai-edge-tab__text {
  font-size: 7px !important;

  font-weight: 650 !important;

  line-height: 1 !important;

  letter-spacing: 0.17em !important;

  color: #444448 !important;

  margin: 0 !important;
}

/* ---------------------------------------------------------
   6. POPUP + TAB INTEGRATION
   --------------------------------------------------------- */

/*
 * Keep the popup itself exactly where the compact version
 * currently sits.
 */

.st3-ai-panel,
#stereophonie-ai-drawer {
  right: 18px !important;
}

/*
 * Tab visually pairs with the assistant without touching it.
 */

.st3-ai-edge-tab.is-open {
  box-shadow:
    -5px 9px 24px rgba(0, 0, 0, 0.07),
    0 0 0 1px rgba(185, 132, 37, 0.025) !important;
}

/* ---------------------------------------------------------
   7. REMOVE TOP X CLOSE BUTTON
   --------------------------------------------------------- */

/*
 * Closing is now handled by:
 * 1. clicking AI Assistant side tab
 * 2. clicking outside the assistant
 */

.st3-ai-panel__top button[aria-label*="Close" i],
.st3-ai-panel__top button[title*="Close" i],
#stereophonie-ai-drawer button[aria-label*="Close" i] {
  display: none !important;
}

/* ---------------------------------------------------------
   8. REBALANCE HEADER AFTER X REMOVAL
   --------------------------------------------------------- */

.st3-ai-panel__top {
  padding-right: 18px !important;
}

/* ---------------------------------------------------------
   9. HOVER — VERY SUBTLE
   --------------------------------------------------------- */

@media (hover: hover) {
  button.st3-ai-edge-tab:hover,
  .st3-ai-edge-tab[data-st-ai-edge-launcher="true"]:hover {
    background: #fffaf1 !important;

    border-color: rgba(190, 132, 24, 0.46) !important;
  }

  button.st3-ai-edge-tab:hover .st3-ai-edge-tab__icon {
    background: #e9a321 !important;

    box-shadow: 0 0 0 4px rgba(245, 179, 53, 0.1) !important;
  }
}

/* ---------------------------------------------------------
   10. MOBILE
   --------------------------------------------------------- */

@media (max-width: 640px) {
  button.st3-ai-edge-tab,
  .st3-ai-edge-tab[data-st-ai-edge-launcher="true"] {
    width: 32px !important;

    min-width: 32px !important;

    height: 108px !important;

    min-height: 108px !important;

    right: 3px !important;

    border-radius: 13px 0 0 13px !important;
  }

  /*
   * On smaller screens the drawer fills nearly all width,
   * so leave the control anchored to the viewport edge.
   */
  button.st3-ai-edge-tab.is-open,
  .st3-ai-edge-tab.is-open[data-st-ai-edge-launcher="true"] {
    right: 3px !important;

    top: 50% !important;

    transform: translateY(-50%) !important;
  }

  .st3-ai-edge-tab__icon {
    width: 8px !important;

    height: 8px !important;

    min-width: 8px !important;

    min-height: 8px !important;
  }

  .st3-ai-edge-tab__text {
    font-size: 6.5px !important;
  }
}

/* === STEREOPHONIE FINAL AI SIDE TAB POLISH END === */

/* === STEREOPHONIE AI TAB EDGE ATTACHMENT START === */

/*
 * CLOSED STATE
 *
 * The vertical AI Assistant tab should behave like a true
 * screen-edge handle: no empty strip between the tab and
 * the right edge of the viewport.
 */
button.st3-ai-edge-tab,
.st3-ai-edge-tab[data-st-ai-edge-launcher="true"],
button[data-st-ai-edge-launcher="true"] {
  right: 0 !important;

  top: 50% !important;
  bottom: auto !important;

  transform: translateY(-50%) !important;

  margin: 0 !important;

  border-radius: 14px 0 0 14px !important;

  /*
   * Keep the right edge visually flush with the viewport.
   */
  border-right-width: 0 !important;
}

/*
 * OPEN STATE
 *
 * The popup already sits a short distance from the right
 * side of the viewport.
 *
 * When open, move the tab to EXACTLY the popup's left edge.
 * No intentional gap. The two surfaces should visually
 * connect as one integrated assistant interface.
 */
button.st3-ai-edge-tab.is-open,
.st3-ai-edge-tab.is-open[data-st-ai-edge-launcher="true"],
button[data-st-ai-edge-launcher="true"].is-open {
  right: calc(var(--st-ai-compact-width) + 18px) !important;

  top: 50% !important;
  bottom: auto !important;

  transform: translateY(-50%) !important;

  margin: 0 !important;

  /*
   * Join cleanly to the assistant panel.
   */
  border-radius: 14px 0 0 14px !important;

  box-shadow: -8px 8px 24px rgba(29, 29, 31, 0.06) !important;
}

/*
 * Remove any previous translate / offset rules that could
 * visually create space or make the tab jump.
 */
button.st3-ai-edge-tab.is-open,
.st3-ai-edge-tab.is-open[data-st-ai-edge-launcher="true"],
button[data-st-ai-edge-launcher="true"].is-open {
  translate: none !important;
}

/*
 * Keep the drawer itself in its current compact location.
 * This does NOT alter its width, height, or internal design.
 */
#stereophonie-ai-drawer.st3-ai-panel {
  right: 18px !important;
}

/*
 * Defensive mobile behavior:
 * still keep the tab at the viewport edge while closed.
 */
@media (max-width: 640px) {
  button.st3-ai-edge-tab,
  .st3-ai-edge-tab[data-st-ai-edge-launcher="true"],
  button[data-st-ai-edge-launcher="true"] {
    right: 0 !important;
  }

  button.st3-ai-edge-tab.is-open,
  .st3-ai-edge-tab.is-open[data-st-ai-edge-launcher="true"],
  button[data-st-ai-edge-launcher="true"].is-open {
    right: calc(var(--st-ai-compact-width) + 10px) !important;
  }

  #stereophonie-ai-drawer.st3-ai-panel {
    right: 10px !important;
  }
}

/* === STEREOPHONIE AI TAB EDGE ATTACHMENT END === */

/* === ST AI TAB ZERO GAP START === */

/*
 * FINAL AI TAB / POPUP CONNECTION
 *
 * The assistant tab and popup should visually behave
 * as one connected Apple-like interface.
 *
 * We intentionally overlap the tab into the popup by 2px.
 * This removes Safari/browser sub-pixel hairline gaps.
 */

button.st3-ai-edge-tab.is-open,
.st3-ai-edge-tab.is-open[data-st-ai-edge-launcher="true"],
button[data-st-ai-edge-launcher="true"].is-open {
  /*
   * Popup right offset = 18px.
   * Tab must sit directly against its left edge.
   *
   * -2px creates a microscopic overlap so no background
   * can appear between the two elements.
   */
  right: calc(var(--st-ai-compact-width) + 16px) !important;

  top: 50% !important;

  transform: translateY(-50%) !important;

  margin: 0 !important;

  /*
   * Keep tab visually above the popup seam.
   */
  z-index: 10002 !important;
}

/*
 * Remove the tab's right border/radius while OPEN.
 * This makes the connection feel intentional rather
 * than like two separate floating cards.
 */
button.st3-ai-edge-tab.is-open,
.st3-ai-edge-tab.is-open[data-st-ai-edge-launcher="true"] {
  border-right-color: transparent !important;

  border-top-right-radius: 0 !important;

  border-bottom-right-radius: 0 !important;
}

/*
 * CLOSED STATE:
 * Keep the tab essentially glued to the right edge
 * of the user's viewport.
 */
button.st3-ai-edge-tab:not(.is-open),
.st3-ai-edge-tab[data-st-ai-edge-launcher="true"]:not(.is-open) {
  right: 0 !important;
}

/* === ST AI TAB ZERO GAP END === */

/* === STEREOPHONIE PREMIUM AI CHAT POLISH START === */

