  border-radius: 50% !important;

  background: #a8a8ad !important;

  opacity: 0.34;

  animation: st-ai-thinking-pulse 1.2s ease-in-out infinite;
}

.st3-ai-thinking span:nth-child(2) {
  animation-delay: 140ms;
}

.st3-ai-thinking span:nth-child(3) {
  animation-delay: 280ms;
}

@keyframes st-ai-thinking-pulse {
  0%,
  60%,
  100% {
    opacity: 0.28;

    transform: translateY(0);
  }

  30% {
    opacity: 0.9;

    transform: translateY(-2px);
  }
}

