/* ========================================================================
   STEREOPHONIE AI ASSISTANT
   TRUE UNIFIED HANDLE + PANEL ARCHITECTURE
   ======================================================================== */

/*
 * IMPORTANT:
 *
 * The panel and the AI Assistant handle no longer animate independently.
 *
 * The .st3-ai-shell itself is the ONLY moving object.
 *
 * OPEN:
 *   entire shell is visible.
 *
 * CLOSED:
 *   entire shell moves right until only the handle remains visible.
 *
 * Therefore the handle physically travels WITH the drawer.
 */

/* ------------------------------------------------------------------------
   1. MASTER ASSISTANT SHELL
   ------------------------------------------------------------------------ */

.st3-ai-shell {
  --st-ai-shell-panel-width: var(--st-ai-compact-width);

  --st-ai-shell-right: 18px;

  --st-ai-shell-handle-width: 34px;

  position: fixed !important;

  top: 50% !important;

  right: var(--st-ai-shell-right) !important;

  width: var(--st-ai-shell-panel-width) !important;

  height: 0 !important;

  margin: 0 !important;

  padding: 0 !important;

  z-index: 10000 !important;

  /*
   * CLOSED STATE
   *
   * Move the complete assistant panel off-screen.
   *
   * Because the handle is attached to the LEFT side of the
   * panel, it lands exactly against the viewport's right edge.
   */
  transform: translate3d(
    calc(var(--st-ai-shell-panel-width) + var(--st-ai-shell-right)),
    0,
    0
  ) !important;

  transition: transform 360ms cubic-bezier(0.22, 0.61, 0.36, 1) !important;

  will-change: transform;

  pointer-events: none !important;
}

/*
 * OPEN STATE
 *
 * One single motion brings BOTH panel and handle into place.
 */

.st3-ai-shell.is-open {
  transform: translate3d(0, 0, 0) !important;
}

/* ------------------------------------------------------------------------
   2. PANEL — CHILD OF THE MOVING SHELL
   ------------------------------------------------------------------------ */

.st3-ai-shell #stereophonie-ai-drawer.st3-ai-panel {
  position: absolute !important;

  top: 50% !important;

  right: 0 !important;

  left: auto !important;

  bottom: auto !important;

  width: var(--st-ai-shell-panel-width) !important;

  /*
   * Vertical centering only.
   *
   * NO horizontal opening animation is allowed here anymore.
   * Horizontal movement belongs exclusively to .st3-ai-shell.
   */
  transform: translateY(-50%) !important;

  translate: none !important;

  margin: 0 !important;

  pointer-events: auto !important;

  /*
   * CRITICAL:
   * prevent historical drawer rules from making it animate
   * separately from the handle.
   */
  transition: opacity 190ms ease !important;

  /*
   * Restore ALL FOUR rounded corners.
   */

  border-radius: 24px !important;

  border-top-left-radius: 24px !important;

  border-bottom-left-radius: 24px !important;

  border-top-right-radius: 24px !important;

  border-bottom-right-radius: 24px !important;

  overflow: hidden !important;
}

/*
 * Closed drawer stays visually hidden while the shell itself
 * moves beyond the viewport.
 */

.st3-ai-shell:not(.is-open) #stereophonie-ai-drawer.st3-ai-panel {
  opacity: 0 !important;

  visibility: hidden !important;
}

/*
 * Opening drawer.
 */

.st3-ai-shell.is-open #stereophonie-ai-drawer.st3-ai-panel {
  opacity: 1 !important;

  visibility: visible !important;
}

/* ------------------------------------------------------------------------
   3. AI ASSISTANT HANDLE
   ------------------------------------------------------------------------ */

.st3-ai-shell button.st3-ai-edge-tab,
.st3-ai-shell .st3-ai-edge-tab[data-st-ai-edge-launcher="true"] {
  position: absolute !important;

  /*
   * Physically attach the handle to the LEFT edge of the drawer.
   */

  left: calc(-1 * var(--st-ai-shell-handle-width)) !important;

  right: auto !important;

  top: 50% !important;

  bottom: auto !important;

  width: var(--st-ai-shell-handle-width) !important;

  min-width: var(--st-ai-shell-handle-width) !important;

  transform: translateY(-50%) !important;

  translate: none !important;

  margin: 0 !important;

  pointer-events: auto !important;

  /*
   * Absolutely NO independent positional animation.
   *
   * The parent shell does all movement.
   */

  transition:
    background-color 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease !important;

  z-index: 2 !important;
}

/* ------------------------------------------------------------------------
   4. HANDLE / PANEL JOIN
   ------------------------------------------------------------------------ */

/*
 * Slight 1px overlap prevents Safari from drawing a tiny
 * background seam between the handle and panel.
 */

.st3-ai-shell.is-open button.st3-ai-edge-tab,
.st3-ai-shell.is-open .st3-ai-edge-tab[data-st-ai-edge-launcher="true"] {
  left: calc(-1 * var(--st-ai-shell-handle-width) + 1px) !important;

  /*
   * Handle behaves like a physical drawer handle.
   */

  border-top-right-radius: 0 !important;

  border-bottom-right-radius: 0 !important;

  border-right-color: transparent !important;

  box-shadow: -7px 7px 22px rgba(29, 29, 31, 0.055) !important;
}

/*
 * Do NOT flatten the drawer corners anymore.
 *
 * It is perfectly valid for the handle to attach around the
 * center-left while the actual panel keeps premium rounded corners.
 */

.st3-ai-shell.is-open #stereophonie-ai-drawer.st3-ai-panel {
  border-top-left-radius: 24px !important;

  border-bottom-left-radius: 24px !important;
}

/* ------------------------------------------------------------------------
   5. CLOSED HANDLE AT EXACT VIEWPORT EDGE
   ------------------------------------------------------------------------ */

/*
 * The parent's translation places this handle exactly at
 * the right edge.
 *
 * Keep its outside side flush with the viewport.
 */

.st3-ai-shell:not(.is-open) button.st3-ai-edge-tab,
.st3-ai-shell:not(.is-open) .st3-ai-edge-tab[data-st-ai-edge-launcher="true"] {
  border-top-right-radius: 0 !important;

  border-bottom-right-radius: 0 !important;

  border-right-width: 0 !important;
}

/* ------------------------------------------------------------------------
   6. REMOVE HISTORICAL PANEL/HANDLE POSITIONING CONFLICTS
   ------------------------------------------------------------------------ */

.st3-ai-shell .st3-ai-edge-tab.is-open,
.st3-ai-shell button.st3-ai-edge-tab.is-open,
.st3-ai-shell button[data-st-ai-edge-launcher="true"].is-open {
  right: auto !important;

  translate: none !important;
}

.st3-ai-shell #stereophonie-ai-drawer {
  right: 0 !important;
}

/* ------------------------------------------------------------------------
   7. PANEL SURFACE POLISH
   ------------------------------------------------------------------------ */

.st3-ai-shell #stereophonie-ai-drawer.st3-ai-panel {
  background: rgba(255, 255, 255, 0.98) !important;

  box-shadow:
    0 30px 90px rgba(29, 29, 31, 0.14),
    0 8px 28px rgba(29, 29, 31, 0.055),
    inset 0 1px 0 rgba(255, 255, 255, 0.96) !important;

  -webkit-backface-visibility: hidden;

  backface-visibility: hidden;
}

/*
 * Make sure header/footer backgrounds remain contained
 * by the restored rounded panel shape.
 */

.st3-ai-shell .st3-ai-panel__top {
  border-top-left-radius: inherit !important;

  border-top-right-radius: inherit !important;
}

.st3-ai-shell .st3-ai-disclaimer {
  border-bottom-left-radius: inherit !important;

  border-bottom-right-radius: inherit !important;
}

/* ------------------------------------------------------------------------
   8. SAFARI SMOOTHNESS
   ------------------------------------------------------------------------ */

.st3-ai-shell,
.st3-ai-shell #stereophonie-ai-drawer,
.st3-ai-shell .st3-ai-edge-tab {
  -webkit-backface-visibility: hidden;

  backface-visibility: hidden;

  transform-style: preserve-3d;
}

/* ------------------------------------------------------------------------
   9. MOBILE
   ------------------------------------------------------------------------ */

@media (max-width: 640px) {
  .st3-ai-shell {
    --st-ai-shell-right: 10px;

    --st-ai-shell-handle-width: 32px;
  }

  .st3-ai-shell #stereophonie-ai-drawer.st3-ai-panel {
    border-radius: 21px !important;

    border-top-left-radius: 21px !important;

    border-bottom-left-radius: 21px !important;

    border-top-right-radius: 21px !important;

    border-bottom-right-radius: 21px !important;
  }
}

/* ------------------------------------------------------------------------
   10. REDUCED MOTION
   ------------------------------------------------------------------------ */

@media (prefers-reduced-motion: reduce) {
  .st3-ai-shell {
    transition: none !important;
  }

  .st3-ai-shell #stereophonie-ai-drawer.st3-ai-panel {
    transition: none !important;
  }
}

