/* ==========================================================
   STEREOPHONIE SALE BADGE — EXACT NEW BREATH V2
   Sale intentionally mirrors the REAL live New badge:
   - same 2.35s rhythm
   - same glow expansion
   - same body glow
   - same easing
========================================================== */

.st-retail-card__badge--sale {
  position: relative !important;

  overflow: visible !important;

  isolation: isolate !important;

  border: 1px solid rgba(245, 179, 53, 0.52) !important;

  background: #ffffff !important;

  animation: stRealNewBadgeBody 2.35s ease-in-out infinite !important;

  transform-origin: center center !important;

  will-change: box-shadow !important;
}

/*
 * Sale text stays above its glow exactly like NEW.
 */
.st-retail-card__badge--sale > b {
  position: relative !important;

  z-index: 2 !important;

  font: inherit !important;

  font-weight: inherit !important;

  color: #1d1d1f !important;
}

/*
 * Real physical mustard breathing glow.
 *
 * This intentionally duplicates:
 * .st-retail-card__new-pulse
 */
.st-retail-card__sale-pulse {
  position: absolute !important;

  inset: -7px !important;

  border-radius: 999px !important;

  pointer-events: none !important;

  z-index: -1 !important;

  opacity: 0;

  transform: scale(0.74);

  background: rgba(245, 179, 53, 0.28);

  filter: blur(8px);

  animation: stRealNewBadgeGlow 2.35s cubic-bezier(0.42, 0, 0.2, 1) infinite !important;

  will-change: transform, opacity !important;
}

/*
 * IMPORTANT:
 * An older Sale rule hides ::before / ::after.
 * That is fine — Sale now uses its own real <i> glow layer,
 * just like the New badge.
 */
.st-retail-card__badge--sale::before,
.st-retail-card__badge--sale::after {
  display: none !important;

  content: none !important;
}

/*
 * Keep New and Sale perfectly synchronized.
 */
.st-retail-card__badge--new,
.st-retail-card__badge--sale {
  animation-duration: 2.35s !important;

  animation-timing-function: ease-in-out !important;

  animation-iteration-count: infinite !important;
}

.st-retail-card__new-pulse,
.st-retail-card__sale-pulse {
  animation-duration: 2.35s !important;

  animation-timing-function: cubic-bezier(0.42, 0, 0.2, 1) !important;

  animation-iteration-count: infinite !important;
}

/*
 * Preserve the same motion even if an older reduced-motion
 * block tries to disable only the Sale badge.
 */
@media (prefers-reduced-motion: reduce) {
  .st-retail-card__badge--sale {
    animation: stRealNewBadgeBody 2.35s ease-in-out infinite !important;
  }

  .st-retail-card__sale-pulse {
    animation: stRealNewBadgeGlow 2.35s cubic-bezier(0.42, 0, 0.2, 1) infinite !important;
  }
}

